.command-palette-overlay {
  position: fixed;
  inset: 0;
  background: rgb(22 28 31 / 0.4);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  z-index: 60;
}

.command-palette {
  width: min(560px, calc(100vw - 32px));
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-pop);
  overflow: hidden;
}

.command-palette-input {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--theme-border-subtle);
}

.command-palette-input input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font: inherit;
  font-size: 15px;
  color: var(--theme-text-primary);
}

.command-palette-input kbd {
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 11px;
  color: var(--theme-text-muted);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  padding: 2px 6px;
  white-space: nowrap;
}

.command-palette-list {
  list-style: none;
  margin: 0;
  padding: 6px;
  max-height: min(420px, 55vh);
  overflow-y: auto;
}

.command-palette-item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  font: inherit;
  font-size: 14px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  color: var(--theme-text-primary);
  cursor: pointer;
}

.command-palette-item.active,
.command-palette-item:hover {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

.command-palette-item small {
  font-size: 12px;
  color: var(--theme-text-muted);
}

.command-palette-hint {
  padding: 10px;
  font-size: 13px;
  color: var(--theme-text-muted);
}

.command-palette-describe {
  margin: 0;
  padding: 8px 14px 12px;
  font-size: 12px;
  color: var(--theme-text-muted);
  border-top: 1px solid var(--theme-border-subtle);
}

.command-palette-invalid {
  color: var(--theme-danger);
}

/* DEKOPEN Bot identity — flat 2D, modern-assistant style.
 * A solid graphite sphere with a darker bottom crescent, twin cyan capsule
 * eyes and one thin cyan orbit line that wraps front/behind the body. No
 * gradients, speculars or glow halos. Eyes carry life (pose, blink, gaze),
 * the outer arc carries job status, the orbit line is identity with subtle
 * state tints. Animations are CSS-only: no timers, free pause in background
 * tabs, one reduced-motion query. */

.orb {
  /* Sphere palette tokens live in styles/tokens.css — the identity IS the
     black orb, identical across themes; only edge stroke and specular
     strength adapt to the dark theme there. */
  display: inline-block;
  vertical-align: middle;
  flex: none;
}

.orb__ring {
  fill: none;
  stroke-width: 1.6;
  opacity: 0;
}
/* The orbital ring — thin, continuous, cyan. Back sweep is dimmed (it is
 * the far side of the orbit); the front sweep is the identity stroke and
 * passes low under the belly, never across the face. */
.orb__ribbon {
  fill: none;
  stroke: var(--orb-ribbon);
  stroke-width: 2;
  stroke-linecap: round;
}
.orb__ribbon--back {
  stroke: var(--orb-ribbon-soft);
  stroke-width: 1.6;
}
.orb__ribbon-run {
  fill: none;
  stroke: var(--orb-eye-hi);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-dasharray: 9 46;
  opacity: 0;
}
.orb__body {
  stroke: var(--orb-edge);
  stroke-width: 0.8;
}
/* Flat crescent under the belly — the only depth cue; solid fill, drawn
 * inside the silhouette so it never reaches the eyes. */
.orb__shade {
  fill: var(--orb-deep);
}
.orb__eyes--joy path {
  fill: none;
  stroke: var(--orb-eye);
  stroke-width: 1.9;
  stroke-linecap: round;
}
.orb__eyes--worry rect,
.orb__eyes--flat rect {
  fill: var(--orb-eye);
}
/* Consequential states tint the identity ribbon, not just the ring. */
.orb.is-approval .orb__ribbon {
  stroke: var(--theme-warning);
}
.orb.is-error .orb__ribbon {
  stroke: var(--theme-danger);
}
.orb.is-success .orb__ribbon {
  stroke: var(--theme-success);
}
/* Exactly one eye set per state — open by default. */
.orb__eyes--joy,
.orb__eyes--worry,
.orb__eyes--flat {
  visibility: hidden;
}
.orb.is-success .orb__eyes--joy,
.orb.is-error .orb__eyes--worry,
.orb.is-canceled .orb__eyes--flat {
  visibility: visible;
}
.orb.is-success .orb__eyes--open,
.orb.is-error .orb__eyes--open,
.orb.is-canceled .orb__eyes--open {
  visibility: hidden;
}

/* Small silhouettes: drop the crescent — at <28px it flattens the face;
 * and push the open eyes larger — at 22px the capsules fall under 3px wide
 * and the face stops reading. The orbit line stays: it IS the identity. */
.orb--s .orb__shade {
  display: none;
}
.orb--s .orb__eyes--open {
  transform: scale(1.16);
}
.orb--s .orb__ribbon {
  stroke-width: 2.4;
}
.orb--s .orb__ribbon--back {
  stroke-width: 1.9;
}

.orb__tilt,
.orb__eyes,
.orb__ring {
  transform-box: fill-box;
  transform-origin: center;
}

/* ————— hover: the orb acknowledges the pointer — a small lift and the eyes
 * sharpen; the face is alive before the user commits to a click ————— */
.orb:hover .orb__tilt,
.orb.is-hover .orb__tilt {
  animation: none;
  transform: translateY(-1.4px);
  transition: transform 160ms ease-out;
}
.orb:hover .orb__eyes,
.orb.is-hover .orb__eyes {
  animation: none;
  transform: scale(1.07);
  transition: transform 160ms ease-out;
}
.orb__tilt,
.orb__eyes {
  transition: transform 160ms ease-out;
}

/* ————— input: the user is composing — attentive, still, eyes wide and a
 * faint accent pulse on the ring: the assistant is listening ————— */
.orb.is-input .orb__tilt {
  animation: orb-breathe 3.2s ease-in-out infinite;
}
.orb.is-input .orb__eyes {
  transform: scale(1.06);
}
.orb.is-input .orb__ring {
  opacity: 1;
  stroke: var(--theme-accent);
  stroke-dasharray: 4 131;
  animation: orb-ringpulse 2.4s ease-in-out infinite;
}

/* ————— idle: slow breath + occasional blink ————— */
.orb.is-idle .orb__tilt {
  animation: orb-breathe 4.6s ease-in-out infinite;
}
.orb.is-idle .orb__eyes {
  animation: orb-blink 5.8s ease-in-out infinite;
}

/* ————— queued: half-lidded shallow breath ————— */
.orb.is-queued .orb__tilt {
  animation: orb-breathe 6.4s ease-in-out infinite;
}
.orb.is-queued .orb__eyes {
  transform: scaleY(0.6);
  animation: orb-blink-lidded 7s ease-in-out infinite;
}

/* ————— thinking: gaze pendulum ————— */
.orb.is-thinking .orb__eyes {
  animation: orb-scan 1.7s ease-in-out infinite;
}
.orb.is-thinking .orb__tilt {
  animation: orb-breathe 3.4s ease-in-out infinite;
}

/* ————— working: steady breath + accent arc orbiting + a bright segment
 * runs the front ribbon — the orbit working ————— */
.orb.is-working .orb__tilt {
  animation: orb-breathe 2.6s ease-in-out infinite;
}
.orb.is-working .orb__eyes {
  animation: orb-blink 6s ease-in-out infinite;
}
.orb.is-working .orb__ring {
  opacity: 1;
  stroke: var(--theme-accent);
  stroke-dasharray: 34 101;
  animation: orb-orbit 1.35s linear infinite;
}
.orb.is-working .orb__ribbon-run {
  opacity: 1;
  animation: orb-ribbonrun 1.5s linear infinite;
}

/* ————— waiting: raised eyes toward the human + accent arc pulse — the
 * ball is in the user's court; informational, not consequential ————— */
.orb.is-waiting .orb__tilt {
  transform: translateY(-1px) rotate(-2.5deg);
}
.orb.is-waiting .orb__eyes {
  transform: translateY(-2.4px);
  animation: orb-waitlook 5.4s ease-in-out infinite;
}
.orb.is-waiting .orb__ring {
  opacity: 1;
  stroke: var(--theme-accent);
  stroke-dasharray: 30 105;
  stroke-dashoffset: 15;
  transform: rotate(-90deg);
  animation: orb-ringpulse 2.2s ease-in-out infinite;
}

/* ————— approval: same raised look, warning arc, slower insistent pulse —
 * a consequential change is staged and nothing applies without the human ————— */
.orb.is-approval .orb__tilt {
  transform: translateY(-1px) rotate(-2.5deg);
}
.orb.is-approval .orb__eyes {
  transform: translateY(-2.4px);
  animation: orb-waitlook 5.4s ease-in-out infinite;
}
.orb.is-approval .orb__ring {
  opacity: 1;
  stroke: var(--theme-warning);
  stroke-dasharray: 30 105;
  stroke-dashoffset: 15;
  transform: rotate(-90deg);
  animation: orb-ringpulse 1.4s ease-in-out infinite;
}

/* ————— success: joy eyes + static success arc + one-shot settle ————— */
.orb.is-success .orb__ring {
  opacity: 1;
  stroke: var(--theme-success);
  stroke-dasharray: 30 105;
  stroke-dashoffset: 15;
  transform: rotate(-90deg);
}
.orb.is-success .orb__tilt {
  animation:
    orb-settle 0.55s ease-out,
    orb-breathe 4.6s ease-in-out 1s infinite;
}

/* ————— error: worried slits + danger arc + one-shot shake ————— */
.orb.is-error .orb__ring {
  opacity: 1;
  stroke: var(--theme-danger);
  stroke-dasharray: 30 105;
  stroke-dashoffset: 15;
  transform: rotate(-90deg);
}
.orb.is-error .orb__tilt {
  animation: orb-shake 0.38s ease-in-out;
}

/* ————— canceled: neutral slits, dimmed ————— */
.orb.is-canceled {
  opacity: 0.5;
}

@keyframes orb-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.028);
  }
}
@keyframes orb-blink {
  0%,
  91%,
  97%,
  100% {
    transform: scaleY(1);
  }
  94% {
    transform: scaleY(0.1);
  }
}
@keyframes orb-blink-lidded {
  0%,
  86%,
  93%,
  100% {
    transform: scaleY(0.6);
  }
  89% {
    transform: scaleY(0.12);
  }
}
@keyframes orb-scan {
  0%,
  100% {
    transform: translateX(-2.4px) scaleX(0.86);
  }
  50% {
    transform: translateX(2.4px) scaleX(0.86);
  }
}
@keyframes orb-waitlook {
  0%,
  74%,
  92%,
  100% {
    transform: translateY(-2.4px) scaleY(1);
  }
  80%,
  84% {
    transform: translateY(-2.4px) scaleY(0.12);
  }
}
@keyframes orb-orbit {
  to {
    transform: rotate(360deg);
  }
}
@keyframes orb-ribbonrun {
  to {
    stroke-dashoffset: -55;
  }
}
@keyframes orb-ringpulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}
@keyframes orb-settle {
  0% {
    transform: scale(0.92);
  }
  60% {
    transform: scale(1.06);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes orb-shake {
  0%,
  100% {
    transform: translateX(0);
  }
  30% {
    transform: translateX(-1.6px);
  }
  65% {
    transform: translateX(1.3px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .orb .orb__tilt,
  .orb .orb__eyes,
  .orb .orb__ring {
    animation: none !important;
  }
}

/* ————— BotFigure — the 96–200px welcome/empty-state figure ————— */
.bot-figure {
  display: block;
  margin-inline: auto;
}
.bot-figure__panes {
  transform-box: fill-box;
  transform-origin: center;
}
.bot-figure__shadow {
  fill: rgba(10, 18, 22, 0.28);
}
:root[data-theme="dark"] .bot-figure__shadow {
  fill: rgba(0, 0, 0, 0.5);
}
.bot-figure__body {
  stroke: var(--orb-edge);
  stroke-width: 1;
}
.bot-figure__shade {
  fill: var(--orb-deep);
}
.bot-figure__ribbon {
  fill: none;
  stroke-width: 5;
  stroke-linecap: round;
}
.bot-figure__ribbon--back {
  stroke: var(--orb-ribbon-soft);
  stroke-width: 4;
}
.bot-figure__ribbon--front {
  stroke: var(--orb-ribbon);
}
.bot-figure__ribbon-run {
  fill: none;
  stroke: var(--orb-eye-hi);
  stroke-width: 6;
  stroke-linecap: round;
  stroke-dasharray: 34 182;
  opacity: 0;
}
/* States on the figure ride the same grammar as the orb — subtle pose and
 * light changes, no invented anatomy. */
.bot-figure__tilt {
  transform-box: fill-box;
  transform-origin: center;
}
.bot-figure.is-idle .bot-figure__tilt,
.bot-figure.is-input .bot-figure__tilt {
  animation: orb-breathe 4.6s ease-in-out infinite;
}
.bot-figure.is-thinking .bot-figure__eyes,
.bot-figure.is-working .bot-figure__eyes {
  animation: orb-scan 1.9s ease-in-out infinite;
}
.bot-figure.is-working .bot-figure__ribbon-run {
  opacity: 1;
  animation: orb-figurerun 1.9s linear infinite;
}
.bot-figure.is-approval .bot-figure__ribbon,
.bot-figure.is-waiting .bot-figure__ribbon {
  stroke: var(--theme-warning);
}
.bot-figure.is-error .bot-figure__ribbon {
  stroke: var(--theme-danger);
}
.bot-figure.is-success .bot-figure__ribbon {
  stroke: var(--theme-success);
}
.bot-figure.is-canceled {
  opacity: 0.55;
}
@keyframes orb-figurerun {
  to {
    stroke-dashoffset: -216;
  }
}
@media (prefers-reduced-motion: reduce) {
  .bot-figure .bot-figure__tilt,
  .bot-figure .bot-figure__eyes,
  .bot-figure .bot-figure__ribbon-run {
    animation: none !important;
  }
  .orb .orb__ribbon-run {
    animation: none !important;
  }
}

/* Contextual Ask dock — a floating panel over the workspace corner. The
 * trigger is one quiet affordance; the panel keeps the thread inside the
 * current surface's context. */
.ask-dock {
  position: fixed;
  right: 16px;
  bottom: 40px; /* above the status bar */
  z-index: 60;
}
/* On the position editor the bottom-right corner is the inspector column —
 * and just left of it the canvas' .plan-inset/.viewport-status live. The
 * dock slides left of the inspector rail so neither is covered. */
.ask-dock--canvas {
  right: 316px;
}
.ask-dock__trigger {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 0;
  background: transparent;
  cursor: pointer;
  padding: 0;
  display: grid;
  place-items: center;
  /* The orb carries its own presence — the button is only a hit target. */
  filter: drop-shadow(0 6px 14px rgb(9 14 13 / 28%));
  transition:
    transform 0.18s ease,
    filter 0.18s ease;
}
.ask-dock__trigger:hover {
  transform: translateY(-2px) scale(1.04);
  filter: drop-shadow(0 10px 18px rgb(9 14 13 / 34%));
}
.ask-dock__trigger:focus-visible {
  outline: 2px solid var(--theme-accent, #0f817a);
  outline-offset: 3px;
}
.ask-dock__panel {
  width: 340px;
  max-height: 480px;
  display: flex;
  flex-direction: column;
  background: var(--theme-surface-panel, #ffffff);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  box-shadow: 0 8px 32px rgb(0 0 0 / 18%);
  overflow: hidden;
}
.ask-dock__header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__title {
  font-weight: 600;
  font-size: 13px;
  flex: 1;
}
.ask-dock__surface {
  font-size: 11px;
  color: var(--theme-text-muted, #5c6c68);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 1px 8px;
}
.ask-dock__close {
  border: 0;
  background: none;
  font-size: 18px;
  cursor: pointer;
  color: var(--theme-text-muted, #5c6c68);
}
.ask-dock__thread {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 80px;
}
.ask-dock__hint {
  color: var(--theme-text-muted, #5c6c68);
  font-size: 12.5px;
  margin: 6px 0;
}
.ask-dock__turn {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.ask-dock__question {
  font-size: 12.5px;
  font-weight: 600;
  margin: 0;
}
.ask-dock__answer {
  font-size: 12.5px;
  margin: 0;
  white-space: pre-wrap;
}
.ask-dock__warnings {
  margin: 0;
  padding-left: 16px;
  font-size: 12px;
  color: var(--theme-warning, #b25e09);
}
.ask-dock__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ask-dock__action {
  font-size: 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-accent-soft, #e4f3f1);
  border-radius: 999px;
  padding: 3px 10px;
  cursor: pointer;
}
.ask-dock__meta {
  font-size: 10.5px;
  color: var(--theme-text-muted, #5c6c68);
  margin: 2px 0 0;
}
.ask-dock__busy {
  font-size: 12px;
  color: var(--theme-text-muted, #5c6c68);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.ask-dock__error {
  font-size: 12px;
  color: var(--theme-danger, #b3372f);
  margin: 0;
  padding: 0 10px 6px;
}
.ask-dock__offline {
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
  background: var(--theme-warning-soft, #fdf3e3);
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  margin: 0;
  padding: 6px 10px;
}
.ask-dock__chips {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px 0;
}
.ask-dock__chip {
  font-size: 11.5px;
  text-align: left;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-secondary, #33443f);
  border-radius: 8px;
  padding: 5px 10px;
  cursor: pointer;
}
.ask-dock__chip:hover {
  border-color: var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
}
.ask-dock__pending {
  margin: 0;
  padding: 6px 10px;
  list-style: none;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  font-size: 12px;
  color: var(--theme-text-secondary, #57635f);
}
.ask-dock__pending li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 3px 0;
}
.ask-dock__pending li span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ask-dock__pending li button {
  border: 0;
  background: transparent;
  color: var(--theme-text-tertiary, #8a948f);
  cursor: pointer;
  font-size: 13px;
  padding: 0 4px;
}
.ask-dock__form {
  display: flex;
  gap: 6px;
  padding: 8px 10px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__form input {
  flex: 1;
  font-size: 13px;
  padding: 7px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__form button {
  font-size: 13px;
  padding: 7px 14px;
  border: 0;
  border-radius: 8px;
  background: var(--theme-accent, #0f817a);
  color: var(--theme-surface-panel);
  cursor: pointer;
}
.ask-dock__form button:disabled {
  opacity: 0.5;
  cursor: default;
}
.ask-dock__modes {
  display: inline-flex;
  gap: 2px;
  margin-left: 6px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  padding: 1px;
}
.ask-dock__mode {
  font-size: 11px;
  padding: 2px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--theme-text-secondary, #576664);
  cursor: pointer;
}
.ask-dock__mode--active {
  background: var(--theme-accent, #0f817a);
  color: var(--theme-surface-panel);
}
.ask-dock__queries {
  margin: 4px 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.ask-dock__queries li {
  font-size: 10.5px;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--theme-surface-inset, #f0f4f3);
  color: var(--theme-text-secondary, #576664);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__ops {
  display: flex;
  flex-direction: column;
  gap: 4px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  padding: 6px 8px;
}
.ask-dock__ops ul {
  margin: 0;
  padding-left: 16px;
  font-size: 12px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__ops .ask-dock__action {
  align-self: flex-start;
}
.ask-dock__action--prepare {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
}

/* §08-WC batch edit diff — one row per affected position, applied through
   the canonical save after the human confirms. */
.ask-dock__batch ul {
  padding-left: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
}
.ask-dock__batch-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 4px 10px;
  align-items: baseline;
  padding: 3px 0;
  border-top: 1px dashed var(--theme-border-subtle, #d9dfde);
}
.ask-dock__batch-row:first-child {
  border-top: 0;
}
.ask-dock__batch-where {
  font-weight: 600;
  white-space: nowrap;
}
.ask-dock__batch-ops {
  color: var(--theme-text-secondary, #576664);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ask-dock__batch-cost {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ask-dock__batch-row.is-applied .ask-dock__batch-cost {
  color: var(--theme-accent, #0f817a);
  font-weight: 600;
}
.ask-dock__batch-row.is-failed .ask-dock__batch-cost,
.ask-dock__batch-row.is-apply_failed .ask-dock__batch-cost {
  color: var(--theme-danger, #b3261e);
}
.ask-dock__batch-row.is-unsupported {
  color: var(--theme-text-muted, #8a9493);
}
.ask-dock__batch-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  padding-top: 6px;
  font-size: 12px;
  color: var(--theme-text-secondary, #576664);
}
.ask-dock__form textarea {
  flex: 1;
  font-size: 13px;
  padding: 7px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-primary, #1f2a29);
  resize: none;
  font-family: inherit;
}

/* ---- §07-H assistant workspace ----------------------------------- */
.aiws {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr) 300px;
  gap: 0;
  /* The workspace IS the window: bounded to the viewport minus the 46px
   * topbar and the .workspace padding (1.5rem × 2) so the transcript scrolls
   * inside — never the page, which would scroll the composer and rail off. */
  height: calc(100vh - 46px - 3rem);
  min-height: 0;
}
.aiws-rail {
  border-right: 1px solid var(--theme-border-subtle, #d9dfde);
  overflow-y: auto;
  padding: 12px;
}
.aiws-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.aiws-rail__head h2 {
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0;
}
.aiws-joblist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.aiws-job {
  width: 100%;
  text-align: left;
  border: 1px solid transparent;
  background: none;
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.aiws-job:hover {
  background: var(--theme-surface-raised, #f2f5f4);
}
.aiws-job--active {
  border-color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.08));
}
.aiws-job__goal {
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.aiws-job__meta {
  font-size: 11px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-state {
  display: inline-block;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--theme-surface-raised, #f2f5f4);
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-state[data-state="running"],
.aiws-state[data-state="queued"],
.aiws-state[data-state="planning"] {
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.12));
  color: var(--theme-accent-deep);
}
.aiws-state[data-state="waiting-for-user"],
.aiws-state[data-state="waiting-for-approval"] {
  background: rgba(196, 141, 41, 0.15);
  color: var(--theme-warning);
}
.aiws-state[data-state="succeeded"] {
  background: rgba(46, 125, 79, 0.14);
  color: var(--theme-success);
}
.aiws-state[data-state="failed"],
.aiws-state[data-state="failed-retryable"] {
  background: rgba(180, 45, 45, 0.12);
  color: var(--theme-danger);
}
.aiws-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.aiws-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-head > div {
  flex: 1;
}
.aiws-head h1 {
  font-size: 15px;
  margin: 0 0 4px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-head__meta {
  font-size: 11px;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0;
}
.aiws-transcript {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.aiws-turn--user {
  align-self: flex-end;
  max-width: 72%;
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.1));
  border-radius: 12px 12px 4px 12px;
  padding: 8px 12px;
  margin: 0;
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
  white-space: pre-wrap;
}
.aiws-turn--agent {
  max-width: 84%;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.aiws-turn--agent .orb {
  margin-top: 1px;
}
.aiws-turn__body {
  flex: 1;
  min-width: 0;
}
.aiws-plan {
  margin: 0 0 8px;
  padding-left: 20px;
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-reply {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--theme-text-primary, #1f2a29);
  white-space: pre-wrap;
}
.aiws-questions {
  margin-top: 8px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-warning);
  background: rgba(196, 141, 41, 0.08);
  border-radius: 0 8px 8px 0;
}
.aiws-questions p {
  margin: 0;
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-warnings {
  margin: 8px 0 0;
  padding-left: 18px;
  font-size: 12px;
  color: var(--theme-danger);
}
.aiws-toggle {
  margin-top: 8px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 999px;
  font-size: 11px;
  padding: 3px 10px;
  cursor: pointer;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-work {
  margin-top: 6px;
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
  border-left: 2px solid var(--theme-border-subtle, #d9dfde);
  padding-left: 10px;
}
.aiws-work ul {
  margin: 4px 0;
  padding-left: 16px;
}
.aiws-claims small {
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.aiws-action {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
  background: none;
  border-radius: 999px;
  font-size: 11px;
  padding: 4px 12px;
  cursor: pointer;
}
.aiws-action--static {
  border-color: var(--theme-border-subtle, #d9dfde);
  color: var(--theme-text-secondary, #4b5f5c);
  cursor: default;
}
.aiws-artifacts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.aiws-artifact {
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #fff);
  border-radius: 10px;
  padding: 8px 12px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
}
.aiws-artifact:hover {
  border-color: var(--theme-accent, #0f817a);
}
.aiws-artifact strong {
  font-size: 12px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-artifact small {
  font-size: 10px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-live {
  font-size: 12px;
  color: var(--theme-accent, #0f817a);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.aiws-hero {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 8px;
}
.aiws-hero__title {
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0 0 4px;
}
.aiws-error {
  margin: 0 18px 8px;
  font-size: 12px;
  color: var(--theme-danger);
}
.aiws-composer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding: 12px 18px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-composer .orb {
  align-self: center;
  flex-shrink: 0;
}
.aiws-composer select {
  font-size: 12px;
  padding: 6px 8px;
  max-width: 11rem;
  min-width: 0;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #fff);
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-composer textarea {
  flex: 1 1 10rem;
  min-width: 0;
  font-size: 13px;
  padding: 8px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #fff);
  color: var(--theme-text-primary, #1f2a29);
  resize: none;
  font-family: inherit;
}
.aiws-inspector {
  border-left: 1px solid var(--theme-border-subtle, #d9dfde);
  overflow-y: auto;
  padding: 14px;
}
.aiws-artifact-detail h2 {
  font-size: 13px;
  margin: 0 0 4px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-evidence {
  font-size: 11px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-payload {
  font-size: 11px;
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 8px;
  padding: 10px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.aiws-empty {
  font-size: 13px;
  color: var(--theme-text-tertiary, #7b8a88);
  padding: 8px;
}
@media (max-width: 1100px) {
  .aiws {
    grid-template-columns: 210px minmax(0, 1fr);
  }
  .aiws-inspector {
    display: none;
  }
}

.aiws-tool {
  display: inline-block;
  margin-right: 6px;
  padding: 0 6px;
  border: 1px solid var(--line-strong, #d0d5dd);
  border-radius: 4px;
  background: var(--surface-sunken, #f2f4f7);
  color: var(--text-subtle, #667085);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10.5px;
  font-weight: 500;
}
.aiws-action .aiws-tool {
  margin-right: 0;
  margin-left: 6px;
}

/* §08 measurement — apply/decline pair + workspace metrics strip. */
.ask-dock__ops-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}
.ask-dock__ops-actions .ask-dock__action {
  align-self: auto;
}
.ask-dock__action--ghost {
  background: transparent;
  color: var(--theme-text-secondary, #576664);
  border-style: dashed;
}
.aiws-metrics {
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 12px;
  background: var(--theme-surface-panel, #ffffff);
}
.aiws-metrics h2 {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--theme-text-secondary, #576664);
  margin: 0 0 8px;
  display: flex;
  gap: 8px;
  align-items: baseline;
}
.aiws-metrics h2 small {
  font-weight: 400;
  text-transform: none;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-metrics dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px 12px;
  margin: 0;
}
.aiws-metrics dl > div {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.aiws-metrics dt {
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-metrics dd {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--theme-text-primary, #1f2a29);
  font-variant-numeric: tabular-nums;
}
.aiws-metrics__failure {
  margin: 8px 0 0;
  font-size: 11px;
  color: var(--theme-danger, #b3372f);
}

.aiws-head__actions {
  display: flex;
  flex-shrink: 0;
  gap: 0.5rem;
  margin-left: auto;
}

/* ——— Artifact chips in the dock ——— */
.ask-dock__artifacts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ask-dock__artifact {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-soft, #e4f3f1);
  border-radius: 999px;
  font-size: 11px;
  padding: 3px 10px;
  cursor: pointer;
}

/* ——— Typed artifact rendering (workspace inspector) ——— */
.art {
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.art-message .art-field {
  display: flex;
  gap: 8px;
  margin: 0 0 4px;
  font-size: 12px;
}
.art-message .art-field span {
  color: var(--theme-text-tertiary, #7b8a88);
  min-width: 52px;
}
.art-body {
  margin: 8px 0 0;
  padding: 10px 12px;
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 8px;
  white-space: pre-wrap;
  font-size: 12.5px;
  line-height: 1.5;
}
.art-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.art-checklist li {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.art-checklist small {
  color: var(--theme-text-tertiary, #7b8a88);
}
.art-pill {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: 999px;
  padding: 1px 8px;
  flex: none;
}
.art-pill[data-tone="ok"] {
  background: var(--theme-success-soft, #e3f2ea);
  color: var(--theme-success, #1e7a4c);
}
.art-pill[data-tone="bad"] {
  background: var(--theme-danger-soft, #fbe9e7);
  color: var(--theme-danger, #b3372f);
}
.art-pill[data-tone="warn"] {
  background: var(--theme-warning-soft, #fdf1e3);
  color: var(--theme-warning, #9c5306);
}
.art-totals {
  display: flex;
  gap: 14px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  font-size: 12px;
}
.art-group {
  margin-bottom: 12px;
}
.art-group h3,
.art-group-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0 0 6px;
}
.art-count {
  color: var(--theme-text-tertiary, #7b8a88);
}
.art-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.art-lines li {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.art-lines li small,
.art-lines li span {
  color: var(--theme-text-secondary, #4b5f5c);
}
.art-lines--numbered {
  list-style: decimal;
  padding-left: 18px;
}
.art-line-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.art-note {
  margin: 6px 0 0;
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.art-kv {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.art-kv-row {
  display: grid;
  grid-template-columns: minmax(90px, 140px) 1fr;
  gap: 8px;
  font-size: 12px;
  align-items: baseline;
}
.art-kv-row dt {
  color: var(--theme-text-secondary, #4b5f5c);
  text-transform: capitalize;
}
.art-kv-row dd {
  margin: 0;
}
.art-empty {
  margin: 0;
  color: var(--theme-text-tertiary, #7b8a88);
  font-size: 12px;
}

/* --- live run progress, waiting banner, artifact shelf, rail identity --- */
.aiws-progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 18px;
  padding: 7px 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  background: var(--theme-surface-panel, #fff);
}
.aiws-progress__label {
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.aiws-waiting {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 18px;
  padding: 10px 14px;
  border: 1px solid var(--theme-warning, #c48d29);
  border-radius: 10px;
  background: rgba(196, 141, 41, 0.08);
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-shelf {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 0 18px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-shelf__label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-shelf__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #fff);
  border-radius: 999px;
  padding: 4px 12px 4px 6px;
  font-size: 12px;
  cursor: pointer;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-shelf__item:hover {
  border-color: var(--theme-accent, #0f817a);
}
.aiws-job {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.aiws-job .orb {
  margin-top: 2px;
}
.aiws-job__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  text-align: left;
}
.aiws-replay {
  display: inline-block;
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 0 8px;
}
.aiws-turn--error {
  max-width: 84%;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.aiws-error__text {
  margin: 0;
  font-size: 13px;
  color: var(--theme-danger, #b3413a);
}
.aiws-error__text .aiws-tool {
  margin-left: 8px;
}
.aiws-step {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  background: var(--theme-surface-raised, #f2f5f4);
}
.aiws-step__ops {
  margin: 0;
  padding-left: 18px;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-step__settled {
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-steps--live {
  flex-direction: column;
  align-items: stretch;
}
.aiws-warnings--rejected {
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-artifact {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
}
.aiws-artifact strong {
  font-size: 13px;
}
.aiws-artifact small {
  font-size: 11px;
  color: var(--theme-text-tertiary, #7b8a88);
}

/* --- dock continuity: replay mark, error turn, questions, meta link --- */
.ask-dock__replay {
  display: inline-block;
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 0 8px;
}
.ask-dock__errorTurn {
  margin-top: 4px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-danger, #b3413a);
  background: rgba(179, 65, 58, 0.07);
  border-radius: 0 8px 8px 0;
}
.ask-dock__errorTurn p {
  margin: 0 0 6px;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__errorTurn code {
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.ask-dock__questions {
  margin-top: 8px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-warning, #c48d29);
  background: rgba(196, 141, 41, 0.08);
  border-radius: 0 8px 8px 0;
}
.ask-dock__questions p {
  margin: 0;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__meta-link {
  border: none;
  background: none;
  padding: 0;
  font: inherit;
  font-size: 11px;
  color: var(--theme-accent, #0f817a);
  cursor: pointer;
  text-decoration: underline;
}
.ask-dock__meta-link:hover {
  text-decoration: none;
}

/* Mobile: the dock is the customer/operator surface — full-width panel,
 * clear of the canvas inspector offset that only exists on desktop. */
@media (max-width: 640px) {
  .ask-dock,
  .ask-dock--canvas {
    right: 8px;
    bottom: 8px;
  }
  .ask-dock__panel {
    width: calc(100vw - 16px);
    max-height: 72vh;
  }
}

/* Bot welcome — the figure on first-open empty states. */
.ask-dock__welcome {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 0.75rem 0.75rem;
  text-align: center;
}

.landing {
  background: var(--theme-bg-canvas);
  color: var(--theme-fg-primary);
  min-height: 100vh;
}

.landing-top {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  justify-content: space-between;
  padding: 0.875rem clamp(1rem, 4vw, 3rem);
  position: sticky;
  top: 0;
  background: var(--theme-bg-canvas);
  z-index: 10;
}

.landing-brand .brand {
  font-weight: 700;
  letter-spacing: 0.06em;
}

.landing-brand .brand-os {
  color: var(--theme-fg-muted);
  font-size: 0.75rem;
  margin-left: 0.35rem;
}

.landing-hero {
  display: grid;
  gap: 2rem;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  padding: clamp(2rem, 6vw, 5rem) clamp(1rem, 4vw, 3rem);
  align-items: center;
}

.landing-hero__copy h1 {
  font-size: clamp(1.9rem, 3.4vw, 3rem);
  line-height: 1.12;
  letter-spacing: -0.015em;
  margin: 0 0 1rem;
}

.landing-hero__lead {
  color: var(--theme-fg-secondary);
  font-size: 1.075rem;
  line-height: 1.55;
  margin: 0 0 1.5rem;
  max-width: 34rem;
}

.landing-hero__actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.landing-hero__note {
  align-items: center;
  color: var(--theme-fg-muted);
  display: flex;
  font-size: 0.875rem;
  gap: 0.5rem;
  margin-top: 1.75rem;
}

.landing-hero__shot {
  margin: 0;
}

.landing-hero__shot img,
.landing-section__shot img {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  box-shadow: 0 18px 48px -20px rgb(15 24 30 / 0.28);
  display: block;
  height: auto;
  width: 100%;
}

.landing-hero__shot figcaption {
  color: var(--theme-fg-muted);
  font-size: 0.8rem;
  margin-top: 0.5rem;
  text-align: center;
}

.landing-sections {
  display: grid;
  gap: clamp(2.5rem, 6vw, 4.5rem);
  padding: 0 clamp(1rem, 4vw, 3rem) clamp(2.5rem, 6vw, 4.5rem);
}

.landing-section {
  align-items: center;
  display: grid;
  gap: clamp(1.25rem, 3vw, 2.5rem);
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
}

.landing-section--flip .landing-section__shot {
  order: 2;
}

.landing-section--flip .landing-section__copy {
  order: 1;
}

.landing-section__shot {
  margin: 0;
}

.landing-section__copy h2 {
  font-size: 1.5rem;
  margin: 0 0 0.75rem;
}

.landing-section__copy p {
  color: var(--theme-fg-secondary);
  line-height: 1.6;
  margin: 0;
}

.landing-assistant {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  display: grid;
  gap: 1.5rem;
  grid-template-columns: auto minmax(0, 5fr) minmax(0, 6fr);
  padding: clamp(2rem, 5vw, 4rem) clamp(1rem, 4vw, 3rem);
}

.landing-assistant h2 {
  font-size: 1.25rem;
  margin: 0 0 0.5rem;
}

.landing-assistant p {
  color: var(--theme-fg-secondary);
  line-height: 1.6;
  margin: 0;
}

.landing-foot {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  color: var(--theme-fg-muted);
  display: flex;
  font-size: 0.85rem;
  justify-content: space-between;
  padding: 1.25rem clamp(1rem, 4vw, 3rem);
}

@media (max-width: 860px) {
  .landing-hero,
  .landing-section,
  .landing-assistant {
    grid-template-columns: 1fr;
  }

  .landing-section--flip .landing-section__shot {
    order: 0;
  }

  .landing-hero__copy h1 {
    font-size: 1.85rem;
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
  margin: 0;
}

body {
  background: var(--theme-bg-canvas);
  color: var(--theme-text-primary);
  font-family:
    "IBM Plex Sans",
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    sans-serif;
  font-size: 0.8125rem;
  line-height: 1.35;
}

button,
input {
  color: inherit;
  font: inherit;
}

button,
input,
a {
  border-radius: 0.3125rem;
}

button {
  border: 1px solid var(--theme-border-subtle);
  background: var(--theme-surface-card);
  cursor: pointer;
  padding: 0.5rem 0.75rem;
}

button:hover,
a:hover {
  background: var(--theme-surface-hover);
}

button:focus-visible,
input:focus-visible,
a:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 2px;
}

/* The light-theme accent reads dim on dark surfaces — use the stronger
 * accent token so keyboard focus stays visible in the dark theme. */
:root[data-theme="dark"] button:focus-visible,
:root[data-theme="dark"] input:focus-visible,
:root[data-theme="dark"] a:focus-visible {
  outline-color: var(--theme-accent-strong);
}

.auth-screen {
  align-items: center;
  background: var(--theme-bg-canvas);
  display: flex;
  justify-content: center;
  min-height: 100vh;
  padding: 2rem;
}

.auth-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  display: grid;
  gap: 1rem;
  max-width: 28rem;
  padding: 2rem;
  width: 100%;
}

.auth-card form {
  display: grid;
  gap: 0.5rem;
}

.auth-card input {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.75rem;
}

.auth-card__brand {
  align-items: baseline;
  display: flex;
  gap: 0.5rem;
}

.auth-card__brand .brand-os {
  color: var(--theme-text-muted);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.auth-card__header {
  display: grid;
  gap: 0.25rem;
}

.auth-card__header h1 {
  font-size: var(--text-title);
  margin: 0;
}

.auth-hint {
  color: var(--theme-text-secondary);
  margin: 0;
}

.auth-form {
  display: grid;
  gap: 0.5rem;
}

.auth-notice {
  border-radius: 0.375rem;
  font-size: 0.75rem;
  margin: 0;
  padding: 0.5rem 0.75rem;
}

.auth-notice--ok {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}

.auth-notice--error {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

.auth-qr {
  align-self: center;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  max-width: 10rem;
}

.org-option {
  align-items: center;
  display: flex;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  text-align: left;
  width: 100%;
}

.org-option:disabled {
  cursor: wait;
  opacity: 0.7;
}

.org-option__glyph {
  align-items: center;
  background: var(--theme-accent-soft);
  border-radius: 0.375rem;
  color: var(--theme-accent-ink);
  display: inline-flex;
  font-weight: 600;
  height: 2rem;
  justify-content: center;
  width: 2rem;
}

.org-option__meta {
  display: grid;
  flex: 1;
  min-width: 0;
}

.org-option__sub {
  color: var(--theme-text-muted);
  font-size: 0.6875rem;
}

/* ——— Onboarding ——— */
.onboarding {
  display: grid;
  gap: var(--space-4);
  margin: 0 auto;
  max-width: 46rem;
  padding: var(--space-6) var(--space-4);
}

.onboarding-head {
  display: grid;
  gap: 0.25rem;
}

.onboarding-head h1 {
  font-size: var(--text-display);
  margin: 0;
}

.onboarding-sub {
  color: var(--theme-text-secondary);
  margin: 0;
}

.onboarding-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* Steps read as a sequence, not loose pills — each li carries a chevron
 * connector into the next step (review m13). */
.onboarding-step {
  align-items: center;
  display: flex;
}

.onboarding-step:not(:last-child)::after {
  color: var(--theme-text-muted);
  content: "›";
}

.onboarding-step button {
  align-items: center;
  /* A visible border + primary text keeps upcoming steps from reading as
   * disabled controls (hostile m2). */
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  color: var(--theme-text-primary);
  display: flex;
  gap: 0.375rem;
  padding: 0.25rem 0.5rem;
}

.onboarding-step.is-current button {
  border-color: var(--theme-accent);
  color: var(--theme-accent-ink);
  font-weight: 600;
}

.onboarding-step.is-done button {
  color: var(--theme-success);
}

.onboarding-step.is-done .onboarding-step__index {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}

.onboarding-step__index {
  align-items: center;
  background: var(--theme-surface-card);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 50%;
  display: inline-flex;
  font-size: 0.625rem;
  font-weight: 600;
  height: 1.25rem;
  justify-content: center;
  width: 1.25rem;
}

.onboarding-panel {
  display: grid;
  gap: var(--space-3);
}

.onboarding-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  display: grid;
  gap: var(--space-3);
  padding: var(--space-5);
}

.onboarding-card h2 {
  font-size: 1rem;
  margin: 0;
}

.onboarding-org {
  align-items: center;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
}

.onboarding-systems {
  display: grid;
  gap: 0.5rem;
}

.onboarding-system {
  align-items: center;
  display: flex;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  text-align: left;
  width: 100%;
}

.onboarding-system.is-picked,
.onboarding-choice__card.is-picked {
  border-color: var(--theme-accent);
  box-shadow: 0 0 0 1px var(--theme-accent);
}

.onboarding-system__meta {
  display: grid;
  flex: 1;
  min-width: 0;
}

.onboarding-choice {
  display: grid;
  gap: 0.5rem;
  grid-template-columns: 1fr 1fr;
}

.onboarding-choice__card {
  align-items: flex-start;
  display: grid;
  gap: 0.375rem;
  padding: 0.75rem;
  text-align: left;
}

.onboarding-choice__card span {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.onboarding-note {
  border-top: 1px dashed var(--theme-border-subtle);
  color: var(--theme-text-secondary);
  margin: 0;
  padding-top: var(--space-3);
}

.onboarding-link {
  justify-self: start;
}

.onboarding-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: space-between;
}

.dashboard-empty__actions {
  display: flex;
  gap: 0.5rem;
}

@media (max-width: 640px) {
  .onboarding-choice {
    grid-template-columns: 1fr;
  }
}

.eyebrow {
  color: var(--theme-text-secondary);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.organization-list {
  display: grid;
  gap: 0.5rem;
}

.organization-list button {
  display: flex;
  justify-content: space-between;
}

/* ——— Application shell: domain rail + work body ——— */
.app-shell {
  background: var(--theme-bg-canvas);
  display: flex;
  min-height: 100vh;
}

.app-rail {
  background: var(--theme-surface-panel);
  border-right: 1px solid var(--theme-border-subtle);
  display: flex;
  flex-direction: column;
  flex: 0 0 auto;
  height: 100vh;
  position: sticky;
  top: 0;
  width: 14.5rem;
}

.app-rail__brand {
  border-bottom: 1px solid var(--theme-border-subtle);
  padding: 0.625rem var(--space-4);
}

.app-rail__nav {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--space-4);
  overflow-y: auto;
  padding: var(--space-2) var(--space-2) var(--space-4);
}

.rail-group__title {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.07em;
  margin: 0 var(--space-2) var(--space-1);
  padding-top: var(--space-2);
  text-transform: uppercase;
}

.rail-item {
  align-items: center;
  border-left: 2px solid transparent;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  color: var(--theme-text-secondary);
  display: flex;
  font-size: var(--text-body);
  font-weight: 500;
  gap: var(--space-2);
  min-height: 36px;
  padding: var(--space-1) var(--space-2) var(--space-1) calc(var(--space-2) - 2px);
  text-decoration: none;
}

.rail-item__icon {
  color: var(--theme-text-muted);
  flex: 0 0 auto;
}

.rail-item:hover .rail-item__icon,
.rail-item.active .rail-item__icon {
  color: currentColor;
}

.rail-item:hover {
  background: var(--theme-surface-hover);
  color: var(--theme-text-primary);
}

.rail-item.active {
  background: var(--theme-accent-soft);
  border-left-color: var(--theme-accent);
  color: var(--theme-accent-ink);
  font-weight: 600;
}

.rail-item:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: -2px;
}

.rail-context {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.rail-context__back {
  align-items: center;
  color: var(--theme-text-muted);
  display: flex;
  font-size: var(--text-s);
  margin: 0 var(--space-2) var(--space-1);
  min-height: 24px;
  text-decoration: none;
}

.rail-context__back:hover {
  color: var(--theme-text-primary);
}

.rail-context__title {
  border-bottom: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0 var(--space-2) var(--space-2);
  padding-bottom: var(--space-2);
}

.app-rail__user {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
}

.app-rail__identity {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.app-rail__email {
  font-size: var(--text-s);
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-rail__role {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
}

.app-rail__user-actions {
  display: flex;
  gap: var(--space-1);
}

.rail-icon-button {
  align-items: center;
  background: none;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  color: var(--theme-text-secondary);
  display: inline-flex;
  height: 26px;
  justify-content: center;
  width: 26px;
}

.rail-icon-button:hover {
  border-color: var(--theme-border-subtle);
  color: var(--theme-text-primary);
}

.app-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.app-topbar {
  align-items: center;
  background: var(--theme-surface-panel);
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  min-height: 46px;
  padding: 0 var(--space-3);
  position: sticky;
  top: 0;
  z-index: 30;
}

.app-topbar__actions {
  align-items: center;
  display: flex;
  gap: var(--space-2);
}

.topbar-search {
  align-items: center;
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  color: var(--theme-text-secondary);
  display: inline-flex;
  font-size: var(--text-s);
  gap: var(--space-2);
  min-height: 28px;
  padding: 0 var(--space-2);
}

.topbar-search:hover {
  border-color: var(--theme-border-strong);
  color: var(--theme-text-primary);
}

.topbar-search kbd {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 0.625rem;
  padding: 0 0.25rem;
}

.topbar-button {
  align-items: center;
  background: none;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  color: var(--theme-text-secondary);
  display: inline-flex;
  font-size: var(--text-s);
  gap: var(--space-1);
  min-height: 28px;
  padding: 0 var(--space-2);
  position: relative;
}

.topbar-button:hover {
  border-color: var(--theme-border-strong);
  color: var(--theme-text-primary);
}

.topbar-button--icon {
  justify-content: center;
  padding: 0;
  width: 28px;
}

.topbar-button__chevron {
  color: var(--theme-text-muted);
  font-size: 0.625rem;
}

.topbar-ai {
  border-color: var(--theme-accent);
  color: var(--theme-accent-ink);
  font-weight: 600;
}

.topbar-ai:hover {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

/* The job chip sits beside the orb: the orb always opens the dock, this
   reaches the most-pressing job directly. */
.topbar-ai-job {
  border-color: var(--theme-warning);
  color: var(--theme-warning);
  font-size: var(--text-xs);
  font-weight: 600;
}

.topbar-ai-job:hover {
  background: var(--theme-warning-soft);
}

/* ——— floating shell menus (switchers + notifications) ——— */
.org-switcher,
.project-switcher,
.attention-bell {
  position: relative;
}

.org-switcher {
  padding: 0 var(--space-2) var(--space-2);
}

.org-switcher__current {
  align-items: center;
  background: var(--theme-surface-card);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  justify-content: space-between;
  gap: var(--space-2);
  min-height: 34px;
  padding: var(--space-1) var(--space-2);
  text-align: left;
  width: 100%;
}

.org-switcher__current:disabled {
  cursor: default;
}

.org-switcher__name {
  font-size: var(--text-s);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.org-switcher__role {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
}

.org-switcher__chevron {
  color: var(--theme-text-muted);
  font-size: 0.625rem;
}

.shell-menu {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-pop);
  left: 0;
  list-style: none;
  margin: 0;
  min-width: 17rem;
  padding: var(--space-1);
  position: absolute;
  top: calc(100% + 6px);
  z-index: 50;
}

.shell-menu--right {
  left: auto;
  right: 0;
}

.shell-menu__title {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.06em;
  margin: 0;
  padding: var(--space-2) var(--space-2) var(--space-1);
  text-transform: uppercase;
}

.shell-menu__item {
  align-items: center;
  background: none;
  border-radius: var(--radius-md);
  color: var(--theme-text-primary);
  display: flex;
  font-size: var(--text-body);
  gap: var(--space-2);
  justify-content: space-between;
  padding: var(--space-2);
  text-align: left;
  width: 100%;
}

.shell-menu__item:hover {
  background: var(--theme-surface-hover);
}

.shell-menu__item--warn {
  color: var(--theme-warning);
}

.shell-menu__meta {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
  padding: var(--space-1) var(--space-2);
}

.shell-menu__all {
  border-top: 1px solid var(--theme-border-subtle);
  color: var(--theme-accent-strong);
  display: block;
  font-size: var(--text-sm);
  font-weight: 600;
  margin-top: var(--space-1);
  padding: var(--space-2);
}

.shell-menu__all:hover {
  background: var(--theme-surface-hover);
  border-radius: var(--radius-md);
}

.attention-bell__badge {
  align-items: center;
  background: var(--theme-danger);
  border-radius: var(--radius-pill);
  color: var(--theme-danger-ink);
  display: inline-flex;
  font-size: 0.5625rem;
  font-weight: 700;
  height: 14px;
  justify-content: center;
  min-width: 14px;
  padding: 0 4px;
  position: absolute;
  right: -4px;
  top: -4px;
}

.brand {
  align-items: center;
  color: var(--theme-accent-ink);
  display: flex;
  font-size: 0.8125rem;
  font-weight: 700;
  gap: 0.375rem;
  letter-spacing: 0.02em;
}

.brand::before {
  background: var(--theme-mark);
  border-radius: 0.125rem;
  content: "";
  display: inline-block;
  height: 0.625rem;
  width: 0.625rem;
}

.context-title {
  color: var(--theme-text-secondary);
  flex: 1;
  font-weight: 600;
}

.crumbs__list {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  list-style: none;
  margin: 0;
  min-height: 2.25rem;
  padding: 0;
}

.crumbs__item {
  align-items: center;
  display: flex;
  font-size: var(--text-xs);
  gap: 0.375rem;
}

.crumbs__sep {
  color: var(--theme-text-muted);
}

.crumbs__link {
  align-items: center;
  color: var(--theme-text-secondary);
  display: inline-flex;
  /* WCAG 2.5.8 — 24 px click box; visual glyphs stay small. */
  min-height: 24px;
  text-decoration: none;
}

.crumbs__link:hover {
  color: var(--theme-accent-ink);
  text-decoration: underline;
}

.crumbs__current {
  color: var(--theme-text-primary);
  font-weight: 500;
}

.workspace {
  background: var(--theme-bg-canvas);
  flex: 1;
  /* The single outer gutter for every surface — pages inside do not add
   * their own, so all routes read at the same distance from the edge. */
  padding: 1.5rem;
}

.workspace:focus-visible {
  outline: none;
}

.skip-link {
  background: var(--theme-accent);
  border-radius: 0 0 0.375rem 0;
  color: var(--theme-accent-ink);
  font-size: 0.85rem;
  font-weight: 600;
  left: 0;
  padding: 0.5rem 0.875rem;
  position: fixed;
  top: 0;
  transform: translateY(-110%);
  transition: transform 0.15s ease;
  z-index: 100;
}

.skip-link:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 2px;
  transform: translateY(0);
}

.placeholder {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  max-width: 48rem;
  padding: 2rem;
}

[role="alert"] {
  color: var(--theme-danger);
}

/* Standalone denial/error notices (a bare <p role="alert"> returned instead
   of page content) must read as a designed state, not a stray red line. */
p[role="alert"]:only-child {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-danger);
  border-radius: var(--radius-md);
  color: var(--theme-text-primary);
  margin: 1.5rem 0;
  max-width: 34rem;
  padding: 1rem 1.25rem;
}

p[role="alert"]:only-child::before {
  content: "⚠ ";
  color: var(--theme-danger);
}

.primary-action {
  background: var(--theme-accent);
  border-radius: 0.3125rem;
  color: var(--theme-surface-panel);
  display: inline-block;
  font-weight: 600;
  margin-top: 1rem;
  padding: 0.625rem 0.875rem;
  text-decoration: none;
}

.primary-action:hover {
  background: var(--theme-accent-strong);
}

/* Task dashboard, not a form column: the attention queue and active work
   use the wide left lane; operations context rides the right lane. */
.dashboard {
  display: grid;
  gap: 1.25rem;
  grid-template-columns: minmax(0, 7fr) minmax(19rem, 5fr);
  /* 96rem left a dead rail at 1920px; the workspace should use the viewport. */
  max-width: 120rem;
}

.dashboard-head,
.dashboard-empty {
  grid-column: 1 / -1;
}

.dashboard-attention,
.dashboard-continue,
.dashboard-list {
  grid-column: 1;
}

.dashboard-ops {
  grid-column: 2;
  grid-row: 2 / span 10;
  align-self: start;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
}

.dashboard-ops .eyebrow {
  margin: 0;
}

.dashboard-funnel {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

/* Jobs reuses the dashboard grid but has no right rail — everything
   spans the full width instead of leaving a dead column (hostile M5). */
.dashboard.jobs-page > * {
  grid-column: 1 / -1;
}

.dashboard-funnel-empty {
  color: var(--theme-text-muted);
  font-size: var(--text-sm);
  margin: 0;
}

@media (max-width: 1100px) {
  .dashboard {
    /* minmax(0,1fr): the single column may shrink below the widest
       child's min-content — otherwise long rows pin the page wider
       than the viewport. */
    grid-template-columns: minmax(0, 1fr);
  }
  .dashboard-ops,
  .dashboard-attention,
  .dashboard-continue,
  .dashboard-list {
    grid-column: 1;
    grid-row: auto;
  }
}

.dashboard-head {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.dashboard-head h1 {
  margin: 0;
}

.dashboard-head .primary-action {
  margin-top: 0;
}

.dashboard-sub {
  color: var(--theme-text-secondary);
  margin: 0.125rem 0 0;
}

.dashboard-cards {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
}

.metric-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  display: grid;
  gap: 0.25rem;
  min-width: 0;
  padding: 0.875rem 1rem;
}

.metric-card > * {
  min-width: 0;
}

.dashboard-money {
  display: grid;
  gap: 0.5rem;
  margin-top: 1rem;
}

.dashboard-money-currency > .eyebrow {
  margin-bottom: 0.375rem;
}

.metric-card strong {
  /* Headline digits, not code — IBM Plex Mono slashes its zero, so a "0"
   * KPI read as an empty-set placeholder (review VM3). */
  font-size: var(--text-display);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.dashboard-attention ul {
  display: grid;
  gap: 0.375rem;
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}

.attention-item a {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  color: var(--theme-text-primary);
  display: flex;
  gap: 0.625rem;
  justify-content: space-between;
  padding: 0.625rem 0.875rem;
  text-decoration: none;
}

.attention-item a:hover {
  border-color: var(--theme-border-strong);
}

.attention-item strong {
  font-variant-numeric: tabular-nums;
}

.attention-item.is-warn a {
  border-color: var(--theme-warning);
}

.attention-item.is-warn strong {
  color: var(--theme-warning);
}

.attention-item .attention-label {
  flex: 1;
}

.attention-item .attention-cta {
  color: var(--theme-accent);
  font-size: 0.75rem;
  font-weight: 600;
  margin-left: auto;
  white-space: nowrap;
}

.attention-item a:hover .attention-cta {
  text-decoration: underline;
}

.dashboard-activity {
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}

.dashboard-activity li {
  align-items: baseline;
  display: flex;
  gap: 0.75rem;
  padding: 0.375rem 0;
}

.dashboard-activity li + li {
  border-top: 1px solid var(--theme-border-subtle);
}

.dashboard-activity-event {
  color: var(--theme-text-primary);
  min-width: 0;
}

.dashboard-activity-code {
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.8125rem;
  white-space: nowrap;
}

.dashboard-activity time {
  color: var(--theme-text-muted);
  font-size: 0.75rem;
  margin-left: auto;
  white-space: nowrap;
}

.dashboard-attention-clear {
  color: var(--theme-text-secondary);
  margin: 0.375rem 0 0;
}

.dashboard-empty {
  background: var(--theme-surface-panel);
  border: 1px dashed var(--theme-border-strong);
  border-radius: 0.5rem;
  padding: 2rem;
  text-align: center;
}

.dashboard-empty p {
  color: var(--theme-text-secondary);
  margin: 0;
}

.dashboard-list {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
}

.dashboard-list-head {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  justify-content: space-between;
  padding: 0.625rem 1rem;
}

.dashboard-list-head h2 {
  font-size: 0.6875rem;
  margin: 0;
}

.dashboard-list-head a {
  color: var(--theme-accent);
  font-weight: 600;
  text-decoration: none;
}

.dashboard-list ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.dashboard-row {
  align-items: center;
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: minmax(8rem, 1.4fr) auto minmax(6rem, 1fr) auto;
  padding: 0.5rem 1rem;
  text-decoration: none;
}

.dashboard-row + .dashboard-row,
.dashboard-list li + li .dashboard-row {
  border-top: 1px solid var(--theme-border-subtle);
}

.dashboard-row-code {
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.75rem;
  white-space: nowrap;
}

.dashboard-row-name {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-row-client {
  color: var(--theme-text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-continue {
  align-items: baseline;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-accent);
  border-radius: 0.5rem;
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.125rem 1rem;
  /* minmax(0,1fr): the nowrap name/meta columns may shrink to the card,
     not the text's min-content — without it a long client name forces
     page-level horizontal scroll. */
  grid-template-columns: minmax(0, 1fr) auto;
  padding: 0.875rem 1rem;
  text-decoration: none;
}

.dashboard-continue:hover {
  border-color: var(--theme-accent);
  border-left-color: var(--theme-accent);
}

.dashboard-continue .eyebrow {
  grid-column: 1 / -1;
}

.dashboard-continue-name {
  font-size: 1.0625rem;
  font-weight: 600;
  grid-column: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-continue-meta {
  color: var(--theme-text-secondary);
  grid-column: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-continue-cta {
  align-self: center;
  color: var(--theme-accent);
  font-weight: 600;
  grid-column: 2;
  grid-row: 2 / 4;
}

@media (max-width: 640px) {
  .dashboard-continue {
    grid-template-columns: 1fr;
  }

  .dashboard-continue-cta {
    grid-column: 1;
    grid-row: auto;
  }
}

.status-chip,
.production-chip,
.production-chip-danger {
  border-radius: 999px;
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 600;
  line-height: 1.5;
  padding: 0.125rem 0.625rem;
}

/* Chips that act (e.g. filter the list) reset button chrome and invite the
   click they promise. */
button.production-chip {
  border: 0;
  cursor: pointer;
  font-family: inherit;
}

button.production-chip:hover {
  filter: brightness(0.95);
}

/* Production chips share the pill language; tones come from the same
   status palette so a status reads identically on every surface. */
.production-chip.status-released {
  background: var(--theme-info-soft);
  color: var(--theme-accent-deep);
}
.production-chip.status-in_progress {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}
.production-chip.status-hold {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}
.production-chip.status-completed {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.production-chip.status-dispatched {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-strong);
}
.production-chip.status-installed {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.production-chip.is-warn {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}
.production-chip.is-ready {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.production-chip.delivery-scheduled {
  background: var(--theme-info-soft);
  color: var(--theme-info);
}
.production-chip.delivery-on_route {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}
.production-chip.delivery-delivered {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.production-chip.delivery-failed {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}
.production-chip-danger {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

.status-chip[data-status="draft"] {
  background: var(--theme-surface-card);
  border: 1px solid var(--theme-border-strong);
  color: var(--theme-text-secondary);
}

.status-chip[data-status="quoted"] {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

.status-chip[data-status="approved"],
.status-chip[data-status="in_production"] {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}

.status-chip[data-status="completed"] {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-strong);
}

.status-chip[data-status="cancelled"] {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

/* Derived vano progression (position-statusKey tones) */
.status-chip[data-status="evaluated"] {
  background: var(--theme-info-soft);
  color: var(--theme-info);
}

.status-chip[data-status="priced"] {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

.status-chip[data-status="frozen"] {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}

.status-chip[data-status="production"] {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}

/* Customer approval link states (quotation links ledger) */
.status-chip[data-status="pending"] {
  background: var(--theme-info-soft);
  color: var(--theme-info);
}

.status-chip[data-status="declined"],
.status-chip[data-status="revoked"] {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

.settings-group {
  margin-top: 1.25rem;
}

.settings-group__title {
  border-bottom: 1px solid var(--theme-border-subtle);
  font-size: 0.8125rem;
  font-weight: 600;
  margin: 0 0 0.75rem;
  padding-bottom: 0.5rem;
}

.settings-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
}

.settings-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  padding: 0.875rem 1rem;
}

.settings-card h2,
.settings-card h3 {
  font-size: 0.6875rem;
  margin: 0 0 0.625rem;
}

.settings-list {
  display: grid;
  gap: 0.5rem;
  margin: 0;
}

.settings-plain {
  list-style: none;
  padding: 0;
}

.settings-row {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.settings-row dt {
  color: var(--theme-text-secondary);
  margin: 0;
}

.settings-row dd {
  margin: 0;
  text-align: right;
}

.settings-role {
  color: var(--theme-text-secondary);
}

.settings-mono {
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.75rem;
}

.settings-branding-preview {
  align-items: center;
  border: 1px dashed var(--theme-border-subtle);
  border-radius: 0.375rem;
  display: flex;
  justify-content: center;
  margin: 0 0 0.75rem;
  min-height: 4rem;
  padding: 0.5rem;
}

.settings-branding-logo {
  max-height: 3.5rem;
  max-width: 100%;
  object-fit: contain;
}

/* Shared ledger/credential forms — these classes are used by settings,
   projects and cobranza surfaces, so they must not live in feature CSS
   that only loads on one route. */
.payments-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 10px;
  margin-top: 10px;
}
.payments-form label {
  display: grid;
  gap: 4px;
  font-size: var(--text-s, 12px);
  color: var(--ink-muted);
}
.payments-form-wide {
  grid-column: 1 / -1;
}
.payments-form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
}
.payments-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
  font-size: var(--text-s, 13px);
}
.payments-table th,
.payments-table td {
  text-align: left;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border, #e0deda);
}
.payments-table .num {
  text-align: right;
  font-family: var(--font-mono, monospace);
}
.payments-voided td {
  opacity: 0.55;
}

/* File pickers: keep the native input visually hidden and let the
   translated button + filename text carry the interaction. */
.file-input-hidden {
  display: none;
}
.file-field {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.file-field__name {
  color: var(--theme-text-secondary);
  font-size: var(--text-s, 12px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-theme {
  border: 1px solid var(--theme-border-strong);
  border-radius: 0.375rem;
  display: inline-flex;
  overflow: hidden;
}

.settings-theme-option {
  background: transparent;
  border: 0;
  color: var(--theme-text-secondary);
  padding: 0.375rem 0.875rem;
}

.settings-theme-option[data-active="true"] {
  background: var(--theme-accent);
  color: var(--theme-surface-panel);
}

.settings-hint {
  color: var(--theme-text-secondary);
  margin: 0 0 0.625rem;
}

.settings-links {
  display: flex;
  gap: 1.25rem;
}

.settings-links a {
  color: var(--theme-accent);
  font-weight: 600;
  text-decoration: none;
}

/* ——— Responsive ———
 * Tablet (<1024px): the rail becomes an overlay drawer toggled from the
 * topbar so the workspace keeps full width. Mobile (<640px): dense chrome —
 * review/approve/status flows stay usable; the CAD editor is not a phone
 * surface by design. */
.rail-toggle {
  display: none;
}

.rail-scrim {
  background: transparent;
  border: none;
  cursor: default;
  display: none;
  inset: 0;
  padding: 0;
  position: fixed;
  z-index: 40;
}

@media (max-width: 1024px) {
  .rail-toggle {
    align-items: center;
    border: none;
    border-radius: var(--radius-md);
    display: inline-flex;
    font-size: 1rem;
    height: 32px;
    justify-content: center;
    padding: 0;
    width: 32px;
  }

  .rail-scrim {
    display: block;
    visibility: hidden;
  }

  .app-shell.rail-open .rail-scrim {
    background: rgba(15, 15, 14, 0.45);
    visibility: visible;
  }

  .app-rail {
    box-shadow: none;
    left: 0;
    position: fixed;
    top: 0;
    transform: translateX(-105%);
    transition:
      transform 0.18s ease,
      visibility 0.18s ease;
    visibility: hidden;
    z-index: 50;
  }

  .app-shell.rail-open .app-rail {
    box-shadow: 0 0 2rem rgba(15, 15, 14, 0.35);
    transform: translateX(0);
    visibility: visible;
  }
}

/* Studio compact rail: on the position editor the domain rail contracts to
 * a 64px icon strip so the canvas owns the viewport. Labels are removed
 * visually but the links keep aria-label + title, so no affordance is lost;
 * the desktop drawer behavior below still applies under 1024px. */
@media (min-width: 1025px) {
  .app-shell[data-studio] .app-rail {
    align-items: stretch;
    padding-inline: 0;
    width: 4rem;
  }

  .app-shell[data-studio] .app-rail__brand {
    padding-inline: 0;
    text-align: center;
  }

  /* Compact mark: the wordmark collapses to its square glyph. */
  .app-shell[data-studio] .app-rail__brand .brand {
    font-size: 0;
    justify-content: center;
  }

  .app-shell[data-studio] .org-switcher,
  .app-shell[data-studio] .rail-group__title,
  .app-shell[data-studio] .app-rail__identity,
  .app-shell[data-studio] .rail-item > span {
    display: none;
  }

  .app-shell[data-studio] .rail-item {
    border-left-width: 2px;
    border-radius: var(--radius-md);
    justify-content: center;
    margin-inline: auto;
    padding-inline: 0;
    width: 2.5rem;
  }

  .app-shell[data-studio] .rail-item__icon {
    height: 18px;
    width: 18px;
  }
}

@media (max-width: 640px) {
  .app-topbar {
    gap: 0.5rem;
  }

  /* Phone: the header stack puts actions on their own line — no clipped
     primary action, no page-level horizontal scroll. */
  .ui-page-header__row {
    flex-direction: column;
    gap: var(--space-2);
  }

  .ui-page-header__actions {
    flex-wrap: wrap;
    width: 100%;
  }

  .attention-item a {
    flex-wrap: wrap;
  }

  .attention-item .attention-cta {
    margin-left: 0;
  }

  .topbar-search span {
    display: none;
  }

  .workspace {
    padding: var(--space-3) var(--space-2);
  }

  .dashboard-cards {
    grid-template-columns: 1fr;
  }

  /* Phone: headline KPIs step down a tier so big amounts fit the card —
     amounts never break mid-figure. */
  .metric-card strong {
    font-size: var(--text-title);
  }

  /* Phone: project rows reflow to two compact lines — name+status, then
     client+code — instead of four columns squeezed into 390px. */
  .dashboard-row {
    gap: 0.125rem 0.5rem;
    grid-template-columns: minmax(0, 1fr) auto;
    padding-block: 0.625rem;
  }

  .dashboard-row-name {
    grid-column: 1;
    grid-row: 1;
  }

  .dashboard-row .status-chip {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
  }

  .dashboard-row-client {
    grid-column: 1;
    grid-row: 2;
  }

  .dashboard-row-code {
    grid-column: 2;
    grid-row: 2;
    justify-self: end;
  }

  .dashboard-activity li {
    flex-wrap: wrap;
    row-gap: 0.125rem;
  }

  .onboarding {
    padding: var(--space-4) var(--space-2);
  }
}

/* Jobs workspace — background work as a legible queue. */
.jobs-filter {
  min-width: 10rem;
}

/* The jobs page shares .dashboard's two-lane grid — the queue itself spans
 * both lanes; a narrow job list would leave most of the page empty. */
.jobs-list {
  grid-column: 1 / -1;
}

.jobs-list {
  display: grid;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.job-row {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  padding: 0.625rem 0.875rem;
}

.job-row-main {
  align-items: center;
  display: flex;
  flex: 1;
  gap: 0.625rem;
  min-width: 12rem;
}

.job-row-meta {
  color: var(--theme-text-secondary);
  display: flex;
  font-size: 0.75rem;
  gap: 0.875rem;
}

.job-row-meta time {
  font-variant-numeric: tabular-nums;
}

.job-row-error {
  color: var(--theme-danger);
  flex-basis: 100%;
  font-size: 0.8125rem;
  margin: 0.125rem 0 0;
}

.job-row-code {
  color: var(--theme-text-muted, #66707f);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.6875rem;
}

/* Clients workspace — master list + detail. */
.clients-desk {
  align-items: start;
  display: grid;
  gap: 1rem;
  grid-template-columns: minmax(16rem, 22rem) minmax(0, 1fr);
}

.clients-list {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.clients-list > ul {
  display: grid;
  gap: 0.25rem;
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}

.clients-row {
  align-items: start;
  background: none;
  border: 1px solid transparent;
  border-radius: 0.375rem;
  color: var(--theme-text-primary);
  cursor: pointer;
  display: grid;
  gap: 0.125rem;
  padding: 0.5rem 0.625rem;
  text-align: left;
  width: 100%;
}

.clients-row:hover {
  border-color: var(--theme-border-subtle);
}

.clients-row.is-active {
  background: var(--theme-surface-raised, var(--theme-surface-panel));
  border-color: var(--theme-accent);
}

.clients-row-name {
  font-weight: 600;
}

.clients-row-meta {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.clients-empty {
  align-items: center;
  color: var(--theme-text-secondary);
  display: flex;
  gap: 0.6rem;
  padding: 0.75rem;
}

.clients-empty__cta {
  background: transparent;
  border: 1px solid var(--theme-accent);
  border-radius: var(--radius-sm);
  color: var(--theme-accent-ink);
  cursor: pointer;
  font-size: 0.75rem;
  padding: 0.18rem 0.6rem;
}

.clients-detail {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  padding: 1rem 1.25rem;
}

.clients-detail-head {
  align-items: start;
  display: flex;
  gap: 1rem;
  justify-content: space-between;
}

.clients-detail-head h2 {
  margin: 0;
}

.clients-detail-meta {
  color: var(--theme-text-secondary);
  margin: 0.25rem 0 0;
}

.clients-detail-actions {
  display: flex;
  gap: 0.5rem;
}

.clients-facts {
  display: grid;
  gap: 0.5rem;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  margin: 1rem 0;
}

.clients-facts dt {
  color: var(--theme-text-secondary);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.clients-facts dd {
  margin: 0.125rem 0 0;
  white-space: pre-wrap;
}

.clients-projects {
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}

.clients-project-row {
  align-items: center;
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: auto minmax(8rem, 1fr) auto auto;
  padding: 0.5rem 0;
  text-decoration: none;
}

.clients-project-row + li {
  border-top: 1px solid var(--theme-border-subtle);
}

.clients-project-row time {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

@media (max-width: 900px) {
  .clients-desk {
    grid-template-columns: 1fr;
  }
}

/* Global reduced-motion contract: every transition/animation in the app
   (skeleton shimmer, dialogs, canvas drags, menu reveals) collapses for
   users who asked the OS to remove it. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* Checkbox labels sit inline with their box — a bare label {display:grid}
   stacks the control over its text, which reads as a detached checkbox. */
label:has(> input[type="checkbox"]),
label.settings-inline {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}
label:has(> input[type="checkbox"]) input[type="checkbox"],
label.settings-inline input[type="checkbox"] {
  flex: none;
}

/* DEKOPEN identity tokens — phase-01 visual contract.
   Architectural workbench feel: warm light canvas, graphite ink, thin lines,
   measured spacing, product as protagonist, petrol-teal accent. Dark theme
   uses legible graphites. No gradients, glow, or glassmorphism.

   Three tiers:
   1. Interface color tokens — --theme-* (surface/text/border/focus/action/
      danger/warning/success/info/disabled, distinct hover-vs-business state).
   2. Physical material colors — --mat-* in the unthemed block: the real finish
      of a product (PVC, foil, aluminium, glass, hardware). Theme-invariant by
      contract: a foil-brown window keeps its finish in the dark theme; Studio,
      print and the renderer may never restyle them as chrome.
   3. Structural tokens — type/space/radius/shadow/z-index.

   Aliases at the bottom retire the ad-hoc vocabulary older code pasted in;
   keep them defined and migrate call sites opportunistically.

   Type scale (contract): base 14px, labels 12–13, section titles 19px,
   page titles 26px. Mono/tabular figures only where comparison improves.
   Space scale: 4/8/12/16/24/32/48. Desktop controls ≈36px, touch 44px. */

:root,
:root[data-theme="light"] {
  --theme-bg-canvas: #f7f6f3;
  --theme-viewport-stage: #e8e9e5;
  --theme-viewport-ground: #d3d5cf;
  --theme-surface-panel: #ffffff;
  --theme-surface-card: #f0efeb;
  --theme-surface-hover: #e9e7e1;
  --theme-border-subtle: #dcdad3;
  --theme-border-strong: #b8b9b1;
  --theme-text-primary: #24292c;
  --theme-text-secondary: #545d60;
  --theme-text-muted: #5f6a6c;
  --theme-text-tertiary: #5f6a6c; /* smallest text tier — AA on panel surfaces */
  --theme-accent: #0f817a;
  --theme-accent-strong: #0b6b66;
  --theme-accent-deep: #09524e;
  --theme-accent-soft: #e4f3f1;
  --theme-accent-ink: #0b4d49;
  --theme-mark: #e56a32;
  --theme-warning: #9c5306;
  --theme-warning-soft: #fdf1e3;
  --theme-success: #1e7a4c;
  --theme-success-soft: #e3f2ea;
  --theme-danger: #b3372f;
  --theme-danger-soft: #fbe9e7;
  --theme-danger-ink: #ffffff;
  --theme-info: var(--theme-accent);
  --theme-info-soft: var(--theme-accent-soft);
  /* Technical states — UNKNOWN means the authority is absent (not "unset"),
     BLOCKED means the domain refuses to proceed. Both are facts to act on,
     so they get dedicated soft surfaces instead of reusing warning/danger. */
  --theme-unknown: #5f6d69;
  --theme-unknown-soft: #e7eceb;
  --theme-blocked: #8c2f9b;
  --theme-blocked-soft: #f3e8f7;
  --theme-focus-ring: #0f817a;
  --theme-selection: #d3ebe8;
  --theme-disabled-bg: #eceeee;
  --theme-disabled-ink: #76847f; /* 3.35:1 on disabled-bg — exempt from AA but readable */
  --theme-disabled-border: #d5dbda;
  --theme-skeleton: #e2e7e6;
  --theme-skeleton-sheen: #f2f5f4;
  --theme-glass-tint: rgba(15, 129, 122, 0.07);
  --op-selected-row: #fdf3dc;
  --shadow-raise: 0 1px 3px rgb(28 30 28 / 0.07), 0 3px 10px rgb(28 30 28 / 0.07);
  --shadow-pop: 0 10px 28px rgb(28 30 28 / 0.14);
  --shadow-modal: 0 12px 40px rgba(20, 24, 24, 0.2);

  /* DEKOPEN orb identity — flat 2D. The sphere is intentionally identical
   * across themes (the identity IS the dark orb); only the edge stroke
   * adapts to the dark theme. */
  --orb-mid: #2a3238;
  --orb-deep: #171e23;
  --orb-edge: rgba(10, 15, 18, 0.55);
  /* Cyan capsule eyes + thin orbit line — the identity accent. */
  --orb-eye: #0fd8ea;
  --orb-eye-hi: #7cf3ff;
  --orb-ribbon: #0fd8ea;
  --orb-ribbon-soft: rgba(15, 216, 234, 0.42);
}

:root[data-theme="dark"] {
  --theme-bg-canvas: #14181a;
  /* 3D stage stays lighter than the chrome so anthracite/PVC frames keep
   * silhouette contrast — a neutral exhibition backdrop, not page chrome. */
  --theme-viewport-stage: #262c2f;
  --theme-viewport-ground: #1c2225;
  --theme-surface-panel: #1b2124;
  --theme-surface-card: #232a2d;
  --theme-surface-hover: #2c3539;
  --theme-border-subtle: #323c40;
  --theme-border-strong: #4a585d;
  --theme-text-primary: #edf2f1;
  --theme-text-secondary: #a4b6b3;
  --theme-text-muted: #81938f;
  --theme-text-tertiary: #81938f;
  --theme-accent: #2aa69b;
  --theme-accent-strong: #45beb1;
  --theme-accent-deep: #2aa69b;
  --theme-accent-soft: #14312f;
  --theme-accent-ink: #bfe6e0;
  --theme-mark: #e8804a;
  --theme-warning: #e09543;
  --theme-warning-soft: #33231a;
  --theme-success: #4caf7f;
  --theme-success-soft: #16291f;
  --theme-danger: #e06154;
  --theme-danger-soft: #331d1a;
  --theme-danger-ink: #ffffff;
  --theme-info: var(--theme-accent);
  --theme-info-soft: var(--theme-accent-soft);
  --theme-unknown: #93a19d;
  --theme-unknown-soft: #242c2f;
  --theme-blocked: #c07ad1;
  --theme-blocked-soft: #2b1f31;
  --theme-focus-ring: #45beb1;
  --theme-selection: #163a38;
  --theme-disabled-bg: #222a2d;
  --theme-disabled-ink: #6b7a76; /* 3.25:1 on disabled-bg */
  --theme-disabled-border: #333d41;
  --theme-skeleton: #262f33;
  --theme-skeleton-sheen: #2f393d;
  --theme-glass-tint: rgba(42, 166, 155, 0.1);
  --op-selected-row: #3a3220;
  --shadow-raise: 0 2px 10px rgba(0, 0, 0, 0.45);
  --shadow-pop: 0 12px 32px rgba(0, 0, 0, 0.55);
  --shadow-modal: 0 12px 44px rgba(0, 0, 0, 0.6);

  --orb-mid: #313a41;
  --orb-deep: #1a2228;
  --orb-edge: rgba(233, 242, 241, 0.16);
  --orb-eye: #12ddf0;
  --orb-eye-hi: #96f6ff;
  --orb-ribbon: #12ddf0;
  --orb-ribbon-soft: rgba(18, 221, 240, 0.48);
}

:root {
  /* Type — contract: base 14–15, labels 12–13, sections 18–20, pages 24–28.
     Operational information never lives below 12px. */
  --font-sans: "IBM Plex Sans", system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, monospace;
  --text-xs: 0.75rem;
  --text-s: 0.8125rem;
  --text-body: 0.9375rem;
  --text-title: 1.1875rem;
  --text-display: 1.625rem;

  /* Space — 4px base grid: 4/8/12/16/24/32/48 */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;

  /* Physical material colors — the product's real finish. Deliberately
     defined once here, outside both themed blocks: a white-PVC or
     foil-brown window must keep its identity in the dark theme, and print/
     documents share the same finish. UI chrome never reuses these. */
  --mat-pvc-fill: #f4f7f6;
  --mat-pvc-edge: #b9c4c2;
  --mat-pvc-highlight: #ffffff;
  --mat-foil-fill: #7b5a3b;
  --mat-foil-edge: #523d26;
  --mat-foil-highlight: #96714c;
  --mat-aluminium-fill: #dce3e5;
  --mat-aluminium-edge: #a3b0b4;
  --mat-aluminium-highlight: #f2f6f7;
  --mat-anthracite-fill: #3f454b;
  --mat-anthracite-edge: #262b30;
  --mat-anthracite-highlight: #5a636b;
  --mat-panel-fill: #e3eae8;
  --mat-panel-edge: #aab6b3;
  --mat-glass: #8fb8cc;
  --mat-steel: #a9b2b8;
  --mat-handle: #4a5055;
  --mat-coupler: #5d6469;
  --mat-gasket: #2e3134;
  --mat-edge: #6b7075;
  /* CNC op-kind marks — categorical diagram palette (drill/water/cut-mill/
     edge/hardware), distinct from semantic accents; fixed across themes so
     a machining drawing reads identically on screen and on paper. */
  --mat-op-mark: #7a5af8;
  --mat-op-mark-edge: #4c2fd1;
  --mat-op-drill: #2563eb;
  --mat-op-drill-edge: #1e40af;
  --mat-op-water: #0891b2;
  --mat-op-water-edge: #0e7490;
  --mat-op-cut: #7c3aed;
  --mat-op-cut-edge: #5b21b6;
  --mat-op-mill: #9333ea;
  --mat-op-mill-edge: #6b21a8;
  --mat-op-edge-work: #64748b;
  --mat-op-edge-work-edge: #334155;
  --mat-op-hardware: #b45309;
  /* Opaque glass pane — physical, one legible tone in both themes (the
     translucent tint let member slabs show through). Signature ink: the
     pad is white paper sealed into the POD, so ink stays dark always. */
  --mat-glass-pane: #e9f2f1;
  --mat-signature-ink: #1a1f24;

  /* Compatibility aliases — resolve to the invariant --mat-* palette so
     existing render call sites keep working unchanged in both themes. */
  --member-pvc-fill: var(--mat-pvc-fill);
  --member-pvc-edge: var(--mat-pvc-edge);
  --member-pvc-highlight: var(--mat-pvc-highlight);
  --member-foil-fill: var(--mat-foil-fill);
  --member-foil-edge: var(--mat-foil-edge);
  --member-foil-highlight: var(--mat-foil-highlight);
  --member-aluminium-fill: var(--mat-aluminium-fill);
  --member-aluminium-edge: var(--mat-aluminium-edge);
  --member-aluminium-highlight: var(--mat-aluminium-highlight);
  --member-anthracite-fill: var(--mat-anthracite-fill);
  --member-anthracite-edge: var(--mat-anthracite-edge);
  --member-anthracite-highlight: var(--mat-anthracite-highlight);
  --member-panel-fill: var(--mat-panel-fill);
  --member-panel-edge: var(--mat-panel-edge);
  --model3d-glass: var(--mat-glass);
  --model3d-steel: var(--mat-steel);
  --model3d-handle: var(--mat-handle);
  --model3d-coupler: var(--mat-coupler);
  --model3d-gasket: var(--mat-gasket);
  --model3d-edge: var(--mat-edge);
  --op-mark: var(--mat-op-mark);
  --op-mark-edge: var(--mat-op-mark-edge);
  --op-drill: var(--mat-op-drill);
  --op-drill-edge: var(--mat-op-drill-edge);
  --op-water: var(--mat-op-water);
  --op-water-edge: var(--mat-op-water-edge);
  --op-cut: var(--mat-op-cut);
  --op-cut-edge: var(--mat-op-cut-edge);
  --op-mill: var(--mat-op-mill);
  --op-mill-edge: var(--mat-op-mill-edge);
  --op-edge-work: var(--mat-op-edge-work);
  --op-edge-work-edge: var(--mat-op-edge-work-edge);
  --op-hardware: var(--mat-op-hardware);
  --theme-glass-pane: var(--mat-glass-pane);
  --signature-ink: var(--mat-signature-ink);

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-pill: 999px;

  /* Elevation — numbered scale; the named shadows resolve through it */
  --elevation-0: none;
  --elevation-1: var(--shadow-raise);
  --elevation-2: var(--shadow-pop);
  --elevation-3: var(--shadow-modal);

  /* Density — row/control heights on the 4px grid */
  --density-compact: 1.75rem;
  --density-default: 2.25rem;
  --density-loose: 2.75rem;
  --control-height: var(--density-default);

  /* Interaction */
  --focus-ring: 0 0 0 2px var(--theme-bg-canvas), 0 0 0 4px var(--theme-focus-ring);
  --motion-fast: 120ms;
  --motion-base: 180ms;

  /* Layers */
  --z-island: 10;
  --z-drawer: 30;
  --z-overlay: 50;
  --z-modal: 90;

  /* Breakpoints (used by @media rules; documented as tokens for parity) */
  --bp-tablet: 1100px;
  --bp-phone: 720px;

  /* Retired-vocabulary aliases — resolve to canonical tokens so older call
     sites render correctly in both themes. New code uses --theme-* directly. */
  --theme-surface: var(--theme-surface-panel);
  --theme-surface-raised: var(--theme-surface-panel);
  --theme-font-mono: var(--font-mono);
  --surface-raised: var(--theme-surface-panel);
  --surface-sunken: var(--theme-surface-card);
  --accent: var(--theme-accent);
  --ok: var(--theme-success);
  --warn: var(--theme-warning);
  --danger: var(--theme-danger);
  --ink: var(--theme-text-primary);
  --ink-muted: var(--theme-text-muted);
  --ink-3: var(--theme-text-secondary);
  --ink-faint: var(--theme-text-muted);
  --text-dim: var(--theme-text-secondary);
  --warning: var(--theme-warning);
  --warning-soft: var(--theme-warning-soft);
  --line-soft: var(--theme-border-subtle);
  --line: var(--theme-border-subtle);
  --line-strong: var(--theme-border-strong);
  --border: var(--theme-border-subtle);
}

/* Route-level error boundary: a crashed view keeps a recoverable frame. */
.route-error {
  min-height: 60vh;
  display: grid;
  place-items: center;
  padding: var(--space-6, 24px);
}
.route-error-card {
  max-width: 26rem;
  text-align: center;
  display: grid;
  gap: var(--space-3, 12px);
}
.route-error-card h1 {
  font-size: 1.25rem;
  margin: 0;
}
.route-error-card p {
  color: var(--theme-text-secondary, #5b6472);
  margin: 0;
}
.route-error-actions {
  display: flex;
  gap: var(--space-2, 8px);
  justify-content: center;
}
.route-error-actions button {
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  border: 1px solid var(--line, #d6dae2);
  background: var(--accent, #1b5cff);
  color: var(--theme-surface-panel);
  font-weight: 600;
  cursor: pointer;
}
.route-error-actions .route-error-secondary {
  background: transparent;
  color: var(--theme-text-primary, #1d2430);
}

/* Canonical primitives — every surface uses these instead of local chrome.
   Token-driven only: no raw colors, no component-invented shadows. */

/* ---------- buttons / controls ---------- */

.ui-button,
button.ui-button {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  color: var(--theme-text-primary);
  cursor: pointer;
  display: inline-flex;
  font-family: inherit;
  font-size: var(--text-body);
  gap: var(--space-2);
  height: var(--control-height);
  padding: 0 var(--space-3);
  transition:
    background var(--motion-fast) ease,
    border-color var(--motion-fast) ease;
}

.ui-button:hover:not(:disabled) {
  background: var(--theme-surface-hover);
  border-color: var(--theme-border-strong);
}

/* Tertiary navigation links ("Volver al proyecto", "Ver todos") — quiet
 * chrome, never default-browser blue (review m5). */
a.ui-backlink {
  align-items: center;
  color: var(--theme-text-secondary);
  display: inline-flex;
  font-size: var(--text-s);
  font-weight: 600;
  /* WCAG 2.5.8 — 24 px click box; visual glyphs stay small. */
  min-height: 24px;
  text-decoration: none;
}

a.ui-backlink--back::before {
  content: "‹";
  margin-right: 0.125rem;
}

a.ui-backlink:hover {
  color: var(--theme-text-primary);
}

.ui-button--primary {
  background: var(--theme-accent-strong);
  border-color: var(--theme-accent-strong);
  color: var(--theme-surface-panel);
}

.ui-button--primary:hover:not(:disabled) {
  background: var(--theme-accent-deep);
  border-color: var(--theme-accent-deep);
}

.ui-button--danger {
  background: var(--theme-danger);
  border-color: var(--theme-danger);
  color: var(--theme-surface-panel);
}

.ui-button--danger:hover:not(:disabled) {
  background: var(--theme-danger);
  border-color: var(--theme-danger);
  filter: brightness(0.92);
}

.ui-button--ghost {
  background: transparent;
  border-color: transparent;
}

.ui-button--ghost:hover:not(:disabled) {
  background: var(--theme-surface-hover);
  border-color: transparent;
}

.ui-button:disabled,
button:disabled {
  background: var(--theme-disabled-bg);
  border-color: var(--theme-disabled-border);
  color: var(--theme-disabled-ink);
  cursor: not-allowed;
}

.ui-icon-button {
  align-items: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  display: inline-flex;
  font-size: var(--text-title);
  height: var(--density-compact);
  justify-content: center;
  padding: 0;
  width: var(--density-compact);
}

.ui-icon-button:hover {
  background: var(--theme-surface-hover);
  color: var(--theme-text-primary);
}

/* one focus contract for every interactive element in the product */
:is(a, button, input, select, textarea, [tabindex]):focus-visible {
  box-shadow: var(--focus-ring);
  outline: none;
}

::selection {
  background: var(--theme-selection);
}

/* ---------- badge ---------- */

.ui-badge {
  align-items: center;
  border-radius: var(--radius-pill);
  display: inline-flex;
  font-size: var(--text-xs);
  font-weight: 600;
  gap: var(--space-1);
  letter-spacing: 0.01em;
  line-height: 1;
  padding: 3px 8px;
  white-space: nowrap;
}

.ui-badge__dot {
  border-radius: var(--radius-pill);
  display: inline-block;
  height: 6px;
  width: 6px;
}

.ui-badge--success {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.ui-badge--success .ui-badge__dot {
  background: var(--theme-success);
}
.ui-badge--warning {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}
.ui-badge--warning .ui-badge__dot {
  background: var(--theme-warning);
}
.ui-badge--danger {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}
.ui-badge--danger .ui-badge__dot {
  background: var(--theme-danger);
}
.ui-badge--info {
  background: var(--theme-info-soft);
  color: var(--theme-accent-ink);
}
.ui-badge--info .ui-badge__dot {
  background: var(--theme-accent);
}
.ui-badge--unknown {
  background: var(--theme-unknown-soft);
  color: var(--theme-unknown);
}
.ui-badge--unknown .ui-badge__dot {
  background: var(--theme-unknown);
}
.ui-badge--blocked {
  background: var(--theme-blocked-soft);
  color: var(--theme-blocked);
}
.ui-badge--blocked .ui-badge__dot {
  background: var(--theme-blocked);
}
.ui-badge--neutral {
  background: var(--theme-surface-card);
  color: var(--theme-text-secondary);
}
.ui-badge--neutral .ui-badge__dot {
  background: var(--theme-text-muted);
}

/* ---------- empty / error / skeleton ---------- */

.ui-empty {
  align-items: center;
  border: 1px dashed var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  justify-content: center;
  padding: var(--space-6) var(--space-4);
  text-align: center;
}

.ui-empty__title {
  color: var(--theme-text-primary);
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0;
}

.ui-empty__body {
  color: var(--theme-text-secondary);
  font-size: var(--text-body);
  margin: 0;
  max-width: 44ch;
}

.ui-empty__action {
  margin-top: var(--space-2);
}

.ui-empty--error {
  border-color: var(--theme-danger);
}

.ui-empty--denied {
  border-style: solid;
  min-height: 12rem;
}

.ui-empty__glyph {
  fill: none;
  height: 2rem;
  stroke: var(--theme-text-secondary);
  stroke-width: 1.4;
  width: 2rem;
}

.ui-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4);
}

.ui-skeleton__line {
  animation: ui-sheen 1.4s ease-in-out infinite;
  background: linear-gradient(
    90deg,
    var(--theme-skeleton) 0%,
    var(--theme-skeleton-sheen) 50%,
    var(--theme-skeleton) 100%
  );
  background-size: 200% 100%;
  border-radius: var(--radius-sm);
  display: block;
  height: 0.85rem;
}

@keyframes ui-sheen {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

/* ---------- banner ---------- */

.ui-banner {
  align-items: flex-start;
  border: 1px solid;
  border-radius: var(--radius-md);
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  padding: var(--space-3);
}

.ui-banner__title {
  font-size: var(--text-body);
  font-weight: 600;
  margin: 0;
}

.ui-banner__body {
  font-size: var(--text-body);
  margin-top: var(--space-1);
}

.ui-banner__action {
  flex-shrink: 0;
}

.ui-banner--warning {
  background: var(--theme-warning-soft);
  border-color: var(--theme-warning);
  color: var(--theme-text-primary);
}
.ui-banner--danger {
  background: var(--theme-danger-soft);
  border-color: var(--theme-danger);
  color: var(--theme-text-primary);
}
.ui-banner--blocked {
  background: var(--theme-blocked-soft);
  border-color: var(--theme-blocked);
  color: var(--theme-text-primary);
}
.ui-banner--unknown {
  background: var(--theme-unknown-soft);
  border-color: var(--theme-unknown);
  color: var(--theme-text-primary);
}
.ui-banner--info {
  background: var(--theme-info-soft);
  border-color: var(--theme-accent);
  color: var(--theme-text-primary);
}

/* ---------- evidence ---------- */

.ui-evidence {
  background: var(--theme-surface-card);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  display: inline-flex;
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  padding: 1px var(--space-1);
  white-space: nowrap;
}

/* ---------- dialog / overlay ---------- */

.ui-overlay {
  align-items: center;
  background: rgb(20 25 27 / 0.42);
  display: flex;
  inset: 0;
  justify-content: center;
  position: fixed;
  z-index: var(--z-modal);
}

:root[data-theme="dark"] .ui-overlay {
  background: rgb(0 0 0 / 0.55);
}

.ui-dialog {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--elevation-3);
  display: flex;
  flex-direction: column;
  max-height: 85vh;
  max-width: calc(100vw - 2rem);
  outline: none;
  width: 34rem;
}

.ui-dialog--s {
  width: 24rem;
}
.ui-dialog--l {
  width: 48rem;
}

.ui-dialog__header {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
}

.ui-dialog__title {
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0;
}

.ui-dialog__body {
  overflow-y: auto;
  padding: var(--space-4);
}

.ui-dialog__text {
  color: var(--theme-text-secondary);
  font-size: var(--text-body);
  margin: 0;
}

.ui-dialog__footer {
  border-top: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: var(--space-2);
  justify-content: flex-end;
  padding: var(--space-3) var(--space-4);
}

/* ---------- toolbar / context nav / split ---------- */

.ui-toolbar {
  align-items: center;
  display: flex;
  gap: var(--space-2);
  min-height: var(--density-loose);
}

.ui-toolbar__title {
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0;
}

.ui-toolbar__spacer {
  flex: 1;
}

.ui-context-nav {
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: var(--space-1);
  overflow-x: auto;
}

.ui-context-nav__link {
  border-bottom: 2px solid transparent;
  color: var(--theme-text-secondary);
  font-size: var(--text-body);
  font-weight: 500;
  padding: var(--space-2) var(--space-3);
  text-decoration: none;
  white-space: nowrap;
}

.ui-context-nav__link:hover {
  color: var(--theme-text-primary);
}

.ui-context-nav__link.active {
  border-bottom-color: var(--theme-accent);
  color: var(--theme-text-primary);
}

.ui-split {
  display: grid;
  grid-template-columns: 1fr auto;
  height: 100%;
  min-height: 0;
}

.ui-split--s {
  grid-template-columns: 1fr 18rem;
}
.ui-split--m {
  grid-template-columns: 1fr 22rem;
}
.ui-split--l {
  grid-template-columns: 1fr 28rem;
}

.ui-split__main {
  min-width: 0;
  overflow: auto;
}

.ui-split__aside {
  border-left: 1px solid var(--theme-border-subtle);
  min-width: 0;
  overflow-y: auto;
}

/* ---------- inline edit ---------- */

.ui-inline-edit {
  align-items: baseline;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: inherit;
  cursor: text;
  display: inline-flex;
  font: inherit;
  gap: var(--space-2);
  max-width: 100%;
  padding: 2px var(--space-1);
  text-align: left;
}

.ui-inline-edit:hover {
  background: var(--theme-surface-hover);
}

.ui-inline-edit__hint {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
  opacity: 0;
  transition: opacity var(--motion-fast) ease;
}

.ui-inline-edit:hover .ui-inline-edit__hint {
  opacity: 1;
}

.ui-inline-edit__placeholder {
  color: var(--theme-text-muted);
  font-style: italic;
}

.ui-inline-edit__input {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-accent);
  border-radius: var(--radius-sm);
  color: var(--theme-text-primary);
  font: inherit;
  padding: 2px var(--space-1);
}

/* ---------- field ---------- */

.ui-field {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.ui-field__label {
  color: var(--theme-text-secondary);
  font-size: var(--text-xs);
  font-weight: 500;
}

.ui-field__input {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  color: var(--theme-text-primary);
  font: inherit;
  height: var(--control-height);
  padding: 0 var(--space-2);
}

.ui-field__input:focus {
  border-color: var(--theme-accent);
  outline: none;
}

/* ---------- focus ---------- */

:where(
  .ui-button,
  .ui-icon-button,
  .ui-context-nav__link,
  .ui-inline-edit,
  .ui-field__input
):focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 1px;
}

/* ---------- disabled ---------- */

:where(.ui-button, .ui-icon-button):disabled {
  background: var(--theme-disabled-bg);
  border-color: var(--theme-disabled-border);
  color: var(--theme-disabled-ink);
  cursor: not-allowed;
}

/* Production/status chip — shared by Settings, Catalogs (imports), Projects
   and Production; it lives in the eager layer so chips render on cold loads
   of any surface. */
.production-chip {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  font-weight: 600;
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-secondary);
}
.production-chip.status-done,
.production-chip.status-completed {
  color: var(--theme-accent);
  border-color: var(--theme-accent);
}
.production-chip.status-in_progress {
  color: var(--theme-info, var(--theme-accent));
  border-color: currentColor;
}
.production-chip.status-blocked,
.production-chip.status-hold {
  color: var(--theme-warning, #e56a32);
  border-color: currentColor;
}
.production-chip.delivery-scheduled {
  border-color: var(--accent);
}
.production-chip.delivery-on_route {
  border-color: var(--warn, #b7791f);
}
.production-chip.delivery-delivered {
  border-color: var(--ok, #2f855a);
}
.production-chip.delivery-failed {
  border-color: var(--danger, #c53030);
}
.production-chip.is-warn {
  color: var(--theme-warn, #b45309);
  border-color: var(--theme-warn, #b45309);
}
.production-chip.is-ready {
  color: var(--theme-accent);
  border-color: var(--theme-accent);
}
.production-chip.imports-status-uploaded,
.production-chip.imports-status-extracting {
  color: var(--theme-info, var(--theme-accent));
  border-color: currentColor;
}
.production-chip.imports-status-review_ready {
  color: var(--theme-warning, #e56a32);
  border-color: currentColor;
}
.production-chip.imports-status-confirmed {
  color: var(--theme-accent);
  border-color: var(--theme-accent);
}
.production-chip.imports-status-failed {
  color: var(--theme-danger, #c0392b);
  border-color: currentColor;
}
.production-chip.imports-confidence-verified_structured {
  color: var(--theme-accent);
  border-color: var(--theme-accent);
}
.production-chip.imports-confidence-high_candidate {
  color: var(--theme-accent);
  border-color: currentColor;
  border-style: dashed;
}
.production-chip.imports-confidence-review_required {
  color: var(--theme-warning, #e56a32);
  border-color: currentColor;
}
.production-chip.imports-confidence-low {
  color: var(--theme-danger, #c0392b);
  border-color: currentColor;
  border-style: dashed;
}

/* ---------- phase-01 component kit ---------- */

/* Button sizes + loading */
.ui-button--compact {
  height: var(--density-compact);
  padding: 0 var(--space-2);
  font-size: var(--text-s);
}
.ui-button--touch {
  height: var(--density-loose);
  padding: 0 var(--space-4);
}
.ui-button__spinner {
  width: 0.85em;
  height: 0.85em;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: ui-spin 0.7s linear infinite;
}
.ui-button__icon {
  display: inline-flex;
}
@keyframes ui-spin {
  to {
    transform: rotate(360deg);
  }
}
.ui-spinner {
  display: inline-block;
  width: 1rem;
  height: 1rem;
  border: 2px solid var(--theme-border-strong);
  border-top-color: var(--theme-accent);
  border-radius: 50%;
  animation: ui-spin 0.7s linear infinite;
}

/* Field help/error */
.ui-field__help {
  color: var(--theme-text-muted);
  font-size: var(--text-s);
  margin: 0;
}
.ui-field__error {
  color: var(--theme-danger);
  font-size: var(--text-s);
  font-weight: 500;
  margin: 0;
}
.ui-field__required {
  color: var(--theme-danger);
}
.ui-field--invalid .ui-field__input,
.ui-field__input[aria-invalid="true"] {
  border-color: var(--theme-danger);
}

/* Affixed input (unit/prefix inside the box) */
.ui-input-affix {
  align-items: stretch;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: inline-flex;
  height: var(--control-height);
  overflow: hidden;
}
.ui-input-affix.is-invalid {
  border-color: var(--theme-danger);
}
.ui-input-affix:focus-within {
  border-color: var(--theme-accent);
}
.ui-input-affix__part {
  align-items: center;
  background: var(--theme-surface-card);
  color: var(--theme-text-secondary);
  display: inline-flex;
  font-size: var(--text-s);
  padding: 0 var(--space-2);
}
.ui-input-affix .ui-field__input--bare {
  border: none;
  border-radius: 0;
  height: 100%;
  min-width: 0;
}
.ui-input-affix .ui-field__input--bare:focus {
  border-color: transparent;
}

/* Select with chevron + empty note */
.ui-select-wrap {
  display: inline-block;
  position: relative;
}
.ui-select {
  appearance: none;
  padding-right: calc(var(--space-4) + 10px);
  width: 100%;
}
.ui-select__chevron {
  color: var(--theme-text-secondary);
  pointer-events: none;
  position: absolute;
  right: var(--space-2);
  top: 50%;
  transform: translateY(-50%);
}
.ui-select-wrap.is-invalid .ui-select {
  border-color: var(--theme-danger);
}
.ui-select-empty {
  align-items: center;
  color: var(--theme-text-muted);
  display: inline-flex;
  font-size: var(--text-body);
  font-style: normal;
}

/* Tabs — underline + weight, never color alone */
.ui-tabs {
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: var(--space-1);
  overflow-x: auto;
}
.ui-tab {
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-family: inherit;
  font-size: var(--text-body);
  font-weight: 500;
  padding: var(--space-2) var(--space-3);
  text-decoration: none;
  white-space: nowrap;
}
.ui-tab:hover {
  color: var(--theme-text-primary);
}
.ui-tab.is-active {
  border-bottom-color: var(--theme-accent);
  color: var(--theme-text-primary);
  font-weight: 600;
}
.ui-tab[aria-disabled="true"] {
  color: var(--theme-disabled-ink);
  cursor: not-allowed;
}

/* Page header — one row, breadcrumb above the title */
.ui-page-header {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding-bottom: var(--space-3);
}
.ui-crumbs {
  color: var(--theme-text-muted);
  display: flex;
  flex-wrap: wrap;
  font-size: var(--text-s);
  gap: var(--space-1);
}
.ui-crumbs a {
  color: var(--theme-text-secondary);
  text-decoration: none;
}
.ui-crumbs a:hover {
  color: var(--theme-accent);
  text-decoration: underline;
}
.ui-crumb__sep {
  margin: 0 var(--space-1);
}
.ui-page-header__row {
  align-items: flex-start;
  display: flex;
  gap: var(--space-4);
  justify-content: space-between;
}
.ui-page-header__main {
  min-width: 0;
}
.ui-page-header__title {
  font-size: var(--text-display);
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.15;
  margin: 0;
}
.ui-page-header__context {
  color: var(--theme-text-secondary);
  font-size: var(--text-s);
  margin: var(--space-1) 0 0;
}
.ui-page-header__actions {
  align-items: center;
  display: flex;
  flex-shrink: 0;
  gap: var(--space-2);
}

/* Data table — aligned figures, readable header, own scroll container */
.ui-table-wrap {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  overflow-x: auto;
}
.ui-table {
  border-collapse: collapse;
  font-size: var(--text-body);
  width: 100%;
}
.ui-table th {
  background: var(--theme-surface-card);
  border-bottom: 1px solid var(--theme-border-strong);
  color: var(--theme-text-secondary);
  font-size: var(--text-s);
  font-weight: 600;
  padding: var(--space-2) var(--space-3);
  text-align: left;
  white-space: nowrap;
}
.ui-table td {
  border-bottom: 1px solid var(--theme-border-subtle);
  padding: var(--space-2) var(--space-3);
  vertical-align: middle;
}
.ui-table tbody tr:last-child td {
  border-bottom: none;
}
.ui-table tbody tr:hover {
  background: var(--theme-surface-hover);
}
.ui-table .ui-table__num {
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
}
.ui-table .ui-table__id {
  font-family: var(--font-mono);
  font-size: var(--text-s);
  white-space: nowrap;
}
.ui-table--compact td {
  padding: var(--space-1) var(--space-3);
}
.ui-table [aria-sort] button {
  align-items: center;
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-weight: inherit;
  gap: var(--space-1);
  padding: 0;
}

/* Tech details — collapsed, copiable, never dominant */
.ui-tech {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
}
.ui-tech__summary {
  align-items: center;
  color: var(--theme-text-secondary);
  cursor: pointer;
  display: flex;
  font-size: var(--text-s);
  gap: var(--space-2);
  justify-content: space-between;
  list-style: none;
  padding: var(--space-2) var(--space-3);
}
.ui-tech__summary::-webkit-details-marker {
  display: none;
}
.ui-tech__summary::before {
  content: "▸";
  font-size: var(--text-xs);
}
.ui-tech[open] .ui-tech__summary::before {
  content: "▾";
}
.ui-tech__copy {
  background: none;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-size: var(--text-xs);
  padding: 2px var(--space-2);
}
.ui-tech__copy:hover {
  border-color: var(--theme-border-strong);
  color: var(--theme-text-primary);
}
.ui-tech__body {
  border-top: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-secondary);
  font-size: var(--text-s);
  padding: var(--space-3);
}
.ui-tech__pre {
  font-family: var(--font-mono);
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-all;
}

/* Toast region — brief confirmations only; errors stay beside the work */
.ui-toast-region {
  bottom: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  position: fixed;
  right: var(--space-4);
  z-index: var(--z-overlay);
}
.ui-toast {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-success);
  border-radius: var(--radius-md);
  box-shadow: var(--elevation-2);
  color: var(--theme-text-primary);
  font-size: var(--text-body);
  max-width: 22rem;
  padding: var(--space-2) var(--space-3);
}
.ui-toast--info {
  border-left-color: var(--theme-accent);
}

.projects-page {
  /* Match .dashboard's workspace width — 96rem left ~190px dead rails on each
   * side of a 1920 viewport while master-detail panes could use them. */
  max-width: 120rem;
  margin-inline: auto;
  color: var(--theme-text-primary);
  font-size: 0.875rem;
}
.projects-page h1 {
  font-size: var(--text-display);
  font-weight: 600;
  margin-bottom: 0.75rem;
}
.projects-page h2 {
  font-size: var(--text-title);
  font-weight: 600;
}
.projects-page a.primary-action {
  color: var(--theme-surface-panel);
  margin-top: 0;
}
.projects-page form {
  margin-block: 1rem;
  padding: 1rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  background: var(--theme-surface-panel);
}
.projects-page fieldset {
  display: grid;
  gap: 0.75rem;
  min-width: 0;
  padding: 0;
  border: 0;
}
.projects-page label {
  display: grid;
  gap: 0.375rem;
  margin-block: 0.75rem;
}
.projects-page input,
.projects-page textarea,
.projects-page button {
  padding: 0.625rem;
  font: inherit;
  color: var(--theme-text-primary);
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
}
.projects-page textarea {
  min-height: 5rem;
  resize: vertical;
}
.projects-page :focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 2px;
}
.projects-page a {
  color: var(--theme-accent);
}
.projects-page [role="alert"] {
  color: var(--theme-danger);
}
.projects-page button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.projects-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.projects-table {
  overflow-x: auto;
}
.projects-table table {
  width: 100%;
  border-collapse: collapse;
}
.projects-table caption,
.projects-table th,
.projects-table td {
  padding: 0.625rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--theme-border-subtle);
}
.projects-page dd {
  margin: 0 0 0.75rem;
  white-space: pre-wrap;
  overflow-wrap: break-word;
}
.project-metadata {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 1.5rem;
  row-gap: 0.25rem;
}
/* The right-rail inspector is ~280px: a 3-col grid there shreds values
 * mid-token («Neto $247.2 99»). Label-left/value-right rows never split a
 * token and survive long location tags. */
.position-detail .project-metadata {
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 0.75rem;
  row-gap: 0.35rem;
}
.position-detail .project-metadata > div {
  display: contents;
}
.position-detail .project-metadata dd {
  margin: 0;
  overflow-wrap: normal;
  text-align: right;
}
.project-metadata dt {
  color: var(--theme-text-secondary);
  font-size: 0.8125rem;
}
.project-metadata-form > fieldset {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 1.25rem;
}
.project-metadata-form > fieldset > button {
  justify-self: start;
}
/* The optional-fields disclosure spans the grid; its inner rows keep the
 * same two-column rhythm as the required fields above it (review m11). */
.project-metadata__extra {
  grid-column: 1 / -1;
}
.project-metadata__extra > summary {
  color: var(--theme-text-muted);
  cursor: pointer;
  font-size: var(--text-s);
  padding: var(--space-1) 0;
}
.project-metadata__extra[open] {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 1.25rem;
}
.project-metadata__extra[open] > summary {
  grid-column: 1 / -1;
}
@media (max-width: 700px) {
  .project-metadata__extra[open] {
    grid-template-columns: 1fr;
  }
}
/* Required marker lives inside the label text (aria-hidden) so it never
 * orphans onto its own line below the control. */
.form-required {
  color: var(--theme-accent);
}
.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-2);
}
@media (max-width: 700px) {
  .project-metadata,
  .project-metadata-form > fieldset,
  .projects-page .quotation-form,
  .quotation-form fieldset,
  .quotation-history li {
    grid-template-columns: 1fr;
  }
}
.projects-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  padding-bottom: 0.75rem;
}
.projects-header > div {
  flex: 1;
}
.projects-header h1 {
  font-size: var(--text-display);
  line-height: 1.5;
}
/* Vano header strip — location/quantity/system are the position's own
   fields, edited in the workspace header rather than buried in a rail. */
.position-head {
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-3);
}

/* fieldset ignores display:flex on its children — the row carries the layout. */
.position-head__row {
  align-items: end;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

.position-head__field {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 7rem;
}

/* The finish picker sits beside the system field — same field language as
   position metadata, narrower: it never takes the wide grid cell. */
.position-head__color {
  align-self: center;
  display: flex;
  flex-direction: column;
  font-size: var(--text-xs);
  gap: var(--space-1);
}

.position-head__color > span {
  color: var(--theme-text-muted);
}

.position-head__field--wide {
  flex: 1;
  min-width: 12rem;
}

.position-head__field > span {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
}

.position-head__field input,
.position-head__field select {
  font: inherit;
  padding: var(--space-1) var(--space-2);
}

.position-head__hint,
.position-head__alert {
  align-self: center;
  color: var(--theme-text-muted);
  flex-basis: 100%;
  font-size: var(--text-xs);
  margin: 0;
}

.position-head__alert[role="alert"] {
  color: var(--theme-danger);
}

.position-workspace {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: minmax(0, 1fr);
  margin-top: 1rem;
}

/* The position editor is a design tool, not a form page — it uses the full
   shell width and height: the route is a bounded app viewport where the
   canvas dominates; the BOM scrolls inside the body region. */
.position-editor {
  display: flex;
  flex-direction: column;
  height: calc(100dvh - 4.875rem);
  max-height: calc(100dvh - 4.875rem);
  max-width: none;
}

.position-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  /* The editor route is a bounded app viewport — the body never scrolls, so a
     wheel gesture over the canvas pans the drawing instead of trapping the
     page scroll. Ancillary content (BOM) docks below in its own scroller. */
  overflow: hidden;
}

.position-body .position-workspace {
  flex: 1;
  grid-template-rows: auto minmax(0, 1fr);
  min-height: 0;
}

.position-body .assembly-editor {
  height: 100%;
}
@media (max-height: 700px) {
  /* Short laptop screens: let the editor shrink below the 28rem floor rather
     than clip its status bar under the non-scrolling body. */
  .position-body .assembly-editor {
    min-height: 0;
  }
}

/* Unsaved-draft recovery banner — a reload no longer silently discards the
   in-flight design; the offer sits between the header and the form strip. */
.draft-banner {
  align-items: center;
  background: var(--theme-surface-raised, var(--theme-surface-panel));
  border: 1px solid var(--theme-accent);
  border-radius: var(--radius-md);
  display: flex;
  gap: 0.6rem;
  margin-bottom: 0.6rem;
  padding: 0.45rem 0.75rem;
}

.draft-banner span {
  color: var(--theme-text-secondary);
  flex: 1;
  font-size: 0.82rem;
}

.draft-banner button {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-size: 0.78rem;
  padding: 0.22rem 0.6rem;
}

.draft-banner button:first-of-type {
  border-color: var(--theme-accent);
  color: var(--theme-accent-ink, var(--theme-accent));
}

/* Position metadata folded into the inspector column — compact fields, same
   visual language as the module inspector. */
.position-panel fieldset {
  border: none;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin: 0;
  padding: 0.4rem 0.75rem 0.6rem;
}

.position-panel .assembly-field input,
.position-panel .assembly-select {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font: inherit;
  padding: 0.3rem 0.45rem;
  text-align: left;
  width: 100%;
}

.position-panel .assembly-field {
  align-items: stretch;
  flex-direction: column;
  gap: 0.15rem;
}

.position-panel .assembly-input-wrap {
  display: flex;
  width: 100%;
}

.position-panel .assembly-input-wrap input {
  flex: 1;
}

.position-panel .assembly-field > span {
  color: var(--theme-text-secondary);
  font-size: 0.78rem;
}
.projects-page select {
  font: inherit;
  color: inherit;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.625rem;
  width: 100%;
}
.quotation-panel {
  margin-block: 1.25rem;
  padding-block: 1rem;
  border-block: 1px solid var(--theme-border-subtle);
}
.quotation-panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.quotation-panel > header p {
  margin-block: 0.25rem 0;
  color: var(--theme-text-secondary);
}
.projects-page .quotation-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 1rem;
  padding-inline: 0;
  border-inline: 0;
  border-radius: 0;
}
.quotation-form fieldset {
  grid-column: 1 / -1;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--theme-border-subtle);
}
.quotation-form legend {
  font-weight: 600;
}
.quotation-form .quotation-confirm,
.quotation-form .projects-actions {
  grid-column: 1 / -1;
}
.handle-inputs {
  grid-column: 1 / -1;
  margin-top: 0.5rem;
}
.handle-inputs h4 {
  margin: 0 0 0.375rem;
  font-size: 0.8125rem;
  font-weight: 600;
}
.handle-row {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) minmax(0, 1.2fr) auto;
  gap: 0.75rem;
  align-items: end;
  padding: 0.375rem 0;
  border-top: 1px solid var(--theme-border-subtle);
}
.handle-leaf {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-width: 0;
}
.handle-leaf strong {
  font-weight: 600;
}
.handle-leaf span {
  font-size: 0.8125rem;
  color: var(--theme-text-muted);
}
.handle-field {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-width: 0;
}
.handle-field > label {
  font-size: 0.75rem;
  color: var(--theme-text-muted);
}
.handle-bounds {
  font-size: 0.75rem;
  color: var(--theme-text-muted);
  font-variant-numeric: tabular-nums;
}
.handle-pending {
  align-self: center;
  padding: 0.125rem 0.5rem;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  color: var(--theme-warning);
  background: var(--theme-warning-soft);
  white-space: nowrap;
}

/* Block-band variant: the save-blocked reason sits under the header as a
 * status line — it must never share a flex row with the action buttons. */
p.handle-pending {
  border-radius: var(--radius-sm);
  display: block;
  margin: 0.4rem 0 0;
  padding: 0.3rem 0.6rem;
  white-space: normal;
}
.handle-suggested {
  align-self: center;
  padding: 0.125rem 0.5rem;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  color: var(--theme-accent);
  background: var(--theme-accent-soft);
  white-space: nowrap;
}
.handle-suggested-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin: 0.25rem 0 0.5rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--theme-accent-soft);
  border-radius: var(--radius-md);
  font-size: 0.8125rem;
  color: var(--theme-text-muted);
  background: color-mix(in srgb, var(--theme-accent-soft) 40%, transparent);
}
.handle-suggested-confirm {
  white-space: nowrap;
}
.handle-row input[aria-invalid="true"] {
  border-color: var(--theme-danger);
}
.workshop-inputs {
  grid-column: 1 / -1;
  margin-top: 0.5rem;
}
.workshop-inputs > summary {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--theme-text-muted);
  cursor: pointer;
  list-style: none;
}
.workshop-inputs > summary::before {
  content: "▸ ";
  color: var(--theme-accent);
}
.workshop-inputs[open] > summary::before {
  content: "▾ ";
}
.workshop-target {
  padding: 0.375rem 0;
  border-top: 1px solid var(--theme-border-subtle);
}
.workshop-target > strong {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}
.workshop-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: end;
}
.workshop-field {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-width: 0;
  font-size: 0.75rem;
  color: var(--theme-text-muted);
}
.workshop-field input {
  min-width: 9rem;
}
.workshop-field--wide input {
  min-width: 18rem;
}
.workshop-unit {
  font-size: 0.6875rem;
  color: var(--theme-text-muted);
  font-variant-numeric: tabular-nums;
}
.workshop-check {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.8125rem;
  white-space: nowrap;
}
.workshop-group {
  margin-top: 0.5rem;
}
.workshop-group > h5 {
  margin: 0 0 0.25rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--theme-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.workshop-accessories {
  display: grid;
  gap: 0.375rem;
  margin-top: 0.375rem;
}
.workshop-accessory {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
  align-items: center;
  padding: 0.375rem 0;
  border-top: 1px solid var(--theme-border-subtle);
}
.workshop-accessory input,
.workshop-accessory select {
  min-width: 0;
}
.workshop-accessory .ghost-button.is-danger {
  color: var(--theme-danger);
  justify-self: end;
}
@media (max-width: 1100px) {
  .workshop-accessory {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
.quotation-form .quotation-confirm {
  display: flex;
  grid-template-columns: auto 1fr;
  align-items: start;
}
.quotation-history ul {
  display: grid;
  gap: 0.5rem;
  padding: 0;
  list-style: none;
}
.quotation-history li {
  display: grid;
  grid-template-columns: 5rem minmax(10rem, 1fr) minmax(12rem, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  padding-block: 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
}
.quotation-share {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0.375rem 0;
}
.quotation-links ul {
  display: grid;
  gap: 0.5rem;
  padding: 0;
  list-style: none;
}
.quotation-link {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.625rem;
  padding-block: 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
}
.quotation-link__meta {
  color: var(--theme-text-secondary);
  font-size: 0.8125rem;
}
.position-thumb-host {
  align-self: start;
}
.position-thumb {
  align-self: start;
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  display: block;
  height: 7.5rem;
  object-fit: contain;
  width: 9rem;
}
.project-locked {
  background: var(--theme-accent-soft);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-mark);
  border-radius: 0.375rem;
  color: var(--theme-text-primary);
  margin: 0.5rem 0;
  padding: 0.625rem 0.875rem;
}
.cut-bar {
  background: var(--theme-border-subtle);
  border-radius: var(--radius-pill);
  display: block;
  height: 0.3125rem;
  margin-top: 0.25rem;
  max-width: 9rem;
  overflow: hidden;
}
.cut-bar > span {
  background: var(--theme-accent);
  border-radius: var(--radius-pill);
  display: block;
  height: 100%;
}
@media (max-width: 640px) {
  .position-thumb {
    width: 100%;
  }
}
/* BOM docks at the bottom of the bounded editor viewport: a slim bar when
   closed, a capped pane with its own scroll when opened — the page column
   itself never scrolls. */
.project-bom {
  flex: none;
  margin-top: 0.5rem;
}
.project-bom[open] {
  max-height: 42dvh;
  overflow-y: auto;
}
.project-bom summary {
  cursor: pointer;
  padding: 0.5rem 0;
}
.projects-table-scroll {
  overflow-x: auto;
}
.projects-table-scroll table {
  width: 100%;
  border-collapse: collapse;
}
.projects-table-scroll th,
.projects-table-scroll td {
  text-align: left;
  padding: 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
}
@media (max-width: 960px) {
  .position-workspace {
    grid-template-columns: 1fr;
  }
}

/* Design library — starter cards previewed through the product renderer */
.starter-library {
  margin-bottom: 0.75rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  background: var(--theme-surface-panel);
  min-width: 0;
}
.starter-library > summary {
  cursor: pointer;
  padding: 0.625rem 0.75rem;
  font-weight: 600;
  color: var(--theme-text-primary);
  list-style: none;
}
.starter-library > summary::before {
  content: "▸";
  display: inline-block;
  margin-right: 0.5rem;
  color: var(--theme-accent);
  transition: transform 0.12s ease;
}
.starter-library[open] > summary::before {
  transform: rotate(90deg);
}
.starter-gallery-wrap {
  padding: 0.25rem 0.75rem 0.75rem;
}
.starter-search {
  display: block;
  margin-bottom: 0.5rem;
  max-width: 22rem;
}
.starter-search input {
  width: 100%;
}
.starter-empty {
  color: var(--theme-text-secondary, #727d82);
  font-size: 0.8125rem;
  margin: 0.5rem 0;
}
.starter-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(7.5rem, 1fr));
  gap: 0.625rem;
  max-width: 100%;
  min-width: 0;
  /* Wrap over scroll: a hidden tail row made contour/door starters
   * undiscoverable; the enclosing <details> already owns the vertical
   * budget, so showing every starter costs the user nothing. */
  overflow-x: visible;
  padding: 0;
}
.starter-card {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.5rem;
  text-align: left;
  cursor: pointer;
}
.starter-card:hover:not(:disabled) {
  border-color: var(--theme-accent);
}
.starter-card:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.starter-thumb {
  display: block;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.25rem;
  background: var(--theme-surface-panel);
}
.starter-thumb svg {
  width: 100%;
  height: 100%;
  display: block;
}
.starter-card-title {
  font-weight: 600;
  color: var(--theme-text-primary);
}
.starter-card-hint {
  font-size: 0.75rem;
  color: var(--theme-text-secondary, #727d82);
}

.projects-payments {
  margin-top: 12px;
}
.payments-summary {
  display: grid;
  gap: 8px;
}
.payments-summary-facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 8px;
  margin: 0;
}
.payments-summary-facts dt {
  color: var(--ink-muted);
  font-size: var(--text-s, 12px);
}
.payments-summary-facts dd {
  margin: 0;
  font-family: var(--font-mono, monospace);
}
.payments-progress {
  height: 6px;
  border-radius: var(--radius-sm);
  background: var(--surface-sunken, #e8e6e1);
  overflow: hidden;
}
.payments-progress > div {
  height: 100%;
  background: var(--accent);
  transition: width 0.3s ease;
}
.imports-empty {
  color: var(--theme-text-secondary);
  font-size: 0.9rem;
}
.imports-file-input {
  display: none;
}
.imports-hint {
  color: var(--theme-text-secondary);
  font-size: 0.85rem;
  margin: 4px 0 8px;
}
.imports-warning {
  color: var(--theme-warning, #e56a32);
  font-size: 0.8rem;
  margin: 0 0 6px;
  padding-inline-start: 16px;
}
.imports-review {
  margin-top: 12px;
  border-top: 1px solid var(--theme-border-subtle);
  padding-top: 10px;
}
.imports-review-fields {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 8px 14px;
  margin-bottom: 10px;
}
.imports-review-fields label {
  display: grid;
  gap: 3px;
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
.imports-row-error td {
  background: color-mix(in srgb, var(--theme-warning, #e56a32) 10%, transparent);
}
.imports-toggle {
  font-weight: 600;
}

/* R3 — the project desk: facts rail (left) · positions grid (center) ·
   selected-vano detail (right). The three panes track the job, not the
   database — facts collapse when the estimator needs the room. */
.project-desk {
  align-items: start;
  display: grid;
  gap: 1rem;
  grid-template-columns: minmax(15rem, 19rem) minmax(0, 1fr) minmax(15rem, 21rem);
}

/* An open workflow section (quote/payments/imports/compare) is real work —
 * the emission form needs far more than the idle rail's 15–19rem; steal from
 * the positions column while it is open (review WM4). Desktop only — under
 * the 1100px breakpoint the desk stays a single column. */
@media (min-width: 1101px) {
  .project-desk[data-facts-open] {
    grid-template-columns: minmax(26rem, 34vw) minmax(0, 1fr) minmax(13rem, 17rem);
  }

  /* Emission is a form-heavy workflow — the rail gets the workspace width
   * while it is open, the positions grid shrinks to a reference column. */
  .project-desk[data-facts-open="quote"] {
    grid-template-columns: minmax(38rem, 55vw) minmax(0, 1fr) minmax(11rem, 14rem);
  }
}

.project-facts {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg, 0.5rem);
  max-height: calc(100vh - 11rem);
  overflow: auto;
  padding: 0.75rem;
  position: sticky;
  top: 0.75rem;
}

.project-facts[data-collapsed] {
  padding: 0.5rem;
}

.project-facts__head {
  align-items: center;
  display: flex;
  gap: 0.5rem;
  justify-content: space-between;
}

.project-facts__list {
  display: grid;
  gap: 0.375rem 0.75rem;
  /* 10.5rem keeps names/tags from column-cramming into mid-token wraps; the
   * hyphenation below turns unavoidable long-word splits into real breaks. */
  grid-template-columns: repeat(auto-fill, minmax(10.5rem, 1fr));
  margin: 0.75rem 0 0;
}

.project-facts__list dd {
  hyphens: auto;
  min-width: 0;
}

.project-facts__section {
  border-top: 1px solid var(--theme-border-subtle);
  margin-top: 0.75rem;
  padding-top: 0.5rem;
}

.project-facts__section > summary {
  cursor: pointer;
  font-weight: 600;
  padding: 0.25rem 0;
}

.position-grid {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.position-row {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md, 0.375rem);
  cursor: pointer;
  display: grid;
  gap: 0.625rem;
  grid-template-columns: 5.5rem minmax(6rem, 1fr) 8.5rem 4.5rem auto;
  padding: 0.5rem 0.75rem;
}

.position-row:hover {
  border-color: var(--theme-accent);
}

.position-row[data-selected] {
  border-color: var(--theme-accent);
  box-shadow: inset 2px 0 0 var(--theme-accent);
}

.position-row:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 1px;
}

.position-row__thumb {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm, 0.25rem);
  display: block;
  height: 4.25rem;
  overflow: hidden;
  width: 5.5rem;
}

/* The studio render is sized for cards — inside the row it must fit the
 * thumb cell instead of cropping the product's edges. */
.position-row__thumb svg,
.position-row__thumb .position-thumb,
.position-row__thumb .position-thumb-host {
  display: block;
  height: 100%;
  object-fit: contain;
  width: 100%;
}

.position-row__loc {
  display: -webkit-box;
  font-weight: 500;
  min-width: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  /* A location name is the position's identity — "Cocina, ventana sobre
   * mesón" clipped to "Cocina, ventana sobre…" reads as a different vano;
   * wrap to two lines instead of truncating (review WM7). */
  white-space: normal;
}

.position-row__dims {
  color: var(--theme-text-secondary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.position-row__spec {
  color: var(--theme-text-muted);
  font-size: 0.8125rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Mobile: the five-column row can't fit 390 px — stack it into a two-row
 * grid (thumb + identity, then specs/qty/status) instead of h-scrolling. */
@media (max-width: 640px) {
  .position-row {
    grid-template-columns: 4rem 1fr;
    row-gap: 0.375rem;
  }

  .position-row__thumb {
    grid-row: span 3;
    height: 5rem;
    width: 4rem;
  }

  .position-row__spec,
  .position-row__dims {
    white-space: normal;
  }
}

.position-row__qty-input {
  max-width: 4.25rem;
}

.project-desk__side {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg, 0.5rem);
  max-height: calc(100vh - 11rem);
  overflow: auto;
  padding: 0.875rem;
  position: sticky;
  top: 0.75rem;
}

.project-desk__hint {
  color: var(--theme-text-muted);
}

.position-detail__thumb .position-thumb,
.position-detail__thumb .position-thumb-studio {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  height: 12rem;
  object-fit: contain;
  width: 100%;
}

.position-detail .project-metadata {
  margin: 0.5rem 0 0.75rem;
}

@media (max-width: 1100px) {
  .project-desk {
    grid-template-columns: minmax(0, 1fr);
  }

  .project-facts,
  .project-desk__side {
    max-height: none;
    position: static;
  }
}

.imports-evidence-toggle {
  font-size: 0.75rem;
  margin-inline-end: 6px;
  padding: 1px 8px;
}
.imports-evidence-row td {
  background: var(--theme-surface-sunken, rgba(0, 0, 0, 0.04));
  font-size: 0.8rem;
  padding: 6px 12px;
}
.imports-evidence-ref {
  display: inline-block;
  margin-inline-end: 8px;
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--theme-text-secondary);
}
.imports-evidence-text {
  display: block;
  margin: 2px 0 6px;
  white-space: pre-wrap;
  font-size: 0.78rem;
  color: var(--theme-text-primary);
}
.imports-existing {
  display: block;
  font-size: 0.78rem;
  color: var(--theme-warning, #e56a32);
}

/* §03-C/F — project workspace header + commercial track */
.project-head {
  margin-bottom: var(--space-3);
}

.project-head__row {
  align-items: start;
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
}

.project-head__row h1 {
  margin: 0;
}

.projects-row__code {
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.75rem;
  margin-left: 0.5rem;
  white-space: nowrap;
}

.projects-row__rev {
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.8125rem;
  white-space: nowrap;
}

.projects-row__next {
  color: var(--theme-text-muted);
  font-size: 0.8125rem;
  max-width: 14rem;
}

.projects-list-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
  margin-bottom: 0.75rem;
}

.projects-list-bar .ui-field {
  margin-bottom: 0;
  min-width: 10rem;
}

.projects-list-bar .projects-search {
  flex: 1 1 14rem;
  max-width: 24rem;
}

.project-activity {
  list-style: none;
  margin: 0;
  padding: 0;
}

.project-activity li {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.5rem;
  padding: 0.4rem 0;
  border-bottom: 1px solid var(--theme-border);
  font-size: 0.8125rem;
}

.project-activity li:last-child {
  border-bottom: 0;
}

.project-activity__label {
  font-weight: 500;
}

.project-activity__detail {
  color: var(--theme-text-muted);
}

.project-activity time {
  color: var(--theme-text-muted);
  margin-left: auto;
  white-space: nowrap;
}

.project-activity__empty {
  color: var(--theme-text-muted);
}

.project-head__code {
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.75rem;
  font-weight: 400;
  white-space: nowrap;
}

.project-head__meta {
  align-items: center;
  color: var(--theme-text-secondary);
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  margin: 0.375rem 0 0;
}

.project-head__action {
  display: flex;
  flex-shrink: 0;
  gap: 0.5rem;
}

.commercial-track {
  display: grid;
  gap: 0.375rem;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  list-style: none;
  margin: var(--space-3) 0 0;
  padding: 0;
}

.commercial-step {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  display: grid;
  gap: 0.125rem;
  min-width: 0;
  padding: 0.5rem 0.625rem;
}

.commercial-step__marker {
  align-self: start;
  border: 2px solid var(--theme-border-strong, var(--theme-text-secondary));
  border-radius: 50%;
  height: 0.625rem;
  margin-bottom: 0.25rem;
  width: 0.625rem;
}

.commercial-step__label {
  font-size: 0.75rem;
  font-weight: 600;
}

.commercial-step__detail {
  color: var(--theme-text-secondary);
  font-size: 0.6875rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.commercial-step[data-state="done"] {
  border-color: var(--theme-accent);
}

.commercial-step[data-state="done"] .commercial-step__marker {
  background: var(--theme-accent);
  border-color: var(--theme-accent);
}

.commercial-step[data-state="current"] {
  border-color: var(--theme-accent);
}

.commercial-step[data-state="current"] .commercial-step__marker {
  border-color: var(--theme-accent);
  box-shadow: 0 0 0 3px var(--theme-accent-soft, rgba(37, 99, 235, 0.15));
}

.commercial-step[data-state="current"] .commercial-step__label {
  color: var(--theme-accent);
}

.commercial-step[data-state="blocked"] {
  border-color: var(--theme-warning);
}

.commercial-step[data-state="blocked"] .commercial-step__label {
  color: var(--theme-warning);
}

.commercial-step[data-state="pending"] {
  color: var(--theme-text-secondary);
}

@media (max-width: 1100px) {
  .commercial-track {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* §03-E — revision compare */
.compare-panel {
  display: grid;
  gap: 0.625rem;
  margin-top: 0.375rem;
}

.compare-controls {
  align-items: end;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.compare-controls .ui-field {
  min-width: 10rem;
}

.compare-summary {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  font-size: 0.8125rem;
  margin: 0;
  padding: 0.5rem 0.75rem;
}

.compare-list {
  display: grid;
  gap: 0.375rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.compare-row {
  align-items: start;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  display: grid;
  gap: 0.625rem;
  grid-template-columns: 2rem auto minmax(0, 1fr) auto;
  padding: 0.5rem 0.625rem;
}

.compare-row[data-change="added"] {
  border-left: 3px solid var(--theme-accent);
}

.compare-row[data-change="removed"] {
  border-left: 3px solid var(--theme-danger);
  opacity: 0.8;
}

.compare-row[data-change="changed"] {
  border-left: 3px solid var(--theme-warning);
}

.compare-row__index {
  color: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-weight: 600;
}

.compare-row__thumbs {
  align-items: center;
  display: flex;
  gap: 0.25rem;
}

.compare-thumb svg {
  height: 3.5rem;
  width: auto;
}

.compare-arrow {
  color: var(--theme-text-secondary);
}

.compare-row__main {
  display: grid;
  gap: 0.125rem;
  min-width: 0;
}

.compare-row__loc {
  font-weight: 600;
}

.compare-row__dims,
.compare-row__detail {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.compare-row__changes {
  font-size: 0.75rem;
  list-style: none;
  margin: 0.25rem 0 0;
  padding: 0;
}

.compare-row__changes li {
  border-top: 1px dashed var(--theme-border-subtle);
  padding: 0.125rem 0;
}

.compare-chip[data-status="added"] {
  background: var(--theme-accent-soft, rgba(37, 99, 235, 0.12));
  color: var(--theme-accent);
}

.compare-chip[data-status="removed"] {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

.compare-chip[data-status="changed"] {
  background: var(--theme-warning-soft, rgba(217, 119, 6, 0.12));
  color: var(--theme-warning);
}

.projects-error-actions {
  align-items: center;
  display: flex;
  gap: 1rem;
}

.position-row__net {
  color: var(--theme-text-secondary);
  font-size: 0.72rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.emit-checklist {
  background: var(--theme-warning-soft, rgba(217, 119, 6, 0.1));
  border: 1px solid var(--theme-warning);
  border-radius: 0.5rem;
  font-size: 0.8125rem;
  margin: 0.75rem 0;
  padding: 0.625rem 1rem;
}

.emit-checklist ul {
  margin: 0.375rem 0 0;
  padding-left: 1.125rem;
}

.emit-checklist .link-button {
  color: var(--theme-text-primary);
  font-size: inherit;
}

/* Pre-emit verdict: states what the revision will allow before Emitir runs
   (quote-only vs production-ready) — no silent downgrades. */
.emit-outcome {
  border-radius: 0.5rem;
  font-size: 0.8125rem;
  margin: 0.75rem 0 0;
  padding: 0.5rem 0.875rem;
}

.emit-outcome--warn {
  background: var(--theme-warning-soft, rgba(217, 119, 6, 0.1));
  border: 1px solid var(--theme-warning);
}

.canvas-editor {
  display: grid;
  gap: 0.75rem;
  min-height: 100%;
}

.canvas-toolbar {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.5rem 0.75rem;
}

.canvas-toolbar button.is-active {
  border-color: var(--theme-accent);
  color: var(--theme-accent);
}

.canvas-layout {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 280px);
  min-height: 0;
}

.cad-viewport,
.canvas-technical-results {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
}

.cad-viewport {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-height: clamp(30rem, calc(100vh - 15rem), 52rem);
}

.cad-viewport__heading {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  justify-content: space-between;
  padding: 0.75rem 1rem;
}

.cad-viewport__heading h1,
.canvas-technical-results h2 {
  font-size: 1rem;
  margin: 0.125rem 0 0;
}

.cad-viewport__heading p {
  margin: 0;
}

.canvas-system {
  color: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
}

.cad-svg {
  background: var(--theme-bg-canvas);
  height: 100%;
  min-height: 34rem;
  touch-action: none;
  width: 100%;
}

.frame-outline,
.glass-pane,
.resize-preview {
  vector-effect: non-scaling-stroke;
}

.frame-outline {
  fill: var(--theme-surface-card);
  stroke: var(--theme-text-primary);
  stroke-width: 5;
}

.glass-pane {
  fill: var(--theme-glass-tint);
  stroke: var(--theme-accent);
  stroke-width: 3;
}

.opening-label,
.glass-dimension {
  fill: var(--theme-text-primary);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 28px;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

.glass-dimension {
  fill: var(--theme-text-secondary);
  font-size: 22px;
}

.dimension-line,
.dimension-tick {
  stroke: var(--theme-text-secondary);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.dimension-editor {
  overflow: visible;
}

.dimension-editor__label {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  display: flex;
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  gap: 0.25rem;
  height: 36px;
  justify-content: center;
  padding: 0.25rem;
}

.dimension-editor input {
  background: var(--theme-bg-canvas);
  border: 1px solid transparent;
  font-variant-numeric: tabular-nums;
  min-width: 0;
  padding: 0.25rem;
  text-align: right;
  width: 7rem;
}

.resize-handle {
  cursor: ew-resize;
  fill: var(--theme-warning);
  stroke: var(--theme-surface-panel);
  stroke-width: 5;
  vector-effect: non-scaling-stroke;
}

.resize-handle[data-testid="resize-height"] {
  cursor: ns-resize;
}

.resize-handle:focus-visible {
  outline: none;
  stroke: var(--theme-accent);
  stroke-width: 8;
}

.resize-preview {
  fill: none;
  pointer-events: none;
  stroke: var(--theme-warning);
  stroke-dasharray: 8 5;
  stroke-width: 3;
}

.snap-guide {
  fill: none;
  pointer-events: none;
  stroke: var(--theme-success);
  stroke-dasharray: 6 4;
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.canvas-technical-results {
  padding: 1rem;
}

.canvas-technical-results dl {
  display: grid;
  gap: 0.75rem;
  margin: 1.25rem 0 0;
}

.canvas-technical-results dl div {
  background: var(--theme-surface-card);
  border-left: 3px solid var(--theme-accent);
  padding: 0.75rem;
}

.canvas-technical-results dt {
  color: var(--theme-text-secondary);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.canvas-technical-results dd {
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-variant-numeric: tabular-nums;
  margin: 0.25rem 0 0;
}

.canvas-error,
.canvas-progress {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  margin: 0;
  padding: 0.5rem 0.75rem;
}

.canvas-progress {
  color: var(--theme-text-secondary);
}

.visually-hidden {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

@media (max-width: 72rem) {
  .canvas-layout {
    grid-template-columns: 1fr;
  }

  .cad-viewport {
    min-height: 32rem;
  }
}

.assembly-editor {
  display: grid;
  gap: 0.75rem;
}

.assembly-field {
  align-items: center;
  display: flex;
  gap: 0.35rem;
}

.assembly-field > span {
  color: var(--theme-text-secondary);
  font-size: 0.85rem;
}

.assembly-field input {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font-variant-numeric: tabular-nums;
  padding: 0.25rem 0.4rem;
  text-align: right;
  width: 5.5rem;
}

/* Unit rides inside the input's right edge — in the column-stacked
 * .position-panel layout a loose unit span would wrap under the field. */
.assembly-input-wrap {
  align-items: center;
  display: inline-flex;
  position: relative;
}

.assembly-input-wrap input {
  padding-right: 1.5rem;
}

.assembly-unit {
  color: var(--theme-text-muted);
  font-size: 0.8rem;
  pointer-events: none;
  position: absolute;
  right: 0.45rem;
}

.assembly-field--inline {
  gap: 0.5rem;
}

.assembly-field--inline input[type="checkbox"] {
  width: auto;
}

.inspector-note {
  color: var(--theme-text-muted);
  font-size: 0.8rem;
  margin: 0 0 0.4rem;
}

.inspector-subhead {
  color: var(--theme-text-secondary);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  margin: 0.6rem 0 0.3rem;
  text-transform: uppercase;
}

.frameless-rows {
  display: grid;
  gap: 0.4rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.frameless-row {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.frameless-row select {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font-size: 0.8rem;
  padding: 0.2rem 0.3rem;
}

.frameless-row input[type="text"] {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font-size: 0.8rem;
  min-width: 0;
  padding: 0.25rem 0.4rem;
  width: 7rem;
}

.frameless-row input[type="number"] {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font-variant-numeric: tabular-nums;
  padding: 0.25rem 0.4rem;
  text-align: right;
  width: 3.5rem;
}

.frameless-edges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 0.9rem;
}

.assembly-canvas {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.5rem 0.75rem;
}

.bow-plan-svg {
  background: var(--theme-bg-canvas);
  display: block;
  min-height: 16rem;
  width: 100%;
}

.plan-module {
  cursor: pointer;
  fill: var(--theme-glass-tint);
  stroke: var(--theme-text-primary);
  stroke-width: 6;
  vector-effect: non-scaling-stroke;
}

.plan-module.is-selected {
  fill: var(--theme-surface-card);
  stroke: var(--theme-accent);
}

.plan-coupling {
  fill: var(--theme-surface-card);
  stroke: var(--theme-text-secondary);
  stroke-width: 4;
  vector-effect: non-scaling-stroke;
}

.plan-front-chain {
  stroke: var(--theme-accent);
  stroke-width: 2;
  stroke-dasharray: 6 4;
  vector-effect: non-scaling-stroke;
}

.plan-dimension {
  fill: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

.plan-dimension--total {
  fill: var(--theme-text-primary);
}

.assembly-status {
  border: 1px solid var(--theme-border-subtle);
  font-size: 0.85rem;
  margin-top: 0.5rem;
  padding: 0.4rem 0.6rem;
}

.assembly-status--valid {
  border-color: var(--theme-success);
  color: var(--theme-success);
}

.assembly-status--manufacturing_incomplete {
  border-color: var(--theme-warning);
  color: var(--theme-warning);
}

.assembly-status--invalid {
  border-color: var(--theme-danger);
  color: var(--theme-danger);
}

.assembly-status--idle {
  color: var(--theme-text-secondary);
}

.assembly-issues {
  color: var(--theme-text-secondary);
  font-size: 0.8rem;
  margin: 0.35rem 0 0;
  padding-left: 1.2rem;
}

/* Compositional editor — canvas-first workspace */
/* The editor is a self-contained application viewport: the grid is bounded by
   the window so the statusbar and plan inset are always on screen, and only the
   tree/side rails scroll internally. */
.assembly-editor {
  display: grid;
  gap: 0.6rem;
  grid-template-columns: 3rem 14rem minmax(0, 1fr) minmax(240px, 280px);
  grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas:
    "tools tree canvas side"
    "status status status side";
  height: calc(100vh - 12rem);
  height: calc(100dvh - 12rem);
  min-height: 28rem;
  position: relative;
}

/* Short viewports (1366×768 laptops): the fixed min-heights reserve more
 * than the screen can give — the canvas ends up clipped below the fold and
 * the product shrinks to a strip. Relax the floor so the grid actually
 * fills the available column. */
@media (max-height: 52.5rem) {
  .assembly-editor {
    height: calc(100dvh - 9.5rem);
    min-height: 20rem;
  }

  .canvas-viewport {
    min-height: 18rem;
  }

  .plan-inset {
    height: 7.5rem;
    width: 10.5rem;
  }
}

.assembly-editor--tree-closed {
  grid-template-columns: 3rem minmax(0, 1fr) minmax(250px, 300px);
  grid-template-areas:
    "tools canvas side"
    "status status side";
}

@media (max-width: 1100px) {
  .assembly-editor,
  .assembly-editor--tree-closed {
    grid-template-columns: 3rem minmax(0, 1fr) minmax(240px, 300px);
    grid-template-areas:
      "tools canvas side"
      "status status side";
  }

  /* The tree column collapses at this width; toggling it opens a drawer
     overlay above the canvas instead — the toggle stays functional. */
  .assembly-tree {
    background: var(--theme-surface-panel);
    border: 1px solid var(--theme-border-subtle);
    border-radius: var(--radius-md);
    bottom: 3.2rem;
    box-shadow: var(--shadow-pop);
    display: block;
    left: 3.8rem;
    max-width: min(18rem, 72vw);
    overflow: hidden;
    position: absolute;
    top: 0.4rem;
    width: 18rem;
    z-index: 6;
  }

  .assembly-tree .object-tree {
    border: none;
    border-radius: 0;
  }
}

/* Tablet portrait (~768px): a three-column grid leaves the canvas a sliver.
 * Stack instead — tools + full-width canvas on top, inspector below, the
 * page scrolls rather than squeezing the product. */
@media (max-width: 820px) {
  .assembly-editor,
  .assembly-editor--tree-closed {
    grid-template-columns: 3rem minmax(0, 1fr);
    grid-template-rows: minmax(20rem, 55dvh) auto auto;
    grid-template-areas:
      "tools canvas"
      "tools side"
      "status status";
    height: auto;
    min-height: 0;
  }

  .canvas-viewport {
    height: 100%;
    min-height: 20rem;
  }

  .assembly-side {
    overflow-y: visible;
  }
}

/* Left tool rail */
.assembly-tools {
  align-content: start;
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  gap: 2px;
  grid-area: tools;
  padding: 0.3rem 0;
}

.tool-button {
  align-items: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  display: flex;
  height: 2rem;
  justify-content: center;
  padding: 0;
  width: 2rem;
}

.tool-button:hover:not(:disabled) {
  background: var(--theme-surface-hover);
  color: var(--theme-text-primary);
}

.tool-button.is-active {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

.tool-button:disabled {
  color: var(--theme-text-muted);
  cursor: default;
  opacity: 0.45;
}

.tool-icon {
  fill: none;
  height: 1rem;
  stroke: currentColor;
  stroke-width: 1.2;
  width: 1rem;
}

.assembly-tools__divider {
  background: var(--theme-border-subtle);
  height: 1px;
  margin: 0.25rem 0;
  width: 1.4rem;
}

.assembly-tools__spacer {
  flex: 1;
}

/* Plan mini-navigator — inset over the canvas, never a second stacked sheet */
.assembly-canvas {
  position: relative;
}

.plan-inset {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  bottom: 0.75rem;
  box-shadow: var(--shadow-raise);
  display: flex;
  flex-direction: column;
  height: 9rem;
  position: absolute;
  right: 0.75rem;
  width: 13rem;
  z-index: 2;
  /* The card floats over the canvas; its empty area must not become a dead
   * zone that swallows clicks meant for the product behind it. Interactive
   * children (header, module/coupling shapes, angle handles) re-enable. */
  pointer-events: none;
}

.plan-inset__header,
.plan-inset .plan-module,
.plan-inset .plan-coupling,
.plan-inset .plan-angle,
.plan-inset .plan-issue-flag {
  pointer-events: auto;
}

.plan-inset__header {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-muted);
  display: flex;
  font-size: 0.72rem;
  font-weight: 600;
  justify-content: space-between;
  letter-spacing: 0.06em;
  padding: 0.3rem 0.5rem;
  text-transform: uppercase;
}

.plan-inset__header button {
  background: transparent;
  border: none;
  color: var(--theme-text-muted);
  cursor: pointer;
  font-size: 0.9rem;
  line-height: 1;
  padding: 0 0.15rem;
}

.plan-inset__svg {
  flex: 1;
  min-height: 0;
}

.plan-toggle {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  bottom: 0.75rem;
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-size: 0.78rem;
  padding: 0.3rem 0.6rem;
  position: absolute;
  right: 0.75rem;
  z-index: 2;
}

/* §16 3D view — larger inset panel; orbit/pan/zoom inside, same selection. */
.model3d-inset {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  bottom: 0.75rem;
  box-shadow: var(--shadow-raise);
  display: flex;
  flex-direction: column;
  height: 22rem;
  left: 0.75rem;
  position: absolute;
  width: 30rem;
  z-index: 3;
}

.model3d-inset .model3d-view {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}

.model3d-toolbar {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  gap: 0.25rem;
  padding: 0.3rem 0.5rem;
}

.model3d-toolbar button {
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-size: 0.72rem;
  padding: 0.18rem 0.5rem;
}

.model3d-toolbar button:hover {
  background: var(--theme-surface-hover);
}

.model3d-toolbar button.is-active {
  background: var(--theme-accent-soft);
  border-color: var(--theme-accent);
  color: var(--theme-accent-ink);
}

.model3d-face {
  color: var(--theme-text-muted);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  margin-left: auto;
  text-transform: uppercase;
}

.model3d-inset .model3d-view .model3d-canvas {
  flex: 1;
  min-height: 0;
}

/* Scene-build diagnostics — the physical truth the drawing could not
 * honour: undeclared kit skus, impossible handle datums, visual-only
 * hinge conventions. Shown as chips over the viewport, never a toast. */
.model3d-diagnostics {
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  padding: 0.3rem 0.5rem;
}

.model3d-diag {
  background: var(--theme-warning-soft, var(--theme-surface-card));
  border: 1px solid var(--theme-warning, var(--theme-border-strong));
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: help;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 0.08rem 0.4rem;
}

.model3d-diag--handle_out_of_range,
.model3d-diag--handle_datum_unsupported,
.model3d-diag--kit_unknown {
  border-color: var(--theme-danger, var(--theme-border-strong));
}

.model3d-illustrative {
  border-bottom: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-muted);
  font-size: 0.66rem;
  margin: 0;
  padding: 0.22rem 0.5rem;
}

.model3d-fallback {
  align-items: center;
  display: flex;
  justify-content: center;
  min-height: 12rem;
}

.model3d-fallback__text {
  color: var(--theme-text-secondary);
  font-size: 0.85rem;
  margin: 0;
  max-width: 22rem;
  text-align: center;
}

.model3d-loading {
  align-items: center;
  color: var(--theme-text-muted);
  display: flex;
  flex: 1;
  flex-direction: column;
  font-size: 0.78rem;
  gap: 10px;
  justify-content: center;
}
/* First open pulls the lazy three.js chunk (~2 s) — an indeterminate bar
   makes the wait legible instead of looking frozen. */
.model3d-loading__bar {
  width: 148px;
  height: 3px;
  border-radius: 2px;
  overflow: hidden;
  position: relative;
  background: var(--theme-skeleton);
}
.model3d-loading__bar::after {
  content: "";
  position: absolute;
  inset: 0;
  width: 40%;
  border-radius: 2px;
  background: var(--theme-accent);
  animation: model3d-slide 1.1s ease-in-out infinite;
}
@keyframes model3d-slide {
  0% {
    transform: translateX(-100%);
  }
  60%,
  100% {
    transform: translateX(260%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .model3d-loading__bar::after {
    animation: none;
    width: 100%;
  }
}

/* The 3D toggle stacks above the floating zoom cluster — both anchor
   bottom-left; one anchor must not swallow the other's hit area. */
.model3d-toggle {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  bottom: 3rem;
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-size: 0.78rem;
  padding: 0.3rem 0.6rem;
  position: absolute;
  left: 0.75rem;
  z-index: 2;
}

/* Status bar — compact persistent state */
.assembly-field-error {
  color: var(--theme-danger);
  display: block;
  font-size: 0.72rem;
  margin-top: 0.2rem;
}

.assembly-field.is-invalid input,
.canvas-dim-input.is-invalid {
  border-color: var(--theme-danger) !important;
}

.assembly-statusbar {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  gap: 0.9rem;
  grid-area: status;
  padding: 0.3rem 0.75rem;
  /* Above the canvas' floating islands (z2) — a scrolled viewport-status
   * chip must never underlap/intercept the issues button (render P2-7). */
  position: relative;
  z-index: 3;
}

.assembly-statusbar__dims {
  color: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 0.75rem;
  font-variant-numeric: tabular-nums;
}

.assembly-statusbar__selection {
  color: var(--theme-text-muted);
  font-size: 0.75rem;
}

.assembly-statusbar__issues {
  background: transparent;
  border: none;
  color: var(--theme-warning);
  cursor: pointer;
  font-size: 0.75rem;
  margin-left: auto;
  padding: 0;
}

/* Object tree — left rail, human names only */
.assembly-tree {
  grid-area: tree;
  min-height: 0;
}

.object-tree {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

.object-tree__title {
  border-bottom: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-muted);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  margin: 0;
  padding: 0.55rem 0.75rem;
  text-transform: uppercase;
}

.tree-root,
.tree-children {
  list-style: none;
  margin: 0;
  padding: 0;
}

.tree-root {
  overflow-y: auto;
  padding: 0.25rem 0.2rem;
}

.tree-row {
  align-items: center;
  display: flex;
  gap: 2px;
  min-height: 1.5rem;
}

.tree-disclosure {
  align-items: center;
  background: transparent;
  border: none;
  color: var(--theme-text-muted);
  cursor: pointer;
  display: inline-flex;
  flex: none;
  height: 0.9rem;
  justify-content: center;
  padding: 0;
  width: 0.9rem;
}

.tree-disclosure--leaf {
  display: inline-block;
}

.tree-label {
  align-items: baseline;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-primary);
  cursor: pointer;
  display: inline-flex;
  flex: 1;
  font: inherit;
  font-size: 0.8rem;
  gap: 0.35rem;
  min-width: 0;
  padding: 0.15rem 0.3rem;
  text-align: left;
}

.tree-label:hover {
  background: var(--theme-surface-hover);
}

/* Selection is a row band (with a leading accent bar), so "this row IS
 * selected" can never be confused with a tinted disclosure that merely
 * CONTAINS the selection on an ancestor row. */
.tree-row.is-selected {
  background: var(--theme-accent-soft);
  border-radius: var(--radius-sm);
  box-shadow: inset 2px 0 0 var(--theme-accent);
}

.tree-row.is-selected .tree-label {
  color: var(--theme-accent-ink);
}

.tree-row.in-path .tree-disclosure {
  color: var(--theme-accent);
}

.tree-label.is-static {
  cursor: default;
}

.tree-label__text {
  flex: none;
  font-weight: 500;
}

.tree-row--member .tree-label__text,
.tree-row--glazing .tree-label__text,
.tree-row--handle .tree-label__text,
.tree-row--panel .tree-label__text {
  color: var(--theme-text-secondary);
  font-weight: 400;
}

.tree-label__detail {
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 0.66rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tree-severity {
  border-radius: 50%;
  flex: none;
  height: 6px;
  margin-left: auto;
  width: 6px;
}

.tree-severity--error {
  background: var(--theme-danger);
}

.tree-severity--warning {
  background: var(--theme-warning);
}

.assembly-canvas {
  display: grid;
  grid-area: canvas;
  grid-template-rows: minmax(0, 1fr);
  min-height: 0;
  padding: 0;
}

.canvas-viewport {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: block;
  height: 100%;
  min-height: 30rem;
  overflow: hidden;
  position: relative;
  touch-action: none;
}

.canvas-viewport:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: -2px;
}

.canvas-viewport .canvas-sheet {
  background-image:
    linear-gradient(to right, rgb(209 216 216 / 0.3) 1px, transparent 1px),
    linear-gradient(to bottom, rgb(209 216 216 / 0.3) 1px, transparent 1px);
  background-size: 24px 24px;
  cursor: grab;
  display: block;
  height: 100%;
  width: 100%;
}

.canvas-viewport.is-panning .canvas-sheet {
  cursor: grabbing;
}

/* Floating zoom cluster — bottom-left island chrome */
.viewport-island {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  bottom: 0.75rem;
  display: flex;
  left: 0.75rem;
  padding: 2px;
  position: absolute;
  z-index: 2;
}

.viewport-button {
  align-items: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  display: inline-flex;
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 0.72rem;
  height: 1.6rem;
  justify-content: center;
  min-width: 1.6rem;
  padding: 0 0.35rem;
}

.viewport-button:hover {
  background: var(--theme-surface-hover);
  color: var(--theme-text-primary);
}

.viewport-button--percent {
  min-width: 3rem;
}

.viewport-menu {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  bottom: calc(100% + 6px);
  box-shadow: var(--shadow-pop);
  display: flex;
  flex-direction: column;
  left: 0;
  min-width: 10.5rem;
  padding: 3px;
  position: absolute;
}

.viewport-menu__item {
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-primary);
  cursor: pointer;
  font: inherit;
  padding: 0.4rem 0.6rem;
  text-align: left;
}

.viewport-menu__item:hover:not(:disabled) {
  background: var(--theme-accent-soft);
}

.viewport-menu__item:disabled {
  color: var(--theme-text-muted);
  cursor: default;
}

.viewport-status {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  bottom: 0.75rem;
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 0.72rem;
  padding: 0.3rem 0.55rem;
  position: absolute;
  right: 0.75rem;
  z-index: 2;
}

.product-front-svg {
  display: block;
  width: 100%;
}

.front-module {
  cursor: pointer;
}

.member {
  vector-effect: non-scaling-stroke;
}

.front-module .member-frame {
  stroke-width: 4;
}

.front-module.is-selected .member-frame {
  stroke: var(--theme-accent);
  stroke-width: 6;
}

.front-module.has-error .member-frame {
  stroke: var(--theme-danger);
  stroke-width: 6;
}

.front-module.has-warning .member-frame {
  stroke: var(--theme-warning);
  stroke-width: 6;
}

.module-opening {
  fill: none;
}

/* A contour module's inset path IS the lite — the transparent base class
 * left Trapecio/Arco elevations as a bare member slab (review M2). */
.module-opening--lite {
  fill: var(--theme-glass-pane);
}

.member-sash {
  stroke-width: 2;
}

.member-mullion,
.member-coupler,
.member-threshold {
  stroke-width: 2.5;
}

.member-bead {
  fill: none;
  stroke: var(--member-pvc-edge);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}

.module-glass {
  /* Opaque pane — a translucent tint showed the dark member slab beneath,
   * so anthracite/foil lites rendered as solid slabs (rendering review M1). */
  fill: var(--theme-glass-pane);
  stroke: var(--theme-border-subtle);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}

.glass-sheen {
  stroke: var(--member-pvc-highlight);
  stroke-width: 7;
  opacity: 0.75;
}

.bay-panel {
  fill: var(--member-panel-fill);
  stroke: var(--member-panel-edge);
  stroke-width: 1.6;
  vector-effect: non-scaling-stroke;
}

.handle-lever line {
  stroke: var(--theme-accent-ink);
  vector-effect: non-scaling-stroke;
}

/* Declared handle datum that lands off the leaf: the flag ring warns —
 * the lever still draws at its clamped display position. */
.handle-lever .handle-datum-flag {
  fill: none;
  stroke: var(--theme-danger);
  stroke-dasharray: 3 2;
  stroke-width: 1.6;
  vector-effect: non-scaling-stroke;
}

.handle-lever.is-datum-invalid line {
  stroke: var(--theme-danger);
}

/* Material-family interior detail: the soft chamber rebate of a PVC profile
 * and the thermal-break strip inside an aluminium extrusion. Strokes come
 * from each surface's own highlight/edge so they follow the member palette. */
.member-inner {
  fill: none;
  stroke-width: 1.1;
  opacity: 0.55;
  vector-effect: non-scaling-stroke;
}

.member-thermal-strip {
  opacity: 0.5;
}

/* Insulated glazing: inner ring reads as the second lite + spacer. */
.module-glass-ig {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  opacity: 0.65;
  vector-effect: non-scaling-stroke;
}

.door-hinge {
  fill: var(--theme-border-subtle);
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}

.module-bay {
  pointer-events: none;
}

/* Leaf-bay selection: pointer events turn on only while a select handler is
   wired (armed divide tool keeps the module's click contract intact). */
.module-bay.bay-pickable {
  cursor: pointer;
  pointer-events: auto;
}

.bay-select-ring {
  fill: none;
  pointer-events: none;
  stroke: var(--theme-accent);
  stroke-dasharray: 42 20;
  stroke-width: 10;
  vector-effect: non-scaling-stroke;
}

.dim-run {
  pointer-events: none;
}

.dim-extension {
  stroke: var(--theme-border-subtle);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.dim-line {
  stroke: var(--theme-text-muted);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.dim-tick {
  stroke: var(--theme-text-secondary);
  stroke-width: 2.6;
  vector-effect: non-scaling-stroke;
}

.opening-glyph polyline,
.opening-glyph line,
.opening-glyph path {
  stroke: var(--theme-text-secondary);
  stroke-width: 2.4;
  vector-effect: non-scaling-stroke;
}

.opening-glyph circle {
  fill: var(--theme-text-secondary);
}

.canvas-dim {
  fill: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-variant-numeric: tabular-nums;
}

.canvas-dim-wrap {
  cursor: pointer;
}

/* Padded hit pill — invisible at rest, surfaces on hover/focus so editable
 * dims read as controls, not decoration. */
.canvas-dim-hit {
  fill: var(--theme-surface-panel);
  opacity: 0;
  stroke: var(--theme-border-subtle);
  stroke-width: 1.5;
  transition: opacity 0.12s ease;
  vector-effect: non-scaling-stroke;
}

.canvas-dim-wrap:hover .canvas-dim-hit,
.canvas-dim-wrap:focus-visible .canvas-dim-hit,
.canvas-dim-wrap.is-active .canvas-dim-hit {
  opacity: 0.92;
}

.canvas-dim-wrap:hover .canvas-dim,
.canvas-dim:hover {
  fill: var(--theme-accent);
}

.canvas-dim.is-active {
  fill: var(--theme-accent-ink);
  font-weight: 500;
}

.canvas-dim-input {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-accent);
  color: var(--theme-text-primary);
  font-variant-numeric: tabular-nums;
  font-size: 0.9rem;
  padding: 0.15rem 0.3rem;
  text-align: center;
  width: 100%;
}

.add-handle {
  cursor: pointer;
}

.add-handle circle {
  fill: var(--theme-surface-panel);
  stroke: var(--theme-border-subtle);
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}

.add-handle path {
  stroke: var(--theme-accent);
  stroke-width: 5;
  vector-effect: non-scaling-stroke;
}

.add-handle:hover circle,
.add-handle:focus circle {
  stroke: var(--theme-accent);
}

/* Detail-level segmented control — overview/design/technical over the
   same selection. Tokens only; matches the tool-strip language. */
.detail-levels {
  display: flex;
  gap: var(--space-1);
  padding: var(--space-1);
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md);
  background: var(--theme-surface);
}

.detail-levels__btn {
  flex: 1;
  padding: var(--space-1) var(--space-2);
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--theme-text-muted);
  font: inherit;
  font-size: var(--text-sm);
  cursor: pointer;
}

.detail-levels__btn:hover {
  color: var(--theme-text);
}

.detail-levels__btn.is-active {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
  font-weight: 600;
}

.inspector-summary {
  padding: var(--space-3);
}

.inspector-summary__title {
  font-size: var(--text-sm);
  margin: 0 0 var(--space-2);
}

.inspector-summary__list {
  display: grid;
  gap: var(--space-2);
  margin: 0;
}

.inspector-summary__row {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
}

.inspector-summary__row dt {
  color: var(--theme-text-muted);
  font-size: var(--text-sm);
}

.inspector-summary__row dd {
  font-size: var(--text-sm);
  margin: 0;
  text-align: right;
}

.tech-panel {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.tech-table {
  border-collapse: collapse;
  font-size: var(--text-xs);
  width: 100%;
}

.tech-table th {
  color: var(--theme-text-muted);
  font-weight: 500;
  text-align: left;
}

.tech-table th,
.tech-table td {
  border-bottom: 1px solid var(--theme-border-subtle);
  padding: var(--space-1) var(--space-2) var(--space-1) 0;
}

.assembly-side {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  grid-area: side;
  min-height: 0;
  min-width: 0;
  overflow-y: auto;
}

.assembly-inspector {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  padding: 0.6rem 0.75rem;
}

.assembly-inspector__header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.assembly-inspector__header h4 {
  font-size: 0.95rem;
  margin: 0;
}

.assembly-hint {
  color: var(--theme-text-muted);
  font-size: 0.85rem;
  margin: 0;
}

.inspector-section {
  border-top: 1px solid var(--theme-border-subtle);
  display: contents;
}

.inspector-section > summary {
  color: var(--theme-text-muted);
  cursor: pointer;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  list-style: none;
  margin-top: 0.4rem;
  padding: 0.3rem 0;
  text-transform: uppercase;
  user-select: none;
}

.inspector-section > summary::before {
  content: "▾";
  display: inline-block;
  margin-right: 0.35rem;
  transition: transform 0.12s ease;
}

.inspector-section:not([open]) > summary::before {
  transform: rotate(-90deg);
}

.inspector-section > summary::-webkit-details-marker {
  display: none;
}

.inspector-section:not([open]) > summary {
  margin-bottom: 0;
}

.inspector-section[open] > *:not(summary) {
  animation: inspector-reveal 0.12s ease;
}

@keyframes inspector-reveal {
  from {
    opacity: 0.4;
  }
  to {
    opacity: 1;
  }
}

.opening-grid {
  display: grid;
  gap: 0.3rem;
  grid-template-columns: repeat(4, 1fr);
}

.opening-choice {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  cursor: pointer;
  padding: 0.15rem;
}

.opening-choice.is-active {
  border-color: var(--theme-accent);
  outline: 1px solid var(--theme-accent);
}

.opening-choice svg {
  display: block;
  width: 100%;
}

.opening-choice__frame {
  fill: var(--theme-glass-tint);
  stroke: var(--theme-text-secondary);
  stroke-width: 4;
}

.opening-choice .opening-glyph polyline,
.opening-choice .opening-glyph line,
.opening-choice .opening-glyph path {
  stroke: var(--theme-text-primary);
  stroke-width: 3;
}

.inspector-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.ghost-button {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  cursor: pointer;
  font-size: 0.85rem;
  padding: 0.3rem 0.55rem;
}

.ghost-button:hover:not(:disabled) {
  border-color: var(--theme-accent);
}

.ghost-button:disabled {
  border-style: dashed;
  color: var(--theme-text-muted);
  cursor: not-allowed;
  opacity: 0.5;
}

.ghost-button.is-danger:hover:not(:disabled) {
  border-color: var(--theme-danger);
  color: var(--theme-danger);
}

.assembly-issues {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.issue-chip {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-left-width: 3px;
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-size: 0.8rem;
  padding: 0.35rem 0.5rem;
  text-align: left;
  width: 100%;
}

.issue-chip--error {
  border-left-color: var(--theme-danger);
}

.issue-chip--warning {
  border-left-color: var(--theme-warning);
}

.plan-angle {
  cursor: pointer;
  fill: var(--theme-text-primary);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-variant-numeric: tabular-nums;
}

.plan-angle:hover {
  fill: var(--theme-accent);
}

.plan-coupling {
  cursor: pointer;
}

.plan-coupling.is-selected {
  stroke: var(--theme-accent);
}

.plan-coupling.has-issue {
  stroke: var(--theme-danger);
}

.plan-issue-flag {
  fill: var(--theme-danger);
  font-weight: 700;
}

/* --- Direct manipulation: divider grips, seam grips, divide preview --- */

.divider-grip {
  /* Faint resting fill — the divider reads as a drag zone, not a dead strip;
   * full accent arrives on hover/active. */
  fill: var(--theme-text-muted);
  fill-opacity: 0.07;
  outline: none;
  pointer-events: all;
  touch-action: none;
}

.divider-grip.is-vertical {
  cursor: ew-resize;
}

.divider-grip.is-horizontal {
  cursor: ns-resize;
}

.divider-grip:hover,
.divider-grip:active {
  fill: var(--theme-accent);
  fill-opacity: 0.18;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.seam-grip {
  cursor: ew-resize;
  fill: var(--theme-text-muted);
  fill-opacity: 0.06;
  pointer-events: all;
  touch-action: none;
}

.seam-grip:hover {
  fill: var(--theme-accent);
  fill-opacity: 0.14;
}

.seam-grip-dot,
.divider-grip-dots circle {
  fill: var(--theme-text-muted);
  opacity: 0.55;
}

.seam-grip:hover ~ .seam-grip-dot,
.divider-grip:hover ~ .divider-grip-dots circle,
.divider-grip.is-selected ~ .divider-grip-dots circle {
  fill: var(--theme-accent);
  opacity: 1;
}

.divide-preview-line {
  pointer-events: none;
  stroke: var(--theme-accent);
  stroke-dasharray: 14 10;
  stroke-width: 2.5;
  vector-effect: non-scaling-stroke;
}

.front-module.is-divide-target {
  cursor: crosshair;
}

.seam-preview {
  pointer-events: none;
}

.seam-preview-line {
  stroke: var(--theme-accent);
  stroke-dasharray: 16 12;
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}

.seam-preview-label {
  fill: var(--theme-accent-ink);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 30px;
  font-variant-numeric: tabular-nums;
}

.assistant-panel__prompt {
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  border: 1px solid var(--theme-border-strong);
  border-radius: var(--radius-sm);
  background: var(--theme-surface);
  color: var(--theme-text-primary);
  font: inherit;
  padding: 6px 8px;
  margin-bottom: 8px;
}

.assistant-panel__preview {
  border-top: 1px solid var(--theme-border-subtle);
  margin-top: 8px;
  padding-top: 8px;
}

.assistant-panel__notes {
  color: var(--theme-text-secondary);
  font-size: 12px;
  margin: 0 0 6px;
}

.assistant-panel__ops,
.assistant-panel__rejected {
  margin: 0 0 8px;
  padding-left: 16px;
  font-size: 12px;
}

.assistant-panel__rejected {
  color: var(--theme-mark);
}

.assistant-panel__meta {
  color: var(--theme-text-muted);
  font-size: 11px;
  margin: 6px 0 0;
}

.alternatives-panel__result {
  border-top: 1px solid var(--theme-border-subtle);
  margin-top: 8px;
  padding-top: 8px;
}

.alternatives-panel__cards {
  display: grid;
  gap: 8px;
  margin-bottom: 8px;
}

.alternative-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  padding: 8px;
  background: var(--theme-surface);
}

.alternative-card__thumb {
  display: block;
  max-height: 140px;
}

.alternative-card__thumb svg,
.alternative-card__thumb .alternative-card__render {
  display: block;
  width: 100%;
  height: auto;
  min-height: 96px;
  border-radius: var(--radius-sm);
  background: var(--model3d-backdrop, var(--theme-bg-canvas));
}

.alternative-card__label {
  font-weight: 600;
  font-size: 12px;
  margin: 6px 0 2px;
}

.alternative-card__rationale {
  color: var(--theme-text-secondary);
  font-size: 11px;
  margin: 0 0 4px;
}

.alternative-card__metrics {
  color: var(--theme-text-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  margin: 0;
}

.alternative-card__warnings {
  color: var(--theme-mark);
  font-size: 11px;
  margin: 4px 0 0;
}

.alternative-card__use {
  margin-top: 6px;
}

.context-menu {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-pop);
  display: flex;
  flex-direction: column;
  min-width: 200px;
  padding: 4px;
  position: fixed;
  z-index: 70;
}

.context-menu__item {
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  padding: 7px 10px;
  text-align: left;
}

.context-menu__item:hover {
  background: var(--theme-surface-raised);
  color: var(--theme-text-primary);
}

.context-menu__item--assistant {
  border-top: 1px solid var(--theme-border-subtle);
  border-radius: 0 0 4px 4px;
  color: var(--theme-accent);
  margin-top: 4px;
}

.context-menu__item {
  align-items: center;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.context-menu__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-menu__hint {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-xs, 3px);
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 10px;
  padding: 1px 5px;
  white-space: nowrap;
}

/* §04: mullion/transom + coupling selection affordances, technical dims,
   provenance chips and power-user recents. */

.member-mullion.is-selected,
.member-coupler.is-selected {
  stroke: var(--theme-accent);
  stroke-width: 4;
}

.divider-grip.is-selected {
  fill: var(--theme-accent);
  fill-opacity: 0.22;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.joint-hit {
  cursor: pointer;
  fill: transparent;
  pointer-events: all;
}

.joint-hit:hover {
  fill: var(--theme-accent);
  fill-opacity: 0.14;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.split-dim,
.member-dim {
  fill: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 22px;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  user-select: none;
}

.prov-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  list-style: none;
  margin: 0 0 10px;
  padding: 0;
}

.prov-chip {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 999px;
  color: var(--theme-text-secondary);
  font-size: 10.5px;
  padding: 1px 8px 1px 3px;
  white-space: nowrap;
}

.prov-chip__state {
  border-radius: 999px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  margin-right: 4px;
  padding: 1px 6px;
  text-transform: uppercase;
}

.prov-chip--verified .prov-chip__state {
  background: color-mix(in srgb, var(--theme-success) 16%, transparent);
  color: var(--theme-success);
}

.prov-chip--declared .prov-chip__state {
  background: color-mix(in srgb, var(--theme-accent) 14%, transparent);
  color: var(--theme-accent-ink);
}

.prov-chip--unknown .prov-chip__state {
  background: var(--theme-surface-raised);
  color: var(--theme-text-muted);
}

.prov-chip--blocked .prov-chip__state {
  background: color-mix(in srgb, var(--theme-danger) 14%, transparent);
  color: var(--theme-danger);
}

.division-children {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
}

.division-children li + li {
  margin-top: 2px;
}

.recents {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.recents__label {
  color: var(--theme-text-muted);
  font-size: 11px;
}

.recents__chip {
  background: var(--theme-surface-raised);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 999px;
  color: var(--theme-text-secondary);
  cursor: pointer;
  font-family: "IBM Plex Mono", "JetBrains Mono", "SF Mono", monospace;
  font-size: 10.5px;
  max-width: 140px;
  overflow: hidden;
  padding: 2px 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.recents__chip:hover {
  border-color: var(--theme-accent);
  color: var(--theme-text-primary);
}

.recents__chip--favorite {
  border-color: color-mix(in srgb, var(--theme-accent) 40%, transparent);
  color: var(--theme-accent-strong, var(--theme-accent));
}

.assembly-field__row {
  align-items: center;
  display: flex;
  gap: 6px;
}

.assembly-field__row select {
  flex: 1;
  min-width: 0;
}

.star-toggle {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 6px;
  color: var(--theme-text-muted);
  cursor: pointer;
  flex: 0 0 auto;
  font-size: 14px;
  line-height: 1;
  padding: 5px 7px;
}

.star-toggle:hover:not(:disabled) {
  border-color: var(--theme-accent);
  color: var(--theme-accent);
}

.star-toggle.is-active {
  border-color: var(--theme-accent);
  color: var(--theme-accent);
}

.star-toggle:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

.issue-fix {
  background: transparent;
  border: none;
  color: var(--theme-accent);
  cursor: pointer;
  font-size: 11px;
  margin-top: 2px;
  padding: 0 4px;
  text-align: left;
}

.issue-fix:hover {
  text-decoration: underline;
}

/* §05-G technical section view — horizontal node cut through a bay. */
.section-view {
  display: block;
  height: auto;
  margin-top: 0.5rem;
  width: 100%;
}

.section-member {
  fill: var(--member-pvc-fill);
  stroke: var(--member-pvc-edge);
  stroke-width: 0.6;
}

.section-member--aluminium {
  fill: var(--member-aluminium-fill);
  stroke: var(--member-aluminium-edge);
}

.section-member--approx {
  fill: none;
  stroke-dasharray: 3 2;
}

.section-glass {
  fill: var(--model3d-glass);
  opacity: 0.75;
}

.section-gasket {
  fill: var(--model3d-gasket);
}

.section-dim {
  stroke: var(--theme-text-muted);
  stroke-width: 0.5;
}

.section-dim__arrow {
  fill: var(--theme-text-muted);
}

.section-dim__text {
  fill: var(--theme-text-muted);
  font-size: 9px;
}

.section-label {
  fill: var(--theme-text-muted);
  font-size: 7px;
  letter-spacing: 0.12em;
}

.section-approx {
  fill: var(--theme-warning);
  font-size: 7px;
}

.section-break {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
}

/* Frameless (glass-only) modules: no member slab — the pane runs edge to
 * edge, supports/fittings mark their declared edges (review M4). */
.module-frameless .module-glass {
  stroke: var(--theme-border-strong);
}

.frameless-exposed {
  fill: var(--theme-bg-canvas);
  stroke: none;
  opacity: 0.35;
}

.frameless-channel {
  fill: var(--model3d-steel);
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}

.frameless-clamp,
.frameless-fitting {
  fill: var(--model3d-steel);
  stroke: var(--theme-text-primary);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}

.frameless-fitting--patch_fitting,
.frameless-fitting--clamp {
  fill: var(--member-aluminium-edge);
}

.frameless-fitting--hinge,
.frameless-fitting--lock {
  fill: var(--theme-text-secondary);
}

.frameless-seal {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-dasharray: 10 6;
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}

/* Corredera notation: head/sill rails behind the leaves and a slide
 * direction arrow per moving leaf — the .sliding-arrow path previously
 * had no stroke and rendered invisible (review M3). */
.sliding-track {
  stroke: var(--theme-text-muted);
  stroke-width: 1.6;
  stroke-dasharray: 7 5;
  vector-effect: non-scaling-stroke;
}

.sliding-arrow {
  fill: none;
  stroke: var(--theme-text-primary);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

/* §15 profile section preview — true-scale cross-section with provenance. */
.section-preview {
  margin: 0;
  display: grid;
  gap: 0.35rem;
}

.section-preview svg {
  display: block;
  width: 100%;
  max-width: 180px;
  height: auto;
  border: 1px solid var(--line, #d8d8d8);
  border-radius: var(--radius-sm);
  background: var(--surface-raised, #fff);
}

.section-preview__shape {
  stroke-width: 0.6;
  vector-effect: non-scaling-stroke;
}

.section-preview__shape--approx {
  fill: none;
  stroke-dasharray: 3 2;
}

.section-preview__axis {
  stroke: var(--line-strong, #9a9a9a);
  stroke-width: 0.4;
  stroke-dasharray: 4 2;
  vector-effect: non-scaling-stroke;
}

.section-preview__axis-label,
.section-preview__dims {
  fill: var(--ink-3, #6b6b6b);
  font-family: var(--font-mono, monospace);
}

.section-preview figcaption {
  font-size: 0.72rem;
  color: var(--ink-3, #6b6b6b);
}

.section-preview[data-provenance="APPROXIMATE"] figcaption::before {
  content: "◌ ";
}

.section-preview[data-provenance="POLYGON"] figcaption::before,
.section-preview[data-provenance="DXF_REFERENCE"] figcaption::before {
  content: "■ ";
}

.section-preview-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.pricing-page {
  color: var(--theme-text-primary);
  max-width: 90rem;
  margin: auto;
}
.pricing-page h1,
.pricing-page h2 {
  margin-bottom: 0.75rem;
}
.pricing-page header p {
  color: var(--theme-text-secondary);
}
.pricing-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 1rem 0;
}
.pricing-tabs [aria-pressed="true"] {
  outline: 2px solid var(--theme-accent);
}
.pricing-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 1fr);
  gap: 1.5rem;
}
.pricing-page article,
.pricing-page form {
  border: 1px solid var(--theme-border-subtle);
  padding: 1rem;
  background: var(--theme-surface-panel);
  border-radius: 0.5rem;
  margin: 0.75rem 0;
}
.pricing-page form {
  display: grid;
  gap: 0.75rem;
  align-content: start;
}

/* Column-mapping + separator fields pair up — a single tall column read as
 * a record viewer, not an import workspace. */
.pricing-page .form-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (max-width: 700px) {
  .pricing-page .form-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* The commercial operation form packs its short config fields two-per-row
 * instead of a single tall column — the page reads as a workspace, not a
 * record viewer. Long fields (reason, checkbox, submit) span both columns. */
.commercial-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.commercial-form > label:has(> input[name="reason"]),
.commercial-form > label:has(> input[name="confirmed"]),
.commercial-form > label:has(> select[name="project_id"]),
.commercial-form > button,
.commercial-form > details {
  grid-column: 1 / -1;
}

@media (max-width: 800px) {
  .commercial-form {
    grid-template-columns: minmax(0, 1fr);
  }
}
.pricing-page label {
  display: grid;
  gap: 0.3rem;
}
.pricing-page input,
.pricing-page select {
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.6rem;
  border-radius: 0.25rem;
  min-width: 0;
}
.pricing-page input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
}
.pricing-page button {
  padding: 0.55rem 0.8rem;
  cursor: pointer;
}
.pricing-page button:disabled {
  cursor: wait;
  opacity: 0.6;
}
.pricing-page [role="alert"] {
  color: var(--theme-danger);
}
.pricing-page dl div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  padding: 0.3rem 0;
}
.pricing-page dd {
  margin: 0;
  overflow-wrap: break-word;
}
.pricing-page table {
  width: 100%;
  border-collapse: collapse;
}
.pricing-page td,
.pricing-page th {
  padding: 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  text-align: left;
}
.pricing-import {
  overflow-x: auto;
}
@media (max-width: 760px) {
  .pricing-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .pricing-page {
    padding: 0.75rem;
  }
}

/* §03-D — pricing decision workspace */
.operation-decision {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  margin: var(--space-3) 0;
  padding: var(--space-3);
}

.operation-decision__head {
  align-items: center;
  display: flex;
  gap: 0.75rem;
  margin-bottom: var(--space-2);
}

.operation-decision__meta {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.operation-totals {
  display: grid;
  gap: 0.5rem;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  margin-bottom: var(--space-2);
}

.operation-total {
  background: var(--theme-surface-page, var(--theme-surface-panel));
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  padding: 0.5rem 0.625rem;
}

.operation-total dt {
  color: var(--theme-text-secondary);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.operation-total dd {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  margin: 0.125rem 0 0;
}

.operation-total--gross dd {
  color: var(--theme-accent-ink, var(--theme-accent));
  font-size: var(--text-title);
}

.operation-total dd[data-negative] {
  color: var(--theme-danger);
}

.pricing-extras {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  margin: var(--space-2) 0;
  padding: var(--space-2) var(--space-3);
}

.pricing-extras legend {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 0 0.25rem;
  text-transform: uppercase;
}

.pricing-extras__row {
  align-items: center;
  display: grid;
  gap: 0.5rem;
  grid-template-columns: minmax(7rem, 10rem) minmax(0, 1fr) minmax(6rem, 9rem) auto;
  margin-top: 0.375rem;
}

@media (max-width: 760px) {
  .pricing-extras__row {
    grid-template-columns: 1fr 1fr;
  }
}

.operation-lines__wrap {
  margin-bottom: var(--space-2);
  overflow-x: auto;
}

.operation-lines {
  border-collapse: collapse;
  font-size: 0.8125rem;
  min-width: 48rem;
  width: 100%;
}

.operation-lines caption {
  color: var(--theme-text-secondary);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 0.375rem 0;
  text-align: left;
  text-transform: uppercase;
}

.operation-lines th,
.operation-lines td {
  border-bottom: 1px solid var(--theme-border-subtle);
  font-variant-numeric: tabular-nums;
  padding: 0.375rem 0.5rem;
  text-align: right;
}

.operation-lines th:nth-child(-n + 3),
.operation-lines td:nth-child(-n + 3) {
  text-align: left;
}

.operation-decision__audit {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.operation-decision__actions {
  display: flex;
  gap: 0.5rem;
  position: sticky;
  bottom: 0;
  margin: var(--space-3) calc(-1 * var(--space-3)) calc(-1 * var(--space-3));
  padding: var(--space-2) var(--space-3);
  background: var(--theme-surface-panel);
  border-top: 1px solid var(--theme-border-subtle);
  border-radius: 0 0 0.5rem 0.5rem;
}

.operation-history__item .operation-history__meta {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.status-chip[data-status="pending"] {
  background: var(--theme-warning-soft, rgba(217, 119, 6, 0.12));
  color: var(--theme-warning);
}

.status-chip[data-status="applied"] {
  background: var(--theme-accent-soft, rgba(37, 99, 235, 0.12));
  color: var(--theme-accent);
}

.status-chip[data-status="rejected"] {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

.status-chip[data-status="withdrawn"] {
  background: var(--theme-surface-alt, rgba(100, 116, 139, 0.12));
  color: var(--theme-text-secondary);
}

.operation-decision__stale {
  color: var(--theme-warning);
  font-size: 0.75rem;
  margin: 0.25rem 0 0;
}

.operation-warning {
  color: var(--theme-warning);
  font-size: 0.7rem;
  margin-left: 0.5rem;
}

.operation-lines__list {
  color: var(--theme-text-secondary);
  font-size: 0.72rem;
  white-space: nowrap;
}

.operation-lines__detail > td {
  border-top: none;
  padding: 0 0.5rem 0.5rem;
}

.operation-lines__detail details summary {
  color: var(--theme-accent);
  cursor: pointer;
  font-size: 0.75rem;
}

.cost-composition {
  margin-top: 0.5rem;
}

.cost-composition__table {
  font-size: 0.75rem;
}

.cost-composition__table td {
  padding: 0.15rem 0.75rem 0.15rem 0;
}

.cost-composition__table td:last-child {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.cost-composition__math {
  color: var(--theme-text-secondary);
  font-size: 0.72rem;
  margin: 0.25rem 0 0;
}

.operation-authorities {
  font-size: 0.72rem;
  color: var(--theme-text-secondary);
  margin-top: 0.25rem;
}

.operation-authorities summary {
  cursor: pointer;
}

.operation-authorities ul {
  margin: 0.25rem 0 0;
  padding-left: 1.25rem;
}

.operation-history__filters {
  align-items: flex-end;
  display: flex;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.operation-history__filters select {
  margin-left: 0.5rem;
}

.field-hint {
  color: var(--theme-text-secondary);
  font-size: 0.72rem;
  margin: 0.15rem 0 0;
}

.coverage-summary {
  color: var(--theme-text-secondary);
  font-size: 0.8125rem;
  margin: 0;
}

.link-button {
  background: none;
  border: none;
  color: var(--theme-accent);
  cursor: pointer;
  font: inherit;
  padding: 0;
  text-decoration: underline;
}

.coverage-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  display: grid;
  gap: 0.25rem;
  padding: 0.75rem 1rem;
}

.coverage-card--missing {
  border-color: var(--theme-danger);
}

.coverage-card__meta,
.coverage-card > span {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.coverage-card .status-chip {
  justify-self: start;
}

.audit-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  display: grid;
  gap: 0.375rem;
  padding: 0.75rem 1rem;
}

.audit-card__header {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.audit-card__project {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
  margin-left: auto;
}

.audit-card__title {
  font-size: 0.875rem;
  margin: 0;
}

.audit-card__diffs {
  font-size: 0.75rem;
  margin: 0;
  padding-left: 1rem;
}

.audit-card__diffs code {
  color: var(--theme-text-secondary);
}

.audit-card__diffs span {
  color: var(--theme-text-secondary);
}

.audit-card__footer {
  color: var(--theme-text-secondary);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.75rem;
  gap: 0.75rem;
}

/* §8 compare band — CURRENT → PROPOSED with the delta in the same glance */
.operation-compare {
  display: flex;
  align-items: stretch;
  gap: var(--space-4);
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-accent);
  border-radius: var(--radius-md);
  background: var(--theme-surface-panel);
  margin: var(--space-3) 0;
}

.operation-compare__cell {
  display: grid;
  gap: var(--space-1);
  align-content: center;
}

.operation-compare__cell span {
  font-size: var(--text-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--theme-text-muted);
}

.operation-compare__cell strong {
  font-size: var(--text-title);
  font-variant-numeric: tabular-nums;
}

.operation-compare__cell small {
  font-size: var(--text-xs);
  font-weight: 500;
  color: var(--theme-text-muted);
}

.operation-compare__arrow {
  align-self: center;
  font-size: var(--text-title);
  color: var(--theme-text-muted);
}

.operation-compare__delta {
  margin-left: auto;
  text-align: right;
}

.operation-compare__delta strong[data-negative] {
  color: var(--theme-accent-ink);
}

.operation-lines__delta [data-negative] {
  color: var(--theme-accent-ink);
}

/* A pricing row: a small live thumbnail next to the position index — the
 * estimator recognizes the vano without opening the editor. */
.operation-lines__vano {
  align-items: center;
  display: inline-flex;
  gap: 0.5rem;
}

.operation-lines__vano .position-thumb {
  flex: none;
  height: 2.5rem;
  width: auto;
}

/* Amounts are single-line data — a wrapped net or unit price reads as two
 * different numbers (phase-06 mandate). */
.operation-lines__money {
  white-space: nowrap;
}

.operation-lines__money small {
  white-space: nowrap;
}

.pricing-fix {
  font-weight: 600;
}

.catalog {
  color: var(--theme-text-primary);
  background: var(--theme-bg-canvas);
  font-size: 0.875rem;
}

.catalog h1,
.catalog h2,
.catalog h3,
.catalog p {
  margin: 0;
}

.catalog h1 {
  font-size: var(--text-display);
}
.catalog h2 {
  font-size: var(--text-title);
}
.catalog h3 {
  font-size: 0.95rem;
}

.catalog p,
.catalog small {
  color: var(--theme-text-secondary);
  line-height: 1.5;
}

.catalog-heading,
.catalog-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.catalog-heading > div,
.catalog-detail > header {
  display: grid;
  gap: 0.35rem;
}

.catalog-status {
  min-height: 1.75rem;
}

.catalog-layout {
  display: grid;
  grid-template-columns: minmax(13rem, 17rem) minmax(0, 1fr);
  gap: 1rem;
  align-items: start;
}

.catalog-master,
.catalog-detail {
  min-width: 0;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  background: var(--theme-surface-panel);
  padding: 0.875rem;
}

.catalog-master {
  display: grid;
  gap: 0.75rem;
}

.catalog-master ul {
  display: grid;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.catalog .catalog-system {
  display: grid;
  width: 100%;
  gap: 0.2rem;
  text-align: left;
  padding: 0.65rem;
}

.catalog-system span {
  color: var(--theme-text-secondary);
}

.catalog-detail {
  display: grid;
  gap: 1rem;
}

/* Long system names/records must wrap, not stretch the page — the detail
 * column hosts wide tables inside scroll containers, which can only shrink
 * if every level allows min-width:0. */
.catalog-detail > *,
.ws > * {
  min-width: 0;
}
.catalog-detail h2,
.ws-identity-head h2,
.ws-chip,
.ws-badge {
  overflow-wrap: anywhere;
}

.catalog-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--theme-border-subtle);
}

.catalog button,
.catalog input,
.catalog select {
  font: inherit;
  color: var(--theme-text-primary);
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.3rem;
  min-height: 2.25rem;
}

.catalog button {
  padding: 0.4rem 0.7rem;
  cursor: pointer;
}

.catalog button:hover:not(:disabled) {
  background: var(--theme-surface-hover);
}

.catalog button[aria-current="true"],
.catalog button[aria-pressed="true"] {
  border-color: var(--theme-accent);
  background: var(--theme-surface-card);
