.inventory-remnant-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: 0.5rem 0.9rem;
  align-items: end;
  padding: 0.75rem;
  border: 1px dashed var(--theme-border-subtle);
  border-radius: 0.4rem;
  margin-bottom: 0.75rem;
}
.inventory-remnant-form .purchasing-hint {
  grid-column: 1 / -1;
  margin: 0;
}
.inventory-movements {
  margin-top: 0.75rem;
  overflow-x: auto;
  max-width: 100%;
}
.inventory-movements summary {
  cursor: pointer;
  color: var(--theme-text-secondary);
  font-weight: 600;
}
.inventory-movements table {
  margin-top: 0.5rem;
  min-width: 34rem;
}
.inventory-adjust {
  margin-bottom: 0.9rem;
}
.inventory-adjust summary {
  cursor: pointer;
  color: var(--theme-text-secondary);
  font-weight: 600;
}
.inventory-adjust-items {
  list-style: none;
  margin: 0.5rem 0;
  padding: 0;
  display: grid;
  gap: 0.3rem;
}
.inventory-adjust-items li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  padding: 0.3rem 0;
  border-bottom: 1px solid var(--theme-border-subtle);
}

.purchasing-index {
  border: 1px solid var(--theme-border, #e0e0e0);
  border-radius: 0.75rem;
  padding: 1rem;
  margin: 0.5rem 0 1rem;
  background: var(--theme-surface, #fff);
  overflow-x: auto;
}
.purchasing-index h2 {
  margin: 0 0 0.5rem;
  font-size: 1rem;
}
.purchasing-index-filters {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
  margin-bottom: 0.75rem;
}
.purchasing-index-filters button {
  border: 1px solid var(--theme-border, #d5d5d5);
  background: var(--theme-surface, #fff);
  border-radius: 999px;
  padding: 0.2rem 0.7rem;
  font-size: 0.8rem;
}
.purchasing-index-filters button.is-active {
  background: var(--theme-primary, #1a4f8f);
  border-color: var(--theme-primary, #1a4f8f);
  color: var(--theme-on-primary, #fff);
}
.purchasing-index table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}
.purchasing-index th {
  text-align: left;
  font-weight: 600;
  color: var(--theme-text-muted, #666);
  padding: 0.35rem 0.5rem;
  border-bottom: 1px solid var(--theme-border, #e0e0e0);
  white-space: nowrap;
}
.purchasing-index td {
  padding: 0.45rem 0.5rem;
  border-bottom: 1px solid var(--theme-border, #eee);
  white-space: nowrap;
}
.purchasing-index-row {
  cursor: pointer;
}
.purchasing-index-row:hover {
  background: var(--theme-hover, #f4f7fb);
}
.purchasing-index-row:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: -2px;
}

.purchasing-badge--expired {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
  border-color: var(--theme-danger);
}
.inventory-label {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  padding: 0.6rem 0.9rem;
  border: 2px solid var(--theme-text, #1b1d21);
  border-radius: 0.35rem;
  background: var(--theme-surface, #fff);
  width: fit-content;
  margin: 0.5rem 0 0.75rem;
}
.inventory-label .qr svg {
  width: 26mm;
  height: 26mm;
  display: block;
}
.inventory-label .inventory-label-id {
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  color: var(--theme-text-secondary, #667085);
}
.inventory-label .inventory-label-name {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.2;
}
.inventory-label .inventory-label-dims {
  font-size: 1.35rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.inventory-label .inventory-label-rack {
  font-size: 0.85rem;
}
.inventory-label-actions {
  display: flex;
  gap: 0.4rem;
  margin-top: 0.4rem;
}
@media print {
  body * {
    visibility: hidden;
  }
  .inventory-label,
  .inventory-label * {
    visibility: visible;
  }
  /* The print/dismiss controls are screen-only chrome — never on the label. */
  .inventory-label .inventory-label-actions,
  .inventory-label .inventory-label-actions * {
    visibility: hidden;
  }
  .inventory-label {
    position: absolute;
    top: 0;
    left: 0;
    margin: 0;
  }
}

.purchasing-glance {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 0.5rem;
  margin: 0.5rem 0;
}
.purchasing-glance-cell {
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md, 8px);
  padding: 0.6rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  background: var(--theme-surface);
}
.purchasing-glance-cell strong {
  font-size: 1.15rem;
  font-weight: 600;
}
.purchasing-glance-cell span {
  font-size: 0.78rem;
  color: var(--theme-text-secondary);
}
.purchasing-glance-cell.is-short {
  border-color: var(--theme-danger, #b3261e);
}
.purchasing-glance-cell.is-short strong {
  color: var(--theme-danger, #b3261e);
}

.purchasing-directory ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}
.purchasing-directory-row {
  display: grid;
  grid-template-columns: minmax(140px, 1.2fr) minmax(160px, 1.4fr) minmax(140px, 1.2fr) minmax(
      180px,
      1.4fr
    );
  gap: 0.75rem;
  padding: 0.55rem 0.75rem;
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md, 8px);
  background: var(--theme-surface);
  align-items: center;
  font-size: 0.85rem;
}
.purchasing-directory-id {
  display: flex;
  flex-direction: column;
}
.purchasing-directory-tax {
  font-size: 0.75rem;
  color: var(--theme-text-secondary);
}
.purchasing-directory-contact {
  display: flex;
  flex-direction: column;
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
.purchasing-directory-cats {
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
.purchasing-directory-orders {
  display: flex;
  flex-direction: column;
  font-size: 0.8rem;
}
.purchasing-directory-open {
  color: var(--theme-accent);
  font-weight: 600;
}
.purchasing-directory-history {
  color: var(--theme-text-secondary);
}
@media (max-width: 900px) {
  .purchasing-directory-row {
    grid-template-columns: 1fr 1fr;
  }
}
.purchasing-order-damaged {
  color: var(--theme-danger, #b3261e);
  font-weight: 600;
}

.production-page {
  color: var(--theme-text-primary);
  max-width: 90rem;
  margin: auto;
}
.production-page h1,
.production-page h2,
.production-page h3 {
  margin-bottom: 0.75rem;
}
.production-page header p {
  color: var(--theme-text-secondary);
}
.production-page [role="alert"] {
  color: var(--theme-danger);
}
/* Action refusals (422 shortage/gate/role) surface where the operator is
   looking — a fixed toast — not a banner scrolled off the top of a long
   order detail. */
.production-action-error {
  position: fixed;
  left: 50%;
  bottom: calc(1rem + env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%);
  z-index: 60;
  max-width: min(34rem, calc(100vw - 2rem));
  margin: 0;
  padding: 0.65rem 1rem;
  border: 1px solid var(--theme-danger);
  border-radius: var(--radius-md, 8px);
  background: var(--theme-surface-panel);
  box-shadow: var(--shadow-lg, 0 8px 24px rgba(0, 0, 0, 0.18));
  font-weight: 600;
}
.production-layout {
  display: grid;
  grid-template-columns: minmax(16rem, 22rem) 1fr;
  gap: 1.25rem;
  align-items: start;
}
.production-orders,
.production-detail {
  /* Grid items default to min-width:auto — a single wide child (the
     scrollable filter row, a long mono code) would stretch the whole track
     and overflow the page on narrow screens. */
  min-width: 0;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  padding: 1rem;
  background: var(--theme-surface-panel);
}
.production-filters {
  display: flex;
  /* Nine+ chips ragged-wrap onto two lines; one scrollable row stays clean. */
  flex-wrap: nowrap;
  gap: var(--space-1);
  margin-bottom: var(--space-3);
  overflow-x: auto;
  padding-bottom: 0.25rem;
}

.production-filter {
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md);
  background: var(--theme-surface);
  color: var(--theme-text-muted);
  cursor: pointer;
  flex: none;
  font: inherit;
  font-size: var(--text-xs);
  padding: var(--space-1) var(--space-2);
  white-space: nowrap;
}

.production-filter:hover {
  color: var(--theme-text);
}

.production-filter.is-active {
  background: var(--theme-accent-soft);
  border-color: var(--theme-accent);
  color: var(--theme-accent-ink);
  font-weight: 600;
}

/* Clear-filters reads as a control, not a placeholder — same solid chrome as
 * the preset filters, de-emphasized by color only (review m12). */
.production-filter-clear {
  color: var(--theme-text);
}

.production-next {
  align-items: center;
  background: var(--theme-accent-soft);
  border: 1px solid var(--theme-accent);
  border-radius: var(--radius-md);
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  justify-content: space-between;
  margin-bottom: var(--space-3);
  padding: var(--space-2) var(--space-3);
}

.production-next-label {
  font-size: var(--text-sm);
}

/* §11 station controls: the next-step bar is the operator's primary touch
 * target — large hit area and type readable from the workstation. */
.production-next .production-step-actions button {
  min-height: 52px;
  min-width: 120px;
  padding: 0.6rem 1.1rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
}

.production-orders ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}
.production-order {
  /* Chips wrap onto their own row instead of squashing or overflowing the
     card when the order carries several states at once. */
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  width: 100%;
  text-align: left;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  background: var(--theme-bg-canvas);
  color: var(--theme-text-primary);
}
.production-order .production-order-progress {
  flex: 1 1 auto;
}
.production-order .production-order-next {
  flex-basis: 100%;
  order: 9;
}
.production-order.active {
  border-color: var(--theme-accent);
}
.production-order-code {
  font-family: var(--theme-font-mono);
  font-weight: 600;
}
.production-order-progress {
  font-size: 0.85rem;
  color: var(--theme-text-secondary);
}
.production-detail-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.production-detail-head .production-chip,
.production-order .production-chip {
  /* Chip text wraps inside the chip before it ever overflows it. */
  white-space: normal;
  overflow-wrap: anywhere;
}
.production-materials {
  display: flex;
  gap: 1.5rem;
  margin: 0.75rem 0;
  padding: 0.75rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
}
.production-materials div {
  display: grid;
  gap: 0.15rem;
}
.production-materials dt {
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
.production-materials dd {
  margin: 0;
  font-family: var(--theme-font-mono);
  font-size: 1.1rem;
}
.production-steps {
  list-style: none;
  margin: 1rem 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}
.production-step {
  align-items: center;
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.375rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.55rem 0.75rem;
}
.production-step.step-done {
  opacity: 0.75;
}
.production-step.step-blocked {
  border-color: var(--theme-warning, #e56a32);
}
.production-step-head {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}
.production-step-seq {
  font-family: var(--theme-font-mono);
  color: var(--theme-text-secondary);
}
.production-step-center {
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
.production-step-note {
  color: var(--theme-text-secondary);
  flex-basis: 100%;
  font-size: 0.9rem;
  margin: 0.2rem 0 0;
}
.production-step-actions {
  display: flex;
  gap: 0.5rem;
  margin-left: auto;
}
.production-step-actions button,
.production-order {
  cursor: pointer;
}
.production-step-actions button {
  padding: 0.4rem 0.7rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.25rem;
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
}
.production-step-actions button:disabled {
  cursor: wait;
  opacity: 0.6;
}
.production-step-hint {
  align-items: center;
  color: var(--theme-text-secondary);
  display: inline-flex;
  font-size: var(--text-s, 12px);
  font-style: italic;
  padding: 0.4rem 0.2rem;
}
.production-remake {
  padding: 0.35rem 0.7rem;
  border: 1px solid var(--theme-mark);
  border-radius: 0.25rem;
  background: transparent;
  color: var(--theme-mark);
  font-weight: 600;
  cursor: pointer;
}
.production-cnc {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.5rem;
}
.production-cnc button {
  padding: 0.35rem 0.7rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.25rem;
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
  font-family: var(--theme-font-mono, monospace);
  font-size: 0.8rem;
  cursor: pointer;
}
.production-cnc button:hover:not(:disabled) {
  border-color: var(--theme-accent, #0f817a);
}
.production-cnc button:disabled {
  cursor: wait;
  opacity: 0.6;
}
.production-cnc .production-cutpack {
  border-color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-soft);
  font-weight: 600;
}

.production-remake:hover:not(:disabled) {
  background: color-mix(in srgb, var(--theme-mark) 12%, transparent);
}
.production-remake:disabled {
  cursor: default;
  opacity: 0.55;
}
.production-note {
  display: grid;
  gap: 0.3rem;
  margin: 0.75rem 0;
}
.production-note input {
  background: var(--theme-bg-canvas);
  color: var(--theme-text-primary);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.6rem;
  border-radius: 0.25rem;
}
.production-events ol {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.35rem;
}
.production-events li {
  display: flex;
  gap: 0.75rem;
  font-size: 0.85rem;
  flex-wrap: wrap;
}
.production-events li > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.production-events time {
  color: var(--theme-text-secondary);
  font-family: var(--theme-font-mono);
}
.production-pick {
  color: var(--theme-text-secondary);
}
@media (max-width: 60rem) {
  .production-layout {
    grid-template-columns: 1fr;
  }
}

.production-optimize {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.25rem;
  padding: 0.9rem;
  margin-bottom: 1rem;
  background: var(--theme-surface-panel);
  /* Plan tables are wider than a phone — scroll inside the section, never
     stretch the page. */
  overflow-x: auto;
}
.production-optimize-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
}
.production-optimize-head h3 {
  margin: 0;
  font-size: 0.95rem;
}
.production-optimize-head time {
  color: var(--theme-text-secondary);
  font-family: var(--theme-font-mono);
  font-size: 0.75rem;
}
.production-optimize-controls {
  display: flex;
  gap: 0.5rem;
  margin: 0.6rem 0;
}
.production-optimize-controls input {
  background: var(--theme-bg-canvas);
  color: var(--theme-text-primary);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.5rem 0.6rem;
  border-radius: 0.25rem;
  font-family: var(--theme-font-mono);
  width: 10rem;
}
.production-optimize-controls button {
  padding: 0.5rem 0.9rem;
  cursor: pointer;
}
.production-optimize-controls button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.production-optimize-empty {
  color: var(--theme-text-secondary);
  font-size: 0.85rem;
  margin: 0.5rem 0 0;
}
.production-invalidated {
  margin: 0 0 var(--space-3);
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--theme-danger);
  border-radius: var(--radius-md);
  background: var(--theme-danger-soft, #fbe9e7);
  color: var(--theme-danger);
  font-weight: 600;
}
.production-invalidated code {
  margin-left: var(--space-2);
  font-weight: 400;
}
.production-blockers {
  list-style: none;
  margin: 0 0 var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-left: 3px solid var(--theme-warning, #b7791f);
  background: var(--theme-warning-soft, #fdf3e0);
  color: var(--theme-text);
  font-size: 0.85rem;
}
.production-blockers li + li {
  margin-top: var(--space-1);
}
.production-event-note {
  display: block;
  color: var(--theme-text-secondary);
  font-style: normal;
  font-size: 0.82rem;
  margin-top: 0.125rem;
}
.production-remake-provenance {
  margin: 0 0 var(--space-3);
  color: var(--theme-text-secondary);
  font-size: 0.85rem;
}
.production-remake-provenance strong {
  color: var(--theme-text-primary);
}
.production-plan {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
  margin-top: 0.6rem;
}
.production-plan th {
  text-align: left;
  color: var(--theme-text-secondary);
  font-weight: 500;
  padding: 0.3rem 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
}
.production-plan td {
  padding: 0.35rem 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  vertical-align: top;
}
.production-plan td:first-child {
  font-family: var(--theme-font-mono);
  color: var(--theme-text-secondary);
}
.production-optimize-purchases {
  font-size: 0.85rem;
  color: var(--theme-text-secondary);
  margin: 0.6rem 0 0;
}
.production-optimize-unnested {
  font-size: 0.85rem;
  color: var(--theme-warning, #b45309);
  margin: 0.6rem 0 0;
}

.production-dispatch {
  border: 1px solid var(--accent, #0f817a);
  background: var(--accent, #0f817a);
  color: var(--theme-surface-panel);
}

.production-dispatch.production-void {
  background: transparent;
  color: var(--theme-danger, #b3261e);
  border-color: var(--theme-danger, #b3261e);
}

.production-dispatch.is-voided {
  background: transparent;
  color: var(--theme-text-muted, #7d8794);
  border-color: var(--theme-border-subtle, #c8ced6);
  text-decoration: line-through;
}

.production-packing {
  margin-block: var(--space-4, 16px);
  /* Packing tables can exceed a phone's width — scroll inside the section. */
  overflow-x: auto;
}

.production-label-code {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.85em;
}

.production-labels {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 12px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.production-label {
  display: grid;
  gap: 6px;
  border: 1px solid var(--line-strong, #2e3338);
  padding: 12px;
  text-align: center;
}
.production-label-qr svg {
  width: 100%;
  max-width: 140px;
  height: auto;
  margin: 0 auto;
  display: block;
}
.production-label-pieces {
  font-weight: 600;
}
.production-label-parts {
  font-size: var(--text-s, 12px);
  color: var(--ink-muted, #6b7280);
}
@media print {
  /* The label sheet lives inside .app-body > .workspace — hiding any ancestor
     of .production-labels prints a blank page, so each level hides only the
     label path's siblings. */
  .app-shell > :not(.app-body),
  .app-body > :not(.workspace),
  .workspace > :not(.production-page),
  .production-page > :not(.production-layout),
  .production-layout > :not(.production-detail),
  .production-detail > :not(.production-packing),
  .production-packing > :not(.production-labels) {
    display: none !important;
  }
  .app-shell,
  .app-body,
  .workspace,
  .production-layout,
  .production-detail,
  .production-packing {
    display: block;
  }
  .production-page {
    max-width: none;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
  }
  .production-labels {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 6mm;
    list-style: none;
    margin: 0;
    padding: 0;
  }
  .production-label {
    break-inside: avoid;
    border: 0.4pt solid var(--theme-border);
    padding: 4mm;
  }
}
.production-delivery {
  margin-top: 12px;
}
.production-delivery-facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 8px;
  margin: 8px 0 0;
}
.production-delivery-facts dt {
  color: var(--ink-muted);
  font-size: var(--text-s, 12px);
}
.production-delivery-facts dd {
  margin: 0;
}
.production-delivery-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 10px;
  margin-top: 10px;
}
.production-delivery-form label {
  display: grid;
  gap: 4px;
  font-size: var(--text-s, 12px);
  color: var(--ink-muted);
}
.production-delivery-wide {
  grid-column: 1 / -1;
}
.production-delivery-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
}
.production-delivery-trips {
  display: grid;
  gap: 6px;
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
}
.production-delivery-trip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper-2, #faf9f7);
}
.production-delivery-trip-date {
  font-weight: 600;
}
.production-delivery-trip-units {
  color: var(--ink-muted);
  font-size: var(--text-s, 12px);
}
.production-delivery-pending {
  margin: 8px 0 0;
  font-size: var(--text-s, 12px);
  color: var(--ink-muted);
}
.production-delivery-units {
  grid-column: 1 / -1;
  margin: 10px 0 0;
  padding: 8px 10px;
  border: 1px dashed var(--line);
  border-radius: 8px;
}
.production-delivery-units legend {
  font-size: var(--text-s, 12px);
  color: var(--ink-muted);
  padding: 0 4px;
}
.production-delivery-unit-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.production-delivery-units-hint {
  margin: 6px 0 0;
  font-size: var(--text-xs, 11px);
  color: var(--ink-muted);
}

.signature-pad {
  position: relative;
  margin-top: 4px;
}
.signature-pad-canvas {
  display: block;
  color: var(--signature-ink);
  width: 100%;
  max-width: 480px;
  height: 160px;
  border: 1px solid var(--line, #d8dde2);
  border-radius: var(--radius-sm);
  /* The pad is paper, not a theme surface: the captured PNG seals into the
     printed POD, so it stays white with dark ink in either theme. */
  background: #fff;
  touch-action: none;
  cursor: crosshair;
}
.signature-pad-hint {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: var(--text-s, 12px);
  color: var(--ink-faint, #98a2ab);
  pointer-events: none;
}
.production-confirm-collect {
  grid-column: 1 / -1;
  display: flex !important;
  align-items: center;
  gap: 8px;
}

.cutplan {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 240px;
  gap: 12px;
  margin: 10px 0 14px;
}
.cutplan-canvas {
  min-width: 0;
  display: grid;
  gap: 10px;
}
.cutplan-bar-row,
.cutplan-sheet-card {
  margin: 0;
  display: grid;
  gap: 4px;
}
.cutplan-bar-row figcaption,
.cutplan-sheet-card figcaption {
  font-size: 0.78rem;
  color: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", monospace;
}
.cutplan-bar {
  display: block;
  width: 100%;
  height: auto;
}
.cutplan-piece-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
  font-size: 0.75rem;
}
.cutplan-piece-legend button {
  background: none;
  border: none;
  padding: 0;
  color: var(--theme-text-secondary);
  font: inherit;
  cursor: pointer;
  text-align: left;
}
.cutplan-piece-legend button:hover {
  color: var(--theme-text-primary);
}
.cutplan-piece-legend button.is-selected {
  color: var(--theme-accent);
  font-weight: 600;
}
.cutplan-sheets {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.cutplan-sheet {
  display: block;
  width: 320px;
  max-width: 100%;
  height: auto;
}
.cutplan-frame,
.cutplan-sheet-frame {
  fill: var(--theme-surface-card);
  stroke: var(--theme-border-subtle);
  stroke-width: 1;
}
.cutplan-cut rect,
.cutplan-nest rect {
  stroke-width: 1;
  cursor: pointer;
}
.cutplan-piece-pvc rect {
  fill: var(--member-pvc-fill);
  stroke: var(--member-pvc-edge);
}
.cutplan-piece-alu rect {
  fill: var(--member-aluminium-fill);
  stroke: var(--member-aluminium-edge);
}
.cutplan-piece-steel rect {
  fill: var(--member-panel-fill);
  stroke: var(--member-panel-edge);
}
.cutplan-nest rect {
  fill: var(--member-panel-fill);
  stroke: var(--member-panel-edge);
}
.cutplan-cut.is-member rect,
.cutplan-nest.is-member rect {
  stroke: var(--theme-accent);
  stroke-width: 1.6;
}
.cutplan-cut.is-selected rect,
.cutplan-nest.is-selected rect {
  stroke: var(--theme-mark);
  stroke-width: 2.2;
}
.cutplan-cut-id {
  font-size: 15px;
  font-weight: 600;
  fill: var(--theme-text-primary);
  font-family: "IBM Plex Mono", monospace;
}
.cutplan-cut-len {
  font-size: 13px;
  font-weight: 600;
  fill: var(--theme-text-secondary);
  font-family: "IBM Plex Mono", monospace;
}
.cutplan-miter-notch {
  fill: var(--theme-mark);
  opacity: 0.85;
}
.cutplan-nest text {
  font-size: 9px;
  fill: var(--theme-text-primary);
  font-family: "IBM Plex Mono", monospace;
  pointer-events: none;
}
.cutplan-cut text {
  pointer-events: none;
}
.cutplan-trim {
  fill: var(--theme-warning-soft);
  stroke: var(--theme-warning);
  stroke-width: 0.5;
}
.cutplan-remainder {
  fill: none;
  stroke: var(--theme-border-subtle);
  stroke-width: 0.6;
  stroke-dasharray: 3 3;
}
.cutplan-detail {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  background: var(--theme-surface-panel);
  padding: 10px 12px;
  align-self: start;
}
.cutplan-detail dl {
  margin: 0;
  display: grid;
  gap: 6px;
  font-size: 0.8rem;
}
.cutplan-detail dt {
  color: var(--theme-text-secondary);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.cutplan-detail dd {
  margin: 0;
  font-family: "IBM Plex Mono", monospace;
  word-break: break-word;
}
.cutplan-detail-empty {
  margin: 0;
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
@media (max-width: 860px) {
  .cutplan {
    grid-template-columns: 1fr;
  }
}
.production-glass {
  margin-top: 0.75rem;
  overflow-x: auto;
}
/* Operator-card tables (pieces/ops/cuts) scroll inside their section on
   narrow screens instead of pushing the whole card wider than the viewport. */
.operator-section,
div:has(> table.production-plan) {
  overflow-x: auto;
}
.production-glass-total td {
  font-weight: 600;
  border-top: 2px solid var(--theme-border-subtle);
}

.production-remnant-tag {
  color: var(--theme-accent-ink, #1d4e33);
  background: var(--theme-accent-soft, #e4f0e8);
  border: 1px solid var(--theme-accent, #2f6f4f);
  font-size: 0.78em;
  font-weight: 600;
  border-radius: 999px;
  padding: 0.05em 0.55em;
  white-space: nowrap;
}
.production-optimize-remnants,
.production-optimize-metrics {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 0.85rem;
  color: var(--theme-text-secondary);
  margin: 0.4rem 0 0;
}

.production-stock-reserve h4 {
  margin: 0 0 0.5em;
  font-size: 0.95em;
}
.production-stock-short {
  color: var(--theme-danger, #b3261e);
}
.production-stock-unmapped {
  color: var(--theme-warning, #b45309);
  font-size: 0.9em;
}

/* §11 work-order traceability */
.production-trace {
  margin-top: 1.25rem;
  border-top: 1px solid var(--line, #d9dce2);
  padding-top: 1rem;
}
.production-trace-chain {
  margin: 0 0 0.75rem;
  font-variant-numeric: tabular-nums;
  color: var(--text-dim, #5a6270);
}
.production-trace-plan table,
.production-trace-stock table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 0.75rem;
  font-size: 0.8125rem;
}
.production-trace-plan th,
.production-trace-stock th {
  text-align: left;
  font-weight: 600;
  padding: 0.25rem 0.5rem;
  border-bottom: 1px solid var(--line, #d9dce2);
}
.production-trace-plan td,
.production-trace-stock td {
  padding: 0.25rem 0.5rem;
  border-bottom: 1px solid var(--line-soft, #eceef2);
  font-variant-numeric: tabular-nums;
}
.production-trace-remnants,
.production-trace-matches {
  margin: 0.5rem 0 0;
  padding-left: 1.25rem;
  font-size: 0.8125rem;
  color: var(--text-dim, #5a6270);
}
.production-trace-lookup {
  display: flex;
  gap: 0.75rem;
  align-items: end;
  margin-top: 0.75rem;
}
.production-trace-lookup label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.8125rem;
  flex: 1;
  min-width: 0;
}
.production-trace-lookup input {
  font-family: var(--font-mono, ui-monospace, monospace);
  min-width: 0;
  width: 100%;
}
@media (max-width: 480px) {
  .production-trace-lookup {
    flex-wrap: wrap;
  }
  .production-trace-lookup label {
    flex-basis: 100%;
  }
}
.production-trace-empty {
  font-size: 0.8125rem;
  color: var(--text-dim, #5a6270);
}
/* Sidebar piece lookup (PM-M6): the control lives outside the order detail,
   so it takes the sidebar width and matches open the order on click. */
.production-orders .production-trace-lookup {
  margin: 0.5rem 0.75rem 0;
}
.production-trace-match {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: 6px;
}
.production-trace-match:hover,
.production-trace-match:focus-visible {
  color: var(--ink, #1c2027);
  outline: none;
  text-decoration: underline;
}

/* §12 operator step card */
.production-step-operator {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  font-weight: 600;
  color: var(--ink, #1d2530);
  cursor: pointer;
  text-align: left;
}
.production-step-operator:hover {
  text-decoration: underline;
}
.production-step.step-operator {
  outline: 2px solid var(--accent, #3156c5);
  outline-offset: 2px;
  border-radius: 4px;
}
.operator-card {
  margin-top: 1rem;
  border: 1px solid var(--line, #d9dce2);
  border-radius: 8px;
  padding: 1rem;
  background: var(--surface-raised, #fbfcfe);
}
.operator-card-head {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.operator-card-head h3 {
  margin: 0;
  font-size: 0.9375rem;
}
.operator-card-body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
/* Persistent primary action: the step's live transitions stay pinned to the
   bottom of the viewport while the card's materials/ops scroll beneath. */
.operator-card-actions {
  position: sticky;
  bottom: 0;
  margin: 0.75rem -1rem -1rem;
  padding: 0.6rem 1rem;
  border-top: 1px solid var(--line, #d9dce2);
  border-radius: 0 0 8px 8px;
  background: var(--surface-raised, #fbfcfe);
  display: flex;
  justify-content: flex-end;
  z-index: 2;
}
.operator-card-actions .production-step-actions {
  margin-left: 0;
}
.operator-card-actions .production-step-actions button {
  min-height: 44px;
  min-width: 110px;
  padding: 0.55rem 1rem;
  font-size: 0.95rem;
  font-weight: 600;
}
.operator-section h4 {
  margin: 0 0 0.375rem;
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-dim, #5a6270);
}
.operator-blockers {
  margin: 0;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--warning, #b45309);
  border-left-width: 4px;
  border-radius: 6px;
  background: var(--warning-soft, #fff7ed);
  color: var(--warning, #b45309);
  font-weight: 600;
  font-size: 0.8125rem;
}
.operator-remnants {
  margin: 0.5rem 0 0;
  padding-left: 1.25rem;
  font-size: 0.8125rem;
  color: var(--text-dim, #5a6270);
}
.operator-row-short td {
  background: var(--warning-soft, #fff7ed);
}
.operator-ops,
.operator-pieces {
  margin-bottom: 0.5rem;
  font-size: 0.8125rem;
}
.operator-summary {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--text-dim, #5a6270);
}

.production-prep {
  margin-bottom: 0.75rem;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-card, 10px);
  background: var(--theme-surface-raised, transparent);
}
.production-prep h3 {
  margin: 0 0 0.4rem;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--theme-text-secondary);
}
.production-prep ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}
.production-prep li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.85rem;
}
.production-prep-release {
  padding: 0.15rem 0.6rem;
  border-radius: var(--radius-pill);
  border: 1px solid var(--theme-accent);
  background: transparent;
  color: var(--theme-accent);
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
}
.production-prep-release:disabled {
  opacity: 0.5;
  cursor: default;
}
.production-station-queue {
  margin-bottom: 0.75rem;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-card, 10px);
}
.production-station-queue h3 {
  margin: 0 0 0.4rem;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--theme-text-secondary);
}
.production-station-queue > ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.production-station-queue li ul {
  list-style: none;
  margin: 0.25rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.production-station-counts {
  display: block;
  margin-left: 0.4rem;
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--theme-text-secondary);
}
.production-station-empty {
  margin: 0 0 0.75rem;
  padding: 0.6rem 0.75rem;
  border: 1px dashed var(--theme-border-subtle);
  border-radius: var(--radius-card, 10px);
  font-size: 0.82rem;
  color: var(--theme-text-secondary);
}
.production-station-empty button {
  margin-left: 0.4rem;
  padding: 0.15rem 0.6rem;
  border-radius: var(--radius-pill);
  border: 1px solid var(--theme-accent);
  background: transparent;
  color: var(--theme-accent);
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
}
.production-order-next {
  display: block;
  font-size: 0.72rem;
  color: var(--theme-text-secondary);
}

/* QC check ledger + entry form — large controls, high contrast for gloves. */
.operator-qc-ledger td strong {
  font-size: 0.78rem;
}
.qc-result-pass {
  color: var(--theme-success, #1a7f4b);
}
.qc-result-fail {
  color: var(--theme-danger, #b3261e);
}
.operator-qc-form {
  display: grid;
  grid-template-columns: minmax(90px, 0.8fr) 1.6fr 0.8fr 0.8fr auto auto;
  gap: 0.5rem;
  margin-top: 0.5rem;
  align-items: stretch;
}
.operator-qc-form select,
.operator-qc-form input {
  min-height: 44px;
  padding: 0.45rem 0.6rem;
  font-size: 0.9rem;
}
.operator-qc-form button {
  min-height: 44px;
  padding: 0.45rem 1rem;
  border-radius: var(--radius-sm, 6px);
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
}
.qc-submit-pass {
  border: 1px solid var(--theme-success, #1a7f4b);
  background: var(--theme-success, #1a7f4b);
  color: var(--theme-surface-panel);
}
.qc-submit-fail {
  border: 1px solid var(--theme-danger, #b3261e);
  background: transparent;
  color: var(--theme-danger, #b3261e);
}
.operator-qc-form button:disabled {
  opacity: 0.45;
  cursor: default;
}
@media (max-width: 900px) {
  .operator-qc-form {
    grid-template-columns: 1fr 1fr;
  }
}

.production-compare {
  background: transparent;
  border: 1px solid var(--theme-accent);
  color: var(--theme-accent);
}
.production-optimize-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.5rem 0;
  font-size: 0.8rem;
  color: var(--theme-text-secondary);
}
.production-optimize-stats strong {
  color: var(--theme-text);
  font-size: 0.85rem;
}
.production-optimize-inputs {
  margin: 0.4rem 0;
  font-size: 0.78rem;
  line-height: 1.45;
  color: var(--theme-text-secondary);
  max-width: 70ch;
}
.production-compare-table {
  margin-top: 0.4rem;
}
.production-compare-table .production-compare-best {
  background: color-mix(in srgb, var(--theme-success, #1a7f4b) 10%, transparent);
}
.production-compare-note {
  margin: 0.3rem 0 0.5rem;
  font-size: 0.75rem;
  color: var(--theme-text-secondary);
}

.production-making {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  align-items: baseline;
  font-size: 0.95rem;
  margin: 0.25rem 0 0.5rem;
  color: var(--theme-text-secondary);
}
.production-making strong {
  color: var(--theme-text);
  font-size: 1.05rem;
}
.production-making-location {
  color: var(--theme-accent);
}

.production-packing-missing {
  color: var(--theme-danger, #b3261e);
  font-weight: 600;
}

/* CNC readiness — per-member machining verdicts and programs. */
.cnc-panel {
  margin-top: 0.6rem;
  border: 1px solid var(--theme-border, #d8d4cd);
  border-radius: 8px;
  background: var(--theme-surface, #fff);
}
.cnc-panel-toggle {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem 0.75rem;
  background: none;
  border: none;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  color: var(--theme-text);
}
.cnc-panel-body {
  padding: 0.4rem 0.75rem 0.75rem;
  /* The members×machines grid is inherently wide — scroll it inside the
     panel instead of stretching the whole production page. */
  overflow-x: auto;
}
.cnc-empty {
  color: var(--theme-text-secondary);
  font-size: 0.85rem;
  margin: 0.25rem 0;
}
.cnc-error {
  color: var(--theme-danger, #b3261e);
  font-size: 0.85rem;
  margin: 0.25rem 0;
}
.cnc-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  table-layout: auto;
  min-width: 0;
}
.cnc-table th,
.cnc-table td {
  word-break: break-word;
}
.cnc-workspace-grid > div {
  min-width: 0;
  overflow-x: auto;
}
.cnc-member-meta {
  font-size: 0.75rem;
  color: var(--theme-text-muted, #6b675f);
}
.cnc-hint {
  font-size: 0.75rem;
  color: var(--theme-text-muted, #6b675f);
  margin: 0 0 0.35rem;
}
.cnc-required-tools {
  font-size: 0.8rem;
  color: var(--theme-text-muted, #6b675f);
  margin: 0.15rem 0 0.4rem;
}
.cnc-table th,
.cnc-table td {
  text-align: left;
  padding: 0.3rem 0.4rem;
  border-bottom: 1px solid var(--theme-border, #d8d4cd);
  vertical-align: top;
}
.cnc-member-label {
  background: none;
  border: none;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  padding: 0;
  color: var(--theme-accent);
  display: inline-flex;
  gap: 0.25rem;
  align-items: center;
}
.cnc-verdict {
  display: inline-block;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
}
.cnc-verdict-pass {
  background: color-mix(in srgb, var(--theme-success, #1a7f4b) 15%, transparent);
  color: var(--theme-success, #1a7f4b);
}
.cnc-verdict-warn {
  background: color-mix(in srgb, var(--theme-warning, #b26a00) 15%, transparent);
  color: var(--theme-warning, #b26a00);
}
.cnc-verdict-block {
  background: color-mix(in srgb, var(--theme-danger, #b3261e) 12%, transparent);
  color: var(--theme-danger, #b3261e);
}
.cnc-verdict-unverified {
  background: color-mix(in srgb, var(--theme-fg, #444) 10%, transparent);
  color: var(--theme-fg, #444);
}
.cnc-issues {
  margin: 0 0 0.75rem;
  padding: 0.55rem 0.9rem;
  border-left: 3px solid var(--theme-warning, #b26a00);
  background: color-mix(in srgb, var(--theme-warning, #b26a00) 8%, transparent);
  font-size: 0.85rem;
  line-height: 1.5;
  list-style: none;
}
.cnc-issues li + li {
  margin-top: 0.3rem;
}
.cnc-generate {
  margin-right: 0.4rem;
  font-size: 0.8rem;
}
.cnc-member-ops td {
  background: var(--theme-bg, #faf9f7);
}
.cnc-ops {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}
.cnc-ops th,
.cnc-ops td {
  padding: 0.2rem 0.4rem;
  border-bottom: 1px dashed var(--theme-border, #d8d4cd);
  text-align: left;
}
.cnc-programs {
  margin-top: 0.75rem;
}
.cnc-programs h4 {
  margin: 0 0 0.35rem;
  font-size: 0.85rem;
  color: var(--theme-text-secondary);
}
.cnc-programs ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.cnc-program {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.75rem;
  align-items: center;
  padding: 0.35rem 0;
  border-bottom: 1px solid var(--theme-border, #d8d4cd);
  font-size: 0.85rem;
}
.cnc-program-stale {
  opacity: 0.65;
}
.cnc-program-no {
  font-family: var(--font-mono, monospace);
  font-weight: 600;
}
.cnc-program-meta {
  color: var(--theme-text-secondary);
}
.cnc-stale {
  color: var(--theme-danger, #b3261e);
  font-weight: 600;
  font-size: 0.78rem;
}
.cnc-program-actions {
  margin-left: auto;
  display: flex;
  gap: 0.4rem;
}
.cnc-program-file {
  font-size: 0.78rem;
  padding: 0.15rem 0.5rem;
}

/* CNC workspace — machine + tool authority management. */
.cnc-workspace {
  margin-top: 0.75rem;
  border: 1px solid var(--theme-border, #d8d4cd);
  border-radius: 8px;
  background: var(--theme-surface, #fff);
}
.cnc-workspace-grid {
  display: grid;
  gap: 1rem;
}
.cnc-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.35rem;
}
.cnc-section-head h3 {
  margin: 0;
  font-size: 0.9rem;
}
.cnc-add {
  font-size: 0.8rem;
  padding: 0.2rem 0.6rem;
}
.cnc-form {
  margin-top: 0.5rem;
  padding: 0.6rem;
  border: 1px dashed var(--theme-border, #d8d4cd);
  border-radius: 6px;
  display: grid;
  gap: 0.5rem;
}
.cnc-form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 0.5rem;
}
.cnc-form-row label {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font-size: 0.78rem;
  color: var(--theme-text-secondary);
}
.cnc-form-group {
  border: none;
  padding: 0;
  margin: 0;
}
.cnc-form-group legend {
  font-size: 0.78rem;
  color: var(--theme-text-secondary);
  padding: 0;
}
.cnc-checks {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem 0.9rem;
  font-size: 0.8rem;
}
.cnc-checks label {
  display: inline-flex;
  gap: 0.3rem;
  align-items: center;
}
.cnc-form-actions {
  display: flex;
  gap: 0.5rem;
}

/* Member ops diagram — operator visual check before program generation. */
.cnc-diagram {
  margin: 0.35rem 0 0.6rem;
}
.cnc-diagram svg {
  width: 100%;
  max-width: 720px;
  display: block;
}
.cnc-diagram-datum {
  font-size: 10px;
  fill: var(--theme-text-secondary);
  font-weight: 600;
}
.cnc-diagram-datum-line {
  stroke: var(--theme-text-secondary);
  stroke-dasharray: 3 2;
  stroke-width: 1;
}
.cnc-diagram-bar {
  fill: var(--theme-surface-alt, #f1efe9);
  stroke: var(--theme-border, #d8d4cd);
  stroke-width: 1.5;
}
.cnc-diagram-op {
  cursor: pointer;
}
.cnc-diagram-op .cnc-mark {
  fill: var(--op-mark);
  stroke: var(--op-mark-edge);
  stroke-width: 1;
}
.cnc-diagram-op .cnc-mark-drill {
  fill: var(--op-drill);
  stroke: var(--op-drill-edge);
}
.cnc-diagram-op .cnc-mark-drainage {
  fill: var(--op-water);
  stroke: var(--op-water-edge);
}
.cnc-diagram-op .cnc-mark-ventilation {
  fill: var(--op-water);
  stroke: var(--op-water-edge);
}
.cnc-diagram-op .cnc-mark-slot {
  fill: var(--op-cut);
  stroke: var(--op-cut-edge);
}
.cnc-diagram-op .cnc-mark-routing {
  fill: var(--op-cut);
  stroke: var(--op-cut-edge);
}
.cnc-diagram-op .cnc-mark-milling {
  fill: var(--op-mill);
  stroke: var(--op-mill-edge);
}
.cnc-diagram-op .cnc-mark-edge {
  fill: var(--op-edge-work);
  stroke: var(--op-edge-work-edge);
}
.cnc-diagram-op .cnc-mark-custom {
  fill: var(--op-edge-work);
  stroke: var(--op-edge-work-edge);
}
.cnc-diagram-op .cnc-mark-hardware circle,
.cnc-diagram-op .cnc-mark-hardware line {
  fill: none;
  stroke: var(--op-hardware);
  stroke-width: 1.6;
}
.cnc-diagram-op.is-selected .cnc-mark,
.cnc-diagram-op.is-selected .cnc-mark-hardware circle,
.cnc-diagram-op.is-selected .cnc-mark-hardware line {
  stroke: var(--theme-danger);
  stroke-width: 2;
}
.cnc-diagram-seq {
  font-size: 9px;
  fill: var(--theme-text-secondary);
  pointer-events: none;
}
.cnc-diagram-legend {
  display: flex;
  gap: 1rem;
  font-size: 0.78rem;
  color: var(--theme-text-secondary);
  margin: 0.15rem 0 0;
}
.cnc-diagram-missing {
  color: var(--op-hardware);
}
.cnc-op-row {
  cursor: pointer;
}
.cnc-op-row.is-selected td {
  background: var(--op-selected-row);
}
.operator-member-strips {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin: 0.35rem 0 0.6rem;
}
.operator-member-strip {
  margin: 0;
}
.operator-member-strip svg {
  width: 100%;
  max-width: 640px;
  display: block;
}
.operator-member-strip figcaption {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--theme-text-secondary);
}
.operator-member-datum {
  font-size: 10px;
  fill: var(--theme-text-secondary);
  font-weight: 600;
}
.operator-member-datum-line {
  stroke: var(--theme-text-secondary);
  stroke-dasharray: 3 2;
  stroke-width: 1;
}
.operator-member-bar {
  fill: var(--theme-surface-alt, #f1efe9);
  stroke: var(--theme-border, #d8d4cd);
  stroke-width: 1.5;
}
.operator-member-op {
  stroke: var(--op-mark);
  stroke-width: 2;
}
.operator-member-seq {
  font-size: 9px;
  fill: var(--theme-text-secondary);
}

/* Customer-facing quote portal — a public surface, so it gets the same
   care as the app: quiet paper, one decision, no chrome. */

.portal-page {
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: clamp(1rem, 5vw, 4rem) var(--space-4);
  background: var(--theme-bg-canvas);
  color: var(--theme-text-primary);
}

.portal-card {
  width: min(38rem, 100%);
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-pop);
  padding: var(--space-6);
  display: grid;
  gap: var(--space-4);
}

.portal-card h1 {
  margin: 0;
  font-size: var(--text-display);
  font-weight: 600;
  letter-spacing: -0.01em;
}

.portal-card .eyebrow {
  margin: 0;
  font-size: var(--text-xs);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--theme-text-muted);
}

.portal-facts {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
  gap: var(--space-3) var(--space-4);
}

.portal-facts > div {
  display: grid;
  gap: var(--space-1);
}

.portal-facts dt {
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--theme-text-muted);
}

.portal-facts dd {
  margin: 0;
  font-size: var(--text-body);
  color: var(--theme-text-primary);
}

.portal-facts dd strong {
  font-size: var(--text-title);
}

.portal-doc {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  justify-self: start;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  color: var(--theme-accent-strong);
  font-weight: 500;
  text-decoration: none;
}

.portal-doc:hover {
  background: var(--theme-accent-soft);
  text-decoration: underline;
}

.portal-pay {
  display: inline-flex;
  align-items: center;
  justify-self: start;
  margin-top: var(--space-3);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  background: var(--theme-accent-strong);
  color: var(--theme-surface-panel);
  font-weight: 600;
  text-decoration: none;
}

.portal-pay:hover {
  background: var(--theme-accent);
  text-decoration: none;
}

.portal-decision__error {
  margin: 0;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
  font-size: var(--text-s);
}

.portal-decided {
  margin: 0;
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
  font-weight: 500;
}

/* Approval and decline must not look identical — success tints teal,
   decline stays neutral-warm so the states are legible at a glance. */
.portal-decided[data-state="declined"] {
  background: color-mix(in srgb, var(--theme-danger) 8%, var(--theme-surface-panel));
  color: var(--theme-text);
}

.portal-decided__contact {
  font-weight: 400;
  color: var(--theme-text-secondary);
  font-size: var(--text-s);
}

.portal-decision__notehint {
  margin: 0;
  font-size: var(--text-s);
  color: var(--theme-text-secondary);
}

/* A disabled decision button must not keep its hover styling — a dead
   green button reads as broken, not as a missing field. */
.portal-decision button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.portal-position__taxincl {
  font-size: var(--text-s);
  font-weight: 500;
  color: var(--theme-text-secondary);
}

.portal-decision {
  display: grid;
  gap: var(--space-3);
  border-top: 1px solid var(--theme-border-subtle);
  padding-top: var(--space-4);
}

.portal-decision label {
  font-size: var(--text-s);
  font-weight: 500;
  color: var(--theme-text-secondary);
}

.portal-decision input {
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
}

.portal-decision input:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 1px;
  border-color: var(--theme-accent);
}

.portal-code {
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
  font-size: 0.75rem;
}

/* §09 proposal layout — issuer-branded document, position cards with the
   §05 studio render, commercial summary, payment state, then the decision. */
.portal-proposal {
  width: min(62rem, 100%);
  display: grid;
  gap: var(--space-5);
}

.portal-proposal__head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-4);
  padding-bottom: var(--space-4);
  border-bottom: 2px solid var(--theme-accent);
}

.portal-proposal__org {
  margin: 0;
  font-size: var(--text-title);
  font-weight: 700;
  letter-spacing: -0.01em;
}

.portal-proposal__taxid {
  margin: var(--space-1) 0 0;
  font-size: var(--text-xs);
  color: var(--theme-text-muted);
}

.portal-proposal__logo {
  display: block;
  max-height: 56px;
  max-width: 220px;
  object-fit: contain;
}

.portal-proposal__notes {
  margin: var(--space-5) 0;
  padding: var(--space-4);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  background: var(--theme-surface-panel);
}

.portal-proposal__notes h2 {
  margin: 0 0 var(--space-2);
  font-size: var(--text-m);
}

.portal-proposal__notes p {
  margin: 0;
  color: var(--theme-text);
  white-space: pre-wrap;
}

.portal-proposal__refs {
  text-align: right;
}

.portal-proposal__refs h1 {
  margin: 0;
  font-size: var(--text-title);
  font-weight: 600;
  letter-spacing: -0.01em;
}

.portal-proposal__ref {
  margin: var(--space-1) 0 0;
  font-size: var(--text-s);
  color: var(--theme-text-secondary);
}

.portal-proposal__summary {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.portal-totals {
  margin: 0;
  display: flex;
  gap: var(--space-5);
  text-align: right;
}

.portal-totals dt {
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--theme-text-muted);
}

.portal-totals dd {
  margin: 0;
  font-size: var(--text-body);
}

.portal-totals__gross dd {
  font-size: var(--text-display);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.portal-proposal__positions h2 {
  margin: 0 0 var(--space-3);
  font-size: var(--text-s);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--theme-text-muted);
}

.portal-positions {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(18rem, 1fr));
  gap: var(--space-3);
}

.portal-position {
  display: grid;
  grid-template-columns: minmax(0, 7.5rem) 1fr;
  gap: var(--space-3);
  padding: var(--space-3);
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  align-items: start;
}

.portal-position__thumb {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  /* Studio backdrop — white PVC on near-white canvas washed the render out. */
  background:
    radial-gradient(120% 90% at 50% 25%, rgba(255, 255, 255, 0.75), transparent 62%),
    linear-gradient(180deg, var(--theme-surface-hover) 0%, var(--theme-border-subtle) 100%);
}

.portal-position__views {
  position: absolute;
  right: 4px;
  bottom: 4px;
  display: inline-flex;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  overflow: hidden;
  opacity: 0.92;
}

.portal-view-toggle {
  border: 0;
  background: transparent;
  padding: 2px 7px;
  font-size: 10px;
  font-weight: 600;
  color: var(--theme-text-muted);
  cursor: pointer;
}

.portal-view-toggle[data-active="true"] {
  background: var(--theme-accent);
  color: var(--theme-surface-panel);
}

.portal-position__count {
  margin-left: 6px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
  font-size: var(--text-xs);
  font-weight: 600;
}

.portal-position__thumb svg,
.portal-position__thumb img {
  display: block;
  width: 100%;
  height: auto;
}

.portal-position__id {
  margin: 0;
  font-weight: 600;
  font-size: var(--text-body);
}

.portal-position__typology {
  margin: 0;
  font-size: var(--text-xs);
  color: var(--theme-text-muted);
  font-family: "IBM Plex Mono", "JetBrains Mono", monospace;
}

.portal-position__facts {
  margin: var(--space-2) 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(7rem, 1fr));
  gap: var(--space-2) var(--space-4);
}

.portal-position__facts dt {
  font-size: var(--text-xs);
  color: var(--theme-text-muted);
}

.portal-position__facts dd {
  margin: 0;
  font-size: var(--text-s);
}

.portal-position__price {
  margin: 0;
  display: flex;
  justify-content: space-between;
  gap: var(--space-2);
  font-size: var(--text-s);
}

.portal-position__price span {
  color: var(--theme-text-muted);
}

.portal-position__unit {
  font-size: var(--text-xs);
  font-weight: 500;
}

.portal-proposal__commercial {
  display: flex;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
  padding: var(--space-4);
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
}

.portal-terms h3 {
  margin: 0 0 var(--space-1);
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--theme-text-muted);
}

.portal-terms p {
  margin: 0;
}

.portal-payment {
  margin: 0;
  display: flex;
  gap: var(--space-5);
  text-align: right;
}

.portal-payment dt {
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--theme-text-muted);
}

.portal-payment dd {
  margin: 0;
  font-size: var(--text-body);
}

.portal-payment__state {
  display: inline-block;
  padding: 0 var(--space-2);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: var(--text-s);
}

.portal-payment__state--pending {
  background: var(--theme-surface-raised);
  color: var(--theme-text-secondary);
}

.portal-payment__state--partial {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}

.portal-payment__state--paid {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

.portal-decision textarea {
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
  font: inherit;
  resize: vertical;
}

.portal-decision textarea:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 1px;
  border-color: var(--theme-accent);
}

.portal-proposal__brand {
  margin-top: var(--space-4);
  padding-top: var(--space-3);
  border-top: 1px solid var(--theme-border-subtle);
  font-size: var(--text-xs);
  color: var(--theme-text-muted);
  text-align: center;
  letter-spacing: 0.06em;
}

.portal-proposal .portal-decision {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
}

/* hero — the customer's own flagship unit rendered large under the masthead */
.portal-proposal__hero {
  margin: 0;
  display: grid;
  justify-items: center;
  gap: var(--space-2);
  padding: var(--space-4);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  background: var(--theme-surface-panel);
}

.portal-proposal__hero svg,
.portal-proposal__hero img,
.portal-proposal__hero canvas {
  display: block;
  max-height: 340px;
  max-width: 100%;
}

.portal-proposal__hero figcaption {
  font-size: var(--text-xs);
  color: var(--theme-text-muted);
}

/* decision recap — identity, total and validity next to the buttons, so the
   customer never approves without the number in view */
.portal-decision h2 {
  margin: 0;
  font-size: var(--text-m);
}

.portal-decision__recap {
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-accent);
  border-radius: var(--radius-md);
  background: var(--theme-surface-panel);
}

.portal-decision__recap dl {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: var(--space-2) var(--space-4);
}

.portal-decision__recap dt {
  font-size: var(--text-xs);
  color: var(--theme-text-muted);
}

.portal-decision__recap dd {
  margin: 0;
  font-size: var(--text-body);
  font-weight: 600;
}

.portal-decision__hint {
  margin: var(--space-2) 0 0;
  font-size: var(--text-s);
  color: var(--theme-text-secondary);
}

.portal-decided p {
  margin: 0;
}

.portal-decided__state {
  font-weight: 600;
  margin-bottom: var(--space-1) !important;
}

/* Decision progress — Propuesta → Decisión → Producción */
.portal-steps {
  display: flex;
  gap: var(--space-2);
  list-style: none;
  margin: var(--space-4) 0;
  padding: 0;
  counter-reset: portal-step;
}
.portal-step {
  flex: 1;
  position: relative;
  padding: var(--space-2) var(--space-3) var(--space-2) calc(var(--space-4) + 1.4rem);
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-m);
  font-size: var(--text-s);
  color: var(--theme-text-muted);
  counter-increment: portal-step;
}
.portal-step::before {
  content: counter(portal-step);
  position: absolute;
  left: var(--space-2);
  top: 50%;
  transform: translateY(-50%);
  width: 1.4rem;
  height: 1.4rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: var(--text-xs);
  font-weight: 600;
  background: var(--theme-canvas);
  color: var(--theme-text-muted);
}
.portal-step[data-state="done"] {
  border-color: var(--theme-accent);
  color: var(--theme-text);
}
.portal-step[data-state="done"]::before {
  content: "✓";
  background: var(--theme-accent);
  color: var(--theme-surface-panel);
}
.portal-step[data-state="current"] {
  border-color: var(--theme-accent);
  box-shadow: 0 0 0 1px var(--theme-accent);
  color: var(--theme-text);
  font-weight: 600;
}
.portal-step[data-state="current"]::before {
  background: var(--theme-accent);
  color: var(--theme-surface-panel);
}
.portal-step[data-state="declined"] {
  border-color: var(--theme-warning, #b45309);
  color: var(--theme-text);
}
.portal-step[data-state="declined"]::before {
  content: "↺";
  background: var(--theme-warning, #b45309);
  color: var(--theme-surface-panel);
}

/* The proposal is the one page the client opens on a phone — decision must
   stay reachable and readable at handset width (§20). */
@media (max-width: 640px) {
  .portal-proposal__head {
    flex-direction: column;
    gap: var(--space-3);
  }
  .portal-proposal__refs {
    text-align: left;
  }
  .portal-totals,
  .portal-payment {
    flex-wrap: wrap;
    gap: var(--space-4);
    text-align: left;
  }
  .portal-position {
    grid-template-columns: 1fr;
  }
  .portal-position__thumb {
    max-width: 16rem;
  }
  .portal-steps {
    flex-direction: column;
  }
  .portal-card {
    padding: var(--space-4);
  }
  .portal-proposal__hero svg,
  .portal-proposal__hero img,
  .portal-proposal__hero canvas {
    max-height: 220px;
  }
  .portal-page .projects-actions {
    flex-direction: column;
    align-items: stretch;
  }
}
